insert into public.exercises
  (id, name, category, type, body_part, equipment, muscle_group, target, secondary_muscles, instructions, image, gif_url, attribution)
values
(514, 'jump squat', 'upper legs', 'strength', 'upper legs', 'body weight', 'quadriceps', 'glutes', '["quadriceps","hamstrings","calves"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart. Lower your body into a squat position by bending your knees and pushing your hips back. Jump explosively off the ground, extending your hips, knees, and ankles. While in mid-air, quickly bring your arms forward for balance. Land softly on the balls of your feet and immediately go into the next repetition. Repeat for the desired number of repetitions.","it":"Stai con i piedi alla larghezza delle spalle. Abbassa il corpo in una posizione tozza piegando le ginocchia e spingendo indietro i fianchi. Salta in modo esplosivo da terra, estendendo i fianchi, le ginocchia e le caviglie. Mentre sei a mezz''aria, porta rapidamente le braccia in avanti per mantenere l''equilibrio. Atterra dolcemente sulle punte dei piedi e passa immediatamente alla ripetizione successiva. Ripetere per il numero di ripetizioni desiderato.","tr":"Ayaklarınız omuz genişliğinde açık olacak şekilde ayakta durun. Dizlerinizi bükerek ve kalçalarınızı geriye doğru iterek vücudunuzu çömelme pozisyonuna indirin. Kalçalarınızı, dizlerinizi ve ayak bileklerinizi uzatarak yerden patlayıcı bir şekilde zıplayın. Havadayken dengenizi sağlamak için kollarınızı hızla öne doğru getirin. Ayak parmaklarınızın üzerine yumuşak bir şekilde inin ve hemen bir sonraki tekrara geçin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Salta de forma explosiva desde el suelo, extendiendo las caderas, las rodillas y los tobillos. Mientras estás en el aire, lleva rápidamente los brazos hacia adelante para mantener el equilibrio. Aterriza suavemente sobre la punta de los pies y pasa de inmediato a la siguiente repetición. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч. Опустите тело в присед, согнув колени и отведя бедра назад. Резко подпрыгните от земли, выпрямляя бедра, колени и лодыжки. Находясь в воздухе, быстро вытяните руки вперед для равновесия. Мягко приземлитесь на подушечки стоп и сразу же переходите к следующему повторению. Повторите необходимое количество повторений.","zh":"双脚分开与肩同宽站立。 弯曲膝盖并将臀部向后推，将身体降低至蹲姿。 爆发性地跳离地面，伸展臀部、膝盖和脚踝。 在半空中时，快速将手臂向前伸以保持平衡。 脚掌轻轻落地，然后立即进入下一个重复动作。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं। अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए अपने शरीर को स्क्वाट स्थिति में लाएँ। अपने कूल्हों, घुटनों और टखनों को फैलाते हुए ज़मीन से तेज़ी से कूदें। मध्य हवा में रहते हुए, संतुलन के लिए अपनी भुजाओं को शीघ्रता से आगे लाएँ। अपने पैरों की उंगलियों पर धीरे से उतरें और तुरंत अगली पुनरावृत्ति पर जाएँ। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań ze stopami rozstawionymi na szerokość barków. Opuść ciało do przysiadu, uginając kolana i cofając biodra. Wyskocz eksplozywnie z podłogi, prostując biodra, kolana i stawy skokowe. Będąc w powietrzu, szybko wysuń ręce do przodu dla równowagi. Wyląduj miękko na palcach stóp i od razu przejdź do kolejnego powtórzenia. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"발을 어깨너비로 벌립니다. 무릎을 구부리고 엉덩이를 뒤로 밀면서 몸을 스쿼트 자세로 낮춥니다. 고관절, 무릎, 발목을 완전히 펼치면서 폭발적으로 바닥에서 뛰어올립니다. 공중에 있을 때 팔을 앞으로 빠르게 가져와 균형을 잡습니다. 발가락 끝으로 부드럽게 착지하고 즉시 다음 반복을 시작합니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules. Abaisse ton corps en position de squat en fléchissant tes genoux et en poussant tes hanches vers l''arrière. Saute du sol de manière explosive, en étendant tes hanches, tes genoux et tes chevilles. En plein saut, ramène rapidement tes bras vers l''avant pour l''équilibre. Atterris en douceur sur la pointe des pieds et enchaîne immédiatement avec la répétition suivante. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0514-LIlE5Tn.jpg', 'videos/0514-LIlE5Tn.gif', '© Gym visual — https://gymvisual.com/'),
(513, 'jump squat v. 2', 'upper legs', 'strength', 'upper legs', 'body weight', 'quadriceps', 'glutes', '["quadriceps","hamstrings","calves"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart. Lower your body into a squat position by bending your knees and pushing your hips back. Jump explosively, extending your hips and knees fully. Land softly on the balls of your feet and immediately lower your body back into a squat position. Repeat for the desired number of repetitions.","it":"Stai con i piedi alla larghezza delle spalle. Abbassa il corpo in una posizione tozza piegando le ginocchia e spingendo indietro i fianchi. Salta in modo esplosivo, estendendo completamente le anche e le ginocchia. Atterra dolcemente sulle punte dei piedi e riporta immediatamente il corpo in posizione tozza. Ripetere per il numero di ripetizioni desiderato.","tr":"Ayaklarınız omuz genişliğinde açık olacak şekilde ayakta durun. Dizlerinizi bükerek ve kalçalarınızı geriye doğru iterek vücudunuzu çömelme pozisyonuna indirin. Kalçalarınızı ve dizlerinizi tamamen uzatarak patlayıcı bir şekilde zıplayın. Ayak parmaklarınızın üzerine yumuşak bir şekilde inin ve hemen vücudunuzu tekrar çömelme pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Salta de forma explosiva, extendiendo por completo las caderas y las rodillas. Aterriza suavemente sobre la punta de los pies y de inmediato baja el cuerpo de nuevo a una posición de sentadilla. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч. Опустите тело в присед, согнув колени и отведя бедра назад. Прыгайте взрывно, полностью выпрямляя бедра и колени. Мягко приземлитесь на подушечки стоп и сразу же опустите тело обратно в присед. Повторите необходимое количество повторений.","zh":"双脚分开与肩同宽站立。 弯曲膝盖并将臀部向后推，将身体降低至蹲姿。 爆发力跳跃，充分伸展臀部和膝盖。 脚掌轻轻着地，然后立即将身体放回蹲姿。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं। अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए अपने शरीर को स्क्वाट स्थिति में लाएँ। अपने कूल्हों और घुटनों को पूरी तरह फैलाते हुए विस्फोटक तरीके से कूदें। अपने पैरों की उंगलियों पर धीरे से उतरें और तुरंत अपने शरीर को वापस स्क्वाट स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań ze stopami rozstawionymi na szerokość barków. Opuść ciało do przysiadu, uginając kolana i cofając biodra. Wyskocz eksplozywnie, w pełni prostując biodra i kolana. Wyląduj miękko na palcach stóp i od razu opuść ciało z powrotem do przysiadu. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"발을 어깨너비로 벌립니다. 무릎을 구부리고 엉덩이를 뒤로 밀면서 몸을 스쿼트 자세로 낮춥니다. 고관절과 무릎을 완전히 펼치면서 폭발적으로 뛰어올립니다. 발가락 끝으로 부드럽게 착지하고 즉시 스쿼트 자세로 내려갑니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules. Abaisse ton corps en position de squat en fléchissant tes genoux et en poussant tes hanches vers l''arrière. Saute de manière explosive, en étendant complètement tes hanches et tes genoux. Atterris en douceur sur la pointe des pieds et redescends immédiatement ton corps en position de squat. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0513-TDYiji6.jpg', 'videos/0513-TDYiji6.gif', '© Gym visual — https://gymvisual.com/'),
(517, 'kettlebell advanced windmill', 'waist', 'strength', 'waist', 'kettlebell', 'obliques', 'abs', '["obliques","shoulders"]'::jsonb, '{"en":"Stand with your feet wider than shoulder-width apart, toes pointing slightly outward. Hold a kettlebell in your right hand, with your arm extended overhead and your palm facing forward. Rotate your left foot slightly to the right, and shift your weight onto your left leg. Bend your left knee and hinge at the hip, lowering your torso towards the left side. Keep your right arm extended overhead and your eyes on the kettlebell. As you lower your torso, allow your right leg to straighten and your right foot to pivot slightly. Lower your torso until you feel a stretch in your left hamstring and your right arm is pointing towards the ground. Pause for a moment, then engage your core and push through your left heel to return to the starting position. Repeat for the desired number of repetitions, then switch sides.","it":"Stare con i piedi più larghi della larghezza delle spalle, con le dita rivolte leggermente verso l''esterno. Tieni un kettlebell nella mano destra, con il braccio teso sopra la testa e il palmo rivolto in avanti. Ruota leggermente il piede sinistro verso destra e sposta il peso sulla gamba sinistra. Piega il ginocchio sinistro e fai perno sull''anca, abbassando il busto verso il lato sinistro. Tieni il braccio destro esteso sopra la testa e gli occhi sul kettlebell. Mentre abbassi il busto, consenti alla gamba destra di raddrizzarsi e al piede destro di ruotare leggermente. Abbassa il busto finché non senti un allungamento nel tendine del ginocchio sinistro e il braccio destro punta verso il suolo. Fai una pausa per un momento, quindi coinvolgi il core e spingi attraverso il tallone sinistro per tornare alla posizione di partenza. Ripeti per il numero di ripetizioni desiderato, quindi cambia lato.","tr":"Ayaklarınız omuz genişliğinden daha geniş, ayak parmaklarınız hafifçe dışarı bakacak şekilde ayakta durun. Sağ elinizde bir kettlebell tutun, kolunuz yukarı doğru uzatılmış ve avucunuz öne bakacak şekilde. Sol ayağınızı hafifçe sağa çevirin ve ağırlığınızı sol bacağınıza verin. Sol dizinizi bükün ve kalçadan menteşeleyin, gövdenizi sol tarafa doğru indirin. Sağ kolunuzu başınızın üzerinde uzatın ve gözlerinizi kettlebell''in üzerinde tutun. Gövdenizi indirirken sağ bacağınızın düzleşmesine ve sağ ayağınızın hafifçe dönmesine izin verin. Sol hamstringinizde bir gerginlik hissedene ve sağ kolunuz yere bakana kadar gövdenizi indirin. Bir an duraklayın, ardından merkez bölgenizi devreye sokun ve başlangıç ​​pozisyonuna dönmek için sol topuğunuzu itin. İstenilen tekrar sayısı kadar tekrarlayın, ardından taraf değiştirin.","es":"Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera. Sostén una pesa rusa en la mano derecha, con el brazo extendido por encima de la cabeza y la palma hacia adelante. Gira el pie izquierdo ligeramente hacia la derecha y traslada el peso hacia la pierna izquierda. Dobla la rodilla izquierda y flexiona la cadera, bajando el torso hacia el lado izquierdo. Mantén el brazo derecho extendido por encima de la cabeza y la mirada en la pesa rusa. Mientras bajas el torso, permite que la pierna derecha se enderece y que el pie derecho gire ligeramente. Baja el torso hasta sentir un estiramiento en el isquiotibial izquierdo y que el brazo derecho apunte hacia el suelo. Haz una pausa breve, luego activa el core y empuja con el talón izquierdo para regresar a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.","ru":"Встаньте, поставив ноги шире ширины плеч, носки слегка направлены наружу. Возьмите гирю в правую руку, вытянув руку над головой и ладонью вперед. Слегка поверните левую ногу вправо и перенесите вес тела на левую ногу. Согните левое колено и согнитесь в бедре, опуская туловище влево. Держите правую руку вытянутой над головой и смотрите на гирю. Опуская туловище, позвольте правой ноге выпрямиться, а правой ступне слегка повернуться. Опускайте туловище до тех пор, пока не почувствуете растяжение левого задней поверхности бедра и правую руку, направленную к земле. Сделайте паузу на мгновение, затем задействуйте корпус и толкните левую пятку, чтобы вернуться в исходное положение. Повторите желаемое количество повторений, затем поменяйте сторону.","zh":"站立，双脚分开比肩宽，脚趾稍微向外。 右手握住壶铃，手臂伸过头顶，手掌朝前。 将左脚稍微向右旋转，并将重量转移到左腿上。 弯曲左膝并铰接在臀部，将躯干向左侧降低。 保持右臂伸过头顶，眼睛盯着壶铃。 当你降低躯干时，让右腿伸直，右脚稍微转动。 降低躯干，直到感觉到左腿筋拉伸并且右臂指向地面。 暂停片刻，然后启动核心并推动左脚跟返回到起始位置。 重复所需的重复次数，然后换边。","hi":"अपने पैरों को कंधे की चौड़ाई से अधिक चौड़ा करके खड़े रहें, पैर की उंगलियां थोड़ी बाहर की ओर हों। अपने दाहिने हाथ में केटलबेल पकड़ें, अपना हाथ ऊपर की ओर फैलाएं और अपनी हथेली आगे की ओर रखें। अपने बाएं पैर को थोड़ा दाहिनी ओर घुमाएं, और अपना वजन अपने बाएं पैर पर डालें। अपने बाएं घुटने को मोड़ें और कूल्हे पर टिकाएं, अपने धड़ को बाईं ओर नीचे करें। अपने दाहिने हाथ को ऊपर की ओर फैलाकर रखें और अपनी आँखें केटलबेल पर रखें। जैसे ही आप अपना धड़ नीचे करते हैं, अपने दाहिने पैर को सीधा होने दें और अपने दाहिने पैर को थोड़ा घूमने दें। अपने धड़ को तब तक नीचे करें जब तक आपको अपने बाएं हैमस्ट्रिंग में खिंचाव महसूस न हो और आपका दाहिना हाथ जमीन की ओर न हो जाए। एक पल के लिए रुकें, फिर अपने कोर को संलग्न करें और प्रारंभिक स्थिति में लौटने के लिए अपनी बाईं एड़ी से धक्का दें। दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।","pl":"Stań ze stopami rozstawionymi szerzej niż barki, palce stóp skierowane lekko na zewnątrz. Trzymaj kettlebell w prawej dłoni, ramię wyciągnięte nad głowę, dłoń skierowana do przodu. Obróć lewą stopę lekko w prawo i przenieś ciężar ciała na lewą nogę. Ugnij lewe kolano i wykonaj skłon w biodrach, opuszczając tułów w lewą stronę. Trzymaj prawe ramię wyciągnięte nad głowę i wzrok skierowany na kettlebell. Podczas opuszczania tułowia pozwól prawej nodze się wyprostować, a prawej stopie lekko się obrócić. Opuszczaj tułów, aż poczujesz rozciąganie w lewym mięśniu dwugłowym uda, a prawe ramię będzie skierowane w stronę podłogi. Zatrzymaj się na chwilę, a następnie napnij mięśnie brzucha i odepchnij się przez lewą piętę, wracając do pozycji wyjściowej. Powtórz zgodnie z zaplanowaną liczbą powtórzeń, a następnie zmień stronę.","ko":"발을 어깨너비보다 넓게 벌리고 발끝을 약간 바깥쪽으로 향합니다. 오른손에 케틀벨을 잡으면서 팔을 머리 위로 펼치고 손바닥이 앞을 향하도록 합니다. 왼발을 약간 오른쪽으로 회전시키고 체중을 왼다리에 옮깁니다. 왼쪽 무릎을 구부리고 고관절을 경첨하면서 상체를 왼쪽으로 낮춥니다. 오른팔을 머리 위에서 펼친 상태로 유지하고 케틀벨을 봅니다. 상체를 내리면서 오른다리를 펼치고 오른발을 약간 회전시킵니다. 왼쪽 햄스트링에서 스트레치를 느끼고 오른팔이 땅을 향할 때까지 상체를 낮춥니다. 잠시 멈춘 후 코어를 수축시키고 왼발꿈치를 밀어 시작 자세로 돌아옵니다. 원하는 반복 횟수만큼 반복한 후 반대쪽으로 전환합니다.","fr":"Tiens-toi debout, les pieds plus écartés que la largeur des épaules, les orteils légèrement tournés vers l''extérieur. Tiens un kettlebell dans la main droite, le bras étendu au-dessus de la tête et la paume tournée vers l''avant. Fais tourner légèrement ton pied gauche vers la droite, et transfère ton poids sur ta jambe gauche. Fléchis ton genou gauche et bascule au niveau de la hanche en abaissant ton torse vers le côté gauche. Garde le bras droit tendu au-dessus de la tête et les yeux sur le kettlebell. En abaissant ton torse, laisse ta jambe droite se tendre et ton pied droit pivoter légèrement. Abaisse ton torse jusqu''à ressentir un étirement dans ton ischio-jambier gauche et jusqu''à ce que ton bras droit pointe vers le sol. Marque une pause, puis gaine ta sangle abdominale et pousse sur ton talon gauche pour revenir à la position de départ. Répète le nombre de répétitions souhaité, puis change de côté."}'::jsonb, 'images/0517-Kal9cQQ.jpg', 'videos/0517-Kal9cQQ.gif', '© Gym visual — https://gymvisual.com/'),
(518, 'kettlebell alternating hang clean', 'lower arms', 'strength', 'lower arms', 'kettlebell', 'shoulders', 'forearms', '["shoulders","traps","core"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up. Allow the kettlebells to hang in front of your body with your arms fully extended. In one fluid motion, explosively extend your hips, shrug your shoulders, and pull the kettlebells up towards your shoulders. As the kettlebells reach shoulder height, rotate your wrists and catch the kettlebells in the rack position, with your palms facing inward and the kettlebells resting on the outside of your forearms. Lower the kettlebells back down to the starting position and repeat the movement with the opposite arm. Continue alternating arms for the desired number of repetitions.","it":"Stai con i piedi alla larghezza delle spalle, tenendo un kettlebell in ciascuna mano con una presa prona. Piega leggermente le ginocchia e fai perno in avanti sui fianchi, mantenendo la schiena dritta e il petto in alto. Lascia che i kettlebell pendano davanti al tuo corpo con le braccia completamente estese. Con un movimento fluido, estendi in modo esplosivo i fianchi, alza le spalle e tira i kettlebell verso le spalle. Quando i kettlebell raggiungono l''altezza delle spalle, ruota i polsi e afferra i kettlebell nella posizione di rack, con i palmi rivolti verso l''interno e i kettlebell appoggiati all''esterno degli avambracci. Abbassare nuovamente i kettlebell nella posizione iniziale e ripetere il movimento con il braccio opposto. Continua ad alternare le braccia per il numero di ripetizioni desiderato.","tr":"Ayaklarınızı omuz genişliğinde açın ve her iki elinizde birer kettlebell''i üstten kavrayarak tutun. Dizlerinizi hafifçe bükün ve kalçalarınızdan öne doğru eğilin, sırtınızı düz ve göğsünüzü yukarıda tutun. Kollarınız tamamen uzatılmış halde kettlebell''lerin vücudunuzun önünde asılı kalmasına izin verin. Tek bir akıcı hareketle kalçalarınızı patlayıcı bir şekilde uzatın, omuzlarınızı silkin ve kettlebell''leri omuzlarınıza doğru çekin. Kettlebell''ler omuz yüksekliğine ulaştığında, bileklerinizi döndürün ve kettlebell''leri, avuçlarınız içe bakacak ve kettlebell''ler ön kollarınızın dışına bakacak şekilde raf pozisyonunda yakalayın. Kettlebell''leri başlangıç ​​pozisyonuna indirin ve hareketi diğer kolunuzla tekrarlayın. İstenilen sayıda tekrar için kolları değiştirerek devam edin.","es":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano con agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Deja que las pesas rusas cuelguen frente al cuerpo con los brazos completamente extendidos. En un solo movimiento fluido, extiende las caderas de forma explosiva, encoge los hombros y tira de las pesas rusas hacia los hombros. Cuando las pesas rusas alcancen la altura de los hombros, gira las muñecas y atrápalas en posición de descanso, con las palmas hacia adentro y las pesas rusas apoyadas en la parte externa de los antebrazos. Baja las pesas rusas de nuevo a la posición inicial y repite el movimiento con el brazo opuesto. Continúa alternando los brazos durante el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, возьмите в каждую руку по гире хватом сверху. Слегка согните колени и наклонитесь вперед в бедрах, держа спину прямо и грудь вверх. Позвольте гирям висеть перед вашим телом, полностью вытянув руки. Одним плавным движением резко выпрямите бедра, пожмите плечами и подтяните гири к плечам. Когда гири достигнут высоты плеч, поверните запястья и поймайте гири в положении стойки, ладонями внутрь, а гирями — на внешней стороне предплечий. Опустите гири обратно в исходное положение и повторите движение противоположной рукой. Продолжайте чередовать руки желаемое количество повторений.","zh":"双脚分开与肩同宽站立，双手各握一个壶铃，正手握住。 稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。 让壶铃悬挂在身体前方，双臂完全伸展。 以一种流畅的动作，爆发性地伸展臀部，耸肩，并将壶铃拉向肩膀。 当壶铃到达肩膀高度时，旋转手腕并将壶铃抓住在架子位置，手掌朝内，壶铃放在前臂外侧。 将壶铃放回起始位置，然后用另一只手臂重复该动作。 继续交替手臂进行所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में केटलबेल को ओवरहैंड पकड़ के साथ पकड़ें। अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ सीधी और छाती ऊपर रखें। अपनी बाहों को पूरी तरह फैलाकर केटलबेल्स को अपने शरीर के सामने लटकने दें। एक तरल गति में, अपने कूल्हों को तेजी से फैलाएं, अपने कंधों को सिकोड़ें, और केटलबेल्स को अपने कंधों की ओर ऊपर खींचें। जैसे ही केटलबेल कंधे की ऊँचाई तक पहुँचें, अपनी कलाइयों को घुमाएँ और केटलबेल को रैक स्थिति में पकड़ें, आपकी हथेलियाँ अंदर की ओर हों और केटलबेल आपके अग्रबाहु के बाहर की ओर टिकी हुई हों। केटलबेल्स को वापस प्रारंभिक स्थिति में लाएँ और विपरीत भुजा से इस क्रिया को दोहराएँ। दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w każdej dłoni nachwytem. Ugnij lekko kolana i wykonaj skłon w biodrach, utrzymując proste plecy i uniesioną klatkę piersiową. Pozwól, aby kettlebelle zwisały przed ciałem z całkowicie wyprostowanymi ramionami. Jednym płynnym ruchem eksplozywnie wyprostuj biodra, unieś ramiona w barkach i podciągnij kettlebelle w stronę barków. Gdy kettlebelle osiągną wysokość barków, obróć nadgarstki i złap je w pozycji podpartej, dłońmi skierowanymi do wewnątrz, kettlebelle opierając na zewnętrznej stronie przedramion. Opuść kettlebelle z powrotem do pozycji wyjściowej i powtórz ruch drugą ręką. Kontynuuj naprzemienne wykonywanie ruchu zgodnie z zaplanowaną liczbą powtórzeń.","ko":"발을 어깨너비로 벌려 서서 각 손에 케틀벨을 손아등그립으로 잡습니다. 무릎을 약간 구부리고 고관절을 경첨하면서 앞으로 숙입니다. 등을 곧게 유지하고 가슴을 올립니다. 케틀벨이 팔이 완전히 펼쳐진 상태로 몸 앞에 매달리도록 합니다. 한 동작으로 고관절을 폭발적으로 펼치고 어깨를 으쓱하면서 케틀벨을 어깨 쪽으로 위로 당깁니다. 케틀벨이 어깨 높이에 도달하면 손목을 회전시켜 케틀벨을 랙 자세로 잡으면서 손바닥이 안쪽을 향하고 케틀벨이 팔뚝의 바깥쪽에 올려집니다. 케틀벨을 시작 자세로 내려놓고 반대쪽 팔로 동작을 반복합니다. 양쪽을 번갈아가며 원하는 반복 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell dans chaque main en prise pronation. Fléchis légèrement les genoux et bascule vers l''avant au niveau des hanches en gardant le dos droit et la poitrine relevée. Laisse les kettlebells pendre devant ton corps, les bras complètement étendus. En un mouvement fluide, étends de manière explosive tes hanches, hausse les épaules et tire les kettlebells vers tes épaules. Lorsque les kettlebells atteignent la hauteur des épaules, fais pivoter tes poignets et réceptionne les kettlebells en position rack, les paumes tournées vers l''intérieur et les kettlebells reposant sur l''extérieur de tes avant-bras. Abaisse les kettlebells jusqu''à la position de départ et répète le mouvement avec le bras opposé. Continue à alterner les bras pour le nombre de répétitions souhaité."}'::jsonb, 'images/0518-I4tibZG.jpg', 'videos/0518-I4tibZG.gif', '© Gym visual — https://gymvisual.com/'),
(520, 'kettlebell alternating press', 'shoulders', 'strength', 'shoulders', 'kettlebell', 'triceps', 'delts', '["triceps","core"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height. Press one kettlebell overhead, fully extending your arm. Lower the kettlebell back to shoulder height. Repeat with the other arm. Continue alternating arms for the desired number of repetitions.","it":"Stare con i piedi alla larghezza delle spalle, tenendo un kettlebell in ciascuna mano all''altezza delle spalle. Premi un kettlebell sopra la testa, estendendo completamente il braccio. Abbassare il kettlebell all''altezza delle spalle. Ripeti con l''altro braccio. Continua ad alternare le braccia per il numero di ripetizioni desiderato.","tr":"Ayaklarınızı omuz genişliğinde açın ve her iki elinizde de omuz hizasında birer kettlebell tutun. Kolunuzu tamamen uzatarak bir kettlebell''i başınızın üzerine bastırın. Kettlebell''i omuz yüksekliğine kadar indirin. Diğer kolla tekrarlayın. İstenilen sayıda tekrar için kolları değiştirerek devam edin.","es":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros. Empuja una pesa rusa por encima de la cabeza, extendiendo el brazo por completo. Baja la pesa rusa de nuevo a la altura de los hombros. Repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, держа в каждой руке по гире на уровне плеч. Выжмите одну гирю над головой, полностью выпрямляя руку. Опустите гирю обратно на высоту плеч. Повторите с другой рукой. Продолжайте чередовать руки желаемое количество повторений.","zh":"双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高。 将一只壶铃按过头顶，完全伸展手臂。 将壶铃降低至肩膀高度。 用另一只手臂重复上述步骤。 继续交替手臂进行所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में कंधे की ऊंचाई पर केटलबेल पकड़ें। अपनी बांह को पूरी तरह फैलाते हुए एक केटलबेल को ऊपर की ओर दबाएं। केटलबेल को वापस कंधे की ऊँचाई तक नीचे लाएँ। दूसरे हाथ से दोहराएँ. दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w każdej dłoni na wysokości barków. Wypchnij jeden kettlebell nad głowę, w pełni prostując ramię. Opuść kettlebell z powrotem na wysokość barku. Powtórz drugą ręką. Kontynuuj naprzemienne wykonywanie ruchu zgodnie z zaplanowaną liczbą powtórzeń.","ko":"발을 어깨너비로 벌려 서서 각 손에 케틀벨을 어깨 높이에 잡습니다. 한쪽 케틀벨을 머리 위로 밀면서 팔을 완전히 펼칩니다. 케틀벨을 어깨 높이로 낮춥니다. 반대쪽 팔로 반복합니다. 양쪽을 번갈아가며 원하는 반복 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell dans chaque main à hauteur d''épaule. Développe un kettlebell au-dessus de ta tête, en tendant complètement ton bras. Abaisse le kettlebell à hauteur des épaules. Répète avec l''autre bras. Continue à alterner les bras pour le nombre de répétitions souhaité."}'::jsonb, 'images/0520-5KLbZWx.jpg', 'videos/0520-5KLbZWx.gif', '© Gym visual — https://gymvisual.com/'),
(519, 'kettlebell alternating press on floor', 'chest', 'strength', 'chest', 'kettlebell', 'shoulders', 'pectorals', '["shoulders","triceps"]'::jsonb, '{"en":"Start by lying on your back on the floor with your knees bent and feet flat on the ground. Hold a kettlebell in each hand, with your palms facing towards your feet and your arms extended straight up towards the ceiling. Lower one kettlebell down towards your shoulder while keeping the other kettlebell extended straight up. Press the lowered kettlebell back up to the starting position while simultaneously lowering the other kettlebell down towards your shoulder. Continue alternating the press motion with each kettlebell for the desired number of repetitions.","it":"Inizia sdraiandoti sulla schiena sul pavimento con le ginocchia piegate e i piedi appoggiati a terra. Tieni un kettlebell in ciascuna mano, con i palmi rivolti verso i piedi e le braccia tese verso il soffitto. Abbassa un kettlebell verso la spalla mantenendo l''altro kettlebell esteso verso l''alto. Spingi nuovamente il kettlebell abbassato nella posizione iniziale e contemporaneamente abbassa l''altro kettlebell verso la spalla. Continua ad alternare il movimento di press con ciascun kettlebell per il numero desiderato di ripetizioni.","tr":"Dizleriniz bükülmüş ve ayaklarınız yere düz basacak şekilde yere sırt üstü yatarak başlayın. Avuç içleriniz ayaklarınıza bakacak ve kollarınız tavana doğru uzatılacak şekilde her iki elinizde birer kettlebell tutun. Bir kettlebell''i omzunuza doğru indirin ve diğer kettlebell''i düz bir şekilde yukarı doğru uzatın. İndirdiğiniz kettlebell''i tekrar başlangıç ​​pozisyonuna doğru bastırın, aynı anda diğer kettlebell''i omzunuza doğru indirin. İstenilen tekrar sayısı için her kettlebell ile basma hareketini değiştirmeye devam edin.","es":"Comienza acostado boca arriba en el suelo con las rodillas dobladas y los pies planos sobre el suelo. Sostén una pesa rusa en cada mano, con las palmas hacia los pies y los brazos extendidos rectos hacia el techo. Baja una pesa rusa hacia el hombro mientras mantienes la otra pesa rusa extendida recta hacia arriba. Empuja la pesa rusa bajada de vuelta hacia la posición inicial mientras al mismo tiempo bajas la otra pesa rusa hacia el hombro. Continúa alternando el movimiento de empuje con cada pesa rusa durante el número de repeticiones deseado.","ru":"Начните с того, что лягте на спину на пол, согните колени и поставьте ступни на землю. Возьмите в каждую руку по гире, ладонями к ногам, а руками вытянутыми вверх к потолку. Опустите одну гирю вниз к плечу, удерживая другую гирю вытянутой прямо вверх. Верните опущенную гирю в исходное положение, одновременно опуская другую гирю вниз к плечу. Продолжайте чередовать движения жима каждой гири желаемое количество повторений.","zh":"首先仰卧在地板上，膝盖弯曲，双脚平放在地面上。 每只手握住一个壶铃，手掌朝向脚部，手臂伸直向天花板。 将一个壶铃向肩膀方向降低，同时保持另一个壶铃向上伸直。 将降低的壶铃按回到起始位置，同时将另一个壶铃向肩膀方向降低。 继续用每个壶铃交替进行推举动作，达到所需的重复次数。","hi":"अपने घुटनों को मोड़कर और पैरों को जमीन पर सपाट रखते हुए अपनी पीठ के बल फर्श पर लेटकर शुरुआत करें। प्रत्येक हाथ में केटलबेल पकड़ें, आपकी हथेलियाँ आपके पैरों की ओर हों और आपकी भुजाएँ छत की ओर सीधी फैली हुई हों। एक केटलबेल को अपने कंधे की ओर नीचे करें जबकि दूसरे केटलबेल को सीधा ऊपर की ओर फैलाकर रखें। निचली केटलबेल को वापस प्रारंभिक स्थिति में दबाएं, साथ ही साथ दूसरी केटलबेल को अपने कंधे की ओर नीचे करें। दोहराव की वांछित संख्या के लिए प्रत्येक केटलबेल के साथ प्रेस गति को बारी-बारी से जारी रखें।","pl":"Połóż się na plecach na podłodze z ugiętymi kolanami i stopami płasko opartymi o podłogę. Trzymaj kettlebell w każdej dłoni, dłonie skierowane w stronę stóp, ramiona wyprostowane prosto w kierunku sufitu. Opuść jeden kettlebell w stronę barku, utrzymując drugi kettlebell wyprostowany w górze. Wypchnij opuszczony kettlebell z powrotem do pozycji wyjściowej, jednocześnie opuszczając drugi kettlebell w stronę barku. Kontynuuj naprzemienne wypychanie kettlebelli zgodnie z zaplanowaną liczbą powtórzeń.","ko":"무릎을 구부리고 발을 바닥에 대고 바닥에 등을 대고 누워집니다. 각 손에 케틀벨을 잡으면서 손바닥이 발 쪽을 향하고 팔이 천장을 향해 완전히 펼쳐진 상태로 누워집니다. 한쪽 케틀벨을 어깨 쪽으로 내리면서 다른 한쪽 케틀벨은 완전히 펼친 상태로 유지합니다. 내려진 케틀벨을 시작 자세로 다시 밀어 올리면서 동시에 다른 한쪽 케틀벨을 어깨 쪽으로 내립니다. 각 케틀벨과 교대로 프레스 동작을 계속하여 원하는 반복 횟수만큼 반복합니다.","fr":"Commence allongé sur le dos sur le sol, les genoux fléchis et les pieds à plat sur le sol. Tiens un kettlebell dans chaque main, les paumes tournées vers tes pieds et les bras étendus droit vers le plafond. Abaisse un kettlebell vers ton épaule tout en gardant l''autre kettlebell tendu droit vers le haut. Repousse le kettlebell abaissé vers le haut jusqu''à la position de départ tout en abaissant simultanément l''autre kettlebell vers ton épaule. Continue à alterner le mouvement de développé avec chaque kettlebell pour le nombre de répétitions souhaité."}'::jsonb, 'images/0519-7w6i0vE.jpg', 'videos/0519-7w6i0vE.gif', '© Gym visual — https://gymvisual.com/'),
(521, 'kettlebell alternating renegade row', 'back', 'strength', 'back', 'kettlebell', 'core', 'upper back', '["core","shoulders"]'::jsonb, '{"en":"Start in a high plank position with your hands gripping the kettlebells and your feet hip-width apart. Engage your core and keep your body in a straight line from head to heels. Pull one kettlebell up towards your chest, keeping your elbow close to your body. Lower the kettlebell back down to the starting position and repeat with the other arm. Continue alternating arms for the desired number of repetitions.","it":"Inizia in una posizione di plancia alta con le mani che afferrano i kettlebell e i piedi alla larghezza delle anche. Coinvolgi il tuo core e mantieni il corpo in linea retta dalla testa ai talloni. Tira un kettlebell verso il petto, mantenendo il gomito vicino al corpo. Abbassare nuovamente il kettlebell nella posizione iniziale e ripetere con l''altro braccio. Continua ad alternare le braccia per il numero di ripetizioni desiderato.","tr":"Elleriniz kettlebell''leri kavrayarak ve ayaklarınız kalça genişliğinde açık olacak şekilde yüksek bir plank pozisyonuyla başlayın. Merkez bölgenizi harekete geçirin ve vücudunuzu baştan topuklara kadar düz bir çizgide tutun. Dirseğinizi vücudunuza yakın tutarak kettlebell''lerden birini göğsünüze doğru çekin. Kettlebell''i tekrar başlangıç ​​pozisyonuna indirin ve hareketi diğer kolunuzla tekrarlayın. İstenilen sayıda tekrar için kolları değiştirerek devam edin.","es":"Comienza en posición de plancha alta con las manos sujetando las pesas rusas y los pies separados a la altura de las caderas. Activa el core y mantén el cuerpo en línea recta desde la cabeza hasta los talones. Tira de una pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo. Baja la pesa rusa de nuevo a la posición inicial y repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.","ru":"Начните с позиции высокой планки, держа руками гири и расставив ноги на ширине плеч. Напрягите корпус и держите тело на прямой линии от головы до пяток. Подтяните одну гирю к груди, держа локоть близко к телу. Опустите гирю обратно в исходное положение и повторите то же самое с другой рукой. Продолжайте чередовать руки желаемое количество повторений.","zh":"从高平板支撑位置开始，双手握住壶铃，双脚分开与臀部同宽。 收紧核心肌群，保持身体从头到脚跟呈一条直线。 将一个壶铃向上拉向胸部，保持肘部靠近身体。 将壶铃放回起始位置，然后用另一只手臂重复该动作。 继续交替手臂进行所需的重复次数。","hi":"अपने हाथों से केटलबेल्स को पकड़कर और अपने पैरों को कूल्हे-चौड़ाई से अलग करके एक उच्च तख़्त स्थिति में शुरुआत करें। अपने कोर को व्यस्त रखें और अपने शरीर को सिर से एड़ी तक एक सीधी रेखा में रखें। अपनी कोहनी को अपने शरीर के पास रखते हुए, एक केटलबेल को अपनी छाती की ओर खींचें। केटलबेल को वापस प्रारंभिक स्थिति में लाएँ और दूसरे हाथ से दोहराएँ। दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।","pl":"Zacznij w wysokiej podporze przodem z dłońmi trzymającymi kettlebelle i stopami rozstawionymi na szerokość bioder. Napnij mięśnie brzucha i utrzymuj ciało w linii prostej od głowy do pięt. Podciągnij jeden kettlebell w stronę klatki piersiowej, trzymając łokieć blisko ciała. Opuść kettlebell z powrotem do pozycji wyjściowej i powtórz drugą ręką. Kontynuuj naprzemienne wykonywanie ruchu zgodnie z zaplanowaną liczbą powtórzeń.","ko":"양손으로 케틀벨을 잡고 높은 플랑크 자세를 취합니다. 몸을 머리부터 발꿈치까지 일직선으로 유지하면서 코어에 힘을 줍니다. 팔꿈치를 몸에 붙인 상태로 한 쪽 케틀벨을 가슴 쪽으로 당깁니다. 케틀벨을 처음 위치로 낮추고 다른 팔로 반복합니다. 원하는 반복 횟수까지 팔을 교대로 계속 움직입니다.","fr":"Commence en position de planche haute, les mains agrippant les kettlebells et les pieds écartés à la largeur des hanches. Gaine ta sangle abdominale et garde ton corps en ligne droite de la tête aux talons. Tire un kettlebell vers ta poitrine, en gardant ton coude près de ton corps. Abaisse le kettlebell jusqu''à la position de départ et répète avec l''autre bras. Continue à alterner les bras pour le nombre de répétitions souhaité."}'::jsonb, 'images/0521-b9kqlBy.jpg', 'videos/0521-b9kqlBy.gif', '© Gym visual — https://gymvisual.com/'),
(522, 'kettlebell alternating row', 'back', 'strength', 'back', 'kettlebell', 'biceps', 'upper back', '["biceps","forearms"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body. Bend forward at the hips, keeping your back straight and your core engaged. Pull one kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together. Lower the kettlebell back down to the starting position and repeat with the other arm. Continue alternating arms for the desired number of repetitions.","it":"Stare con i piedi alla larghezza delle spalle, le ginocchia leggermente piegate e tenere un kettlebell in ciascuna mano con i palmi rivolti verso il corpo. Piegati in avanti sui fianchi, mantenendo la schiena dritta e il core impegnato. Tira un kettlebell verso il petto, mantenendo il gomito vicino al corpo e stringendo insieme le scapole. Abbassare nuovamente il kettlebell nella posizione iniziale e ripetere con l''altro braccio. Continua ad alternare le braccia per il numero di ripetizioni desiderato.","tr":"Ayaklarınızı omuz genişliğinde açın, dizlerinizi hafifçe bükün ve avuçlarınız vücudunuza bakacak şekilde her iki elinizde bir kettlebell tutun. Kalçalarınızı öne doğru eğin, sırtınızı düz ve merkez bölgenizi meşgul tutun. Bir kettlebell''i göğsünüze doğru çekin, dirseğinizi vücudunuza yakın tutun ve kürek kemiklerinizi birbirine sıkıştırın. Kettlebell''i tekrar başlangıç ​​pozisyonuna indirin ve hareketi diğer kolunuzla tekrarlayın. İstenilen sayıda tekrar için kolları değiştirerek devam edin.","es":"Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sostén una pesa rusa en cada mano con las palmas hacia el cuerpo. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Tira de una pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo y apretando los omóplatos entre sí. Baja la pesa rusa de nuevo a la posición inicial y repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, колени слегка согнуты, в каждой руке держите по гире ладонями к телу. Наклонитесь вперед в бедрах, сохраняя спину прямой и напряженный корпус. Подтяните одну гирю к груди, держа локоть близко к телу и сжимая лопатки вместе. Опустите гирю обратно в исходное положение и повторите то же самое с другой рукой. Продолжайте чередовать руки желаемое количество повторений.","zh":"双脚分开与肩同宽站立，膝盖稍微弯曲，双手各握一个壶铃，手掌朝向身体。 臀部向前弯曲，保持背部挺直，核心肌群参与。 将一个壶铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。 将壶铃放回起始位置，然后用另一只手臂重复该动作。 继续交替手臂进行所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, घुटने थोड़े मुड़े हुए हों और अपनी हथेलियों को अपने शरीर की ओर रखते हुए प्रत्येक हाथ में एक केटलबेल पकड़ें। अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, कूल्हों के बल आगे की ओर झुकें। एक केटलबेल को अपनी छाती की ओर खींचें, अपनी कोहनी को अपने शरीर के करीब रखें और अपने कंधे के ब्लेड को एक साथ निचोड़ें। केटलबेल को वापस प्रारंभिक स्थिति में लाएँ और दूसरे हाथ से दोहराएँ। दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।","pl":"Stań ze stopami rozstawionymi na szerokość barków, kolana lekko ugięte, i trzymaj kettlebell w każdej dłoni, dłonie skierowane w stronę ciała. Pochyl się do przodu w biodrach, utrzymując proste plecy i napięte mięśnie brzucha. Podciągnij jeden kettlebell w stronę klatki piersiowej, trzymając łokieć blisko ciała i ściskając łopatki. Opuść kettlebell z powrotem do pozycji wyjściowej i powtórz drugą ręką. Kontynuuj naprzemienne wykonywanie ruchu zgodnie z zaplanowaną liczbą powtórzeń.","ko":"양쪽 손에 케틀벨을 잡고 다리를 어깨 너비로 벌리고 무릎을 살짝 구부립니다. 허리에서 구부리면서 등을 곧게 펴고 코어에 힘을 줍니다. 팔꿈치를 몸에 붙이고 한 쪽 케틀벨을 가슴 쪽으로 당기면서 어깨 날개뼈를 모아줍니다. 케틀벨을 처음 위치로 낮추고 다른 팔로 반복합니다. 원하는 반복 횟수까지 팔을 교대로 계속 움직입니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, les genoux légèrement fléchis, et tiens un kettlebell dans chaque main, paumes tournées vers ton corps. Penche-toi vers l''avant au niveau des hanches en gardant ton dos droit et ta sangle abdominale gainée. Tire un kettlebell vers ta poitrine, en gardant ton coude près de ton corps et en contractant tes omoplates. Abaisse le kettlebell jusqu''à la position de départ et répète avec l''autre bras. Continue à alterner les bras pour le nombre de répétitions souhaité."}'::jsonb, 'images/0522-Ca76jUE.jpg', 'videos/0522-Ca76jUE.gif', '© Gym visual — https://gymvisual.com/'),
(523, 'kettlebell arnold press', 'shoulders', 'strength', 'shoulders', 'kettlebell', 'triceps', 'delts', '["triceps","upper back"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height with your palms facing towards you. Engage your core and press the kettlebells overhead, rotating your palms to face forward as you extend your arms. Pause at the top of the movement, then slowly lower the kettlebells back to the starting position. Repeat for the desired number of repetitions.","it":"Stai con i piedi alla larghezza delle spalle, tenendo un kettlebell in ciascuna mano all''altezza delle spalle con i palmi rivolti verso di te. Coinvolgi il core e premi i kettlebell sopra la testa, ruotando i palmi delle mani in modo che siano rivolti in avanti mentre estendi le braccia. Fare una pausa nella parte superiore del movimento, quindi abbassare lentamente i kettlebell nella posizione iniziale. Ripetere per il numero di ripetizioni desiderato.","tr":"Ayaklarınız omuz genişliğinde açık, avuçlarınız size bakacak şekilde her iki elinizde omuz hizasında birer kettlebell tutarak ayakta durun. Merkez bölgenizi devreye sokun ve kollarınızı uzatırken avuç içlerinizi öne bakacak şekilde döndürerek kettlebell''leri başınızın üzerine bastırın. Hareketin en üst noktasında duraklayın, ardından kettlebell''leri yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros con las palmas hacia ti. Activa el core y empuja las pesas rusas por encima de la cabeza, girando las palmas hacia adelante mientras extiendes los brazos. Haz una pausa en la parte superior del movimiento, luego baja lentamente las pesas rusas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Встаньте, поставив ноги на ширине плеч, держа в каждой руке по гире на уровне плеч ладонями к себе. Напрягите корпус и выжмите гири над головой, поворачивая ладони лицом вперед и вытягивая руки. Сделайте паузу в верхней точке движения, затем медленно опустите гири обратно в исходное положение. Повторите необходимое количество повторений.","zh":"双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高，手掌朝向自己。 启动你的核心并将壶铃压过头顶，在伸展手臂时旋转手掌以面向前方。 在动作的最高点暂停，然后慢慢将壶铃放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में कंधे की ऊंचाई पर केटलबेल पकड़ें और अपनी हथेलियों को अपनी ओर रखें। अपने कोर को संलग्न करें और केटलबेल्स को ऊपर की ओर दबाएं, अपनी हथेलियों को आगे की ओर घुमाते हुए अपनी बाहों को फैलाएं। गति के शीर्ष पर रुकें, फिर धीरे-धीरे केटलबेल्स को प्रारंभिक स्थिति में वापस लाएँ। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w każdej dłoni na wysokości barków, dłonie skierowane do siebie. Napnij mięśnie brzucha i wypchnij kettlebelle nad głowę, obracając dłonie do przodu w trakcie prostowania ramion. Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść kettlebelle do pozycji wyjściowej. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"양손으로 케틀벨을 어깨 높이에서 잡고 다리를 어깨 너비로 벌립니다. 코어에 힘을 주고 케틀벨을 머리 위로 누르면서 팔을 펴는 것과 동시에 손바닥이 앞을 향하도록 회전시킵니다. 최고점에서 잠깐 멈춘 후 케틀벨을 천천히 처음 위치로 낮춥니다. 원하는 반복 횟수까지 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell dans chaque main à hauteur d''épaule, paumes tournées vers toi. Gaine ta sangle abdominale et pousse les kettlebells au-dessus de ta tête, en tournant tes paumes vers l''avant à mesure que tu étends tes bras. Marque une pause en haut du mouvement, puis abaisse lentement les kettlebells jusqu''à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0523-UM8mgyG.jpg', 'videos/0523-UM8mgyG.gif', '© Gym visual — https://gymvisual.com/'),
(524, 'kettlebell bent press', 'waist', 'strength', 'waist', 'kettlebell', 'shoulders', 'abs', '["shoulders","triceps","obliques"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in your right hand. Bend your knees slightly and press the kettlebell overhead with your right arm, keeping your elbow locked. Rotate your torso to the left, shifting your weight onto your left foot. Bend your left knee and lower your torso towards the ground, keeping your right arm extended overhead. As you lower, keep your eyes on the kettlebell and your chest lifted. Once your left hand touches the ground, push through your left foot and straighten your left leg, driving your hips forward. As you drive your hips forward, use your core and right arm to press the kettlebell back up to the starting position. Repeat for the desired number of repetitions, then switch sides.","it":"Stai con i piedi alla larghezza delle spalle, tenendo un kettlebell nella mano destra. Piega leggermente le ginocchia e premi il kettlebell sopra la testa con il braccio destro, mantenendo il gomito bloccato. Ruota il busto verso sinistra, spostando il peso sul piede sinistro. Piega il ginocchio sinistro e abbassa il busto verso terra, mantenendo il braccio destro esteso sopra la testa. Mentre ti abbassi, tieni gli occhi sul kettlebell e il petto sollevato. Una volta che la mano sinistra tocca il suolo, spingi il piede sinistro e raddrizza la gamba sinistra, spingendo i fianchi in avanti. Mentre spingi i fianchi in avanti, usa il core e il braccio destro per riportare il kettlebell nella posizione iniziale. Ripeti per il numero di ripetizioni desiderato, quindi cambia lato.","tr":"Ayaklarınızı omuz genişliğinde açın ve sağ elinizde bir kettlebell tutun. Dizlerinizi hafifçe bükün ve dirseğinizi kilitli tutarak kettlebell''i sağ kolunuzla başınızın üzerine doğru bastırın. Ağırlığınızı sol ayağınıza vererek gövdenizi sola döndürün. Sol dizinizi bükün ve sağ kolunuzu başınızın üzerinde uzatarak gövdenizi yere doğru indirin. Aşağı inerken gözlerinizi kettlebell''de tutun ve göğsünüzü kaldırın. Sol eliniz yere değdiğinde, sol ayağınızı itin ve sol bacağınızı düzleştirerek kalçalarınızı ileri doğru hareket ettirin. Kalçalarınızı ileri doğru iterken, kettlebell''i başlangıç ​​pozisyonuna geri itmek için merkez bölgenizi ve sağ kolunuzu kullanın. İstenilen tekrar sayısı kadar tekrarlayın, ardından taraf değiştirin.","es":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en la mano derecha. Dobla ligeramente las rodillas y empuja la pesa rusa por encima de la cabeza con el brazo derecho, manteniendo el codo bloqueado. Rota el torso hacia la izquierda, trasladando tu peso al pie izquierdo. Flexiona la rodilla izquierda y baja el torso hacia el suelo, manteniendo el brazo derecho extendido por encima de la cabeza. Mientras bajas, mantén la mirada en la pesa rusa y el pecho elevado. Cuando tu mano izquierda toque el suelo, empuja con el pie izquierdo y estira la pierna izquierda, llevando las caderas hacia adelante. Mientras llevas las caderas hacia adelante, usa el core y el brazo derecho para empujar la pesa rusa de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.","ru":"Встаньте, ноги на ширине плеч, в правой руке держите гирю. Слегка согните колени и нажмите гирю над головой правой рукой, держа локоть зафиксированным. Поверните туловище влево, перенеся вес тела на левую ногу. Согните левое колено и опустите туловище к земле, держа правую руку вытянутой над головой. Опускаясь, следите за гирей, а грудь приподнимайте. Как только ваша левая рука коснется земли, оттолкнитесь левой ступней и выпрямите левую ногу, направляя бедра вперед. Когда вы двигаете бедрами вперед, используйте корпус и правую руку, чтобы вернуть гирю в исходное положение. Повторите желаемое количество повторений, затем поменяйте сторону.","zh":"双脚分开与肩同宽站立，右手握住壶铃。 稍微弯曲膝盖，用右臂将壶铃压过头顶，保持肘部锁定。 将躯干向左旋转，将重量转移到左脚上。 弯曲左膝，将躯干压向地面，保持右臂伸过头顶。 当你下降时，眼睛盯着壶铃，胸部抬起。 左手接触地面后，将左脚推入并伸直左腿，推动臀部向前。 当你向前推动臀部时，用你的核心和右臂将壶铃推回到起始位置。 重复所需的重复次数，然后换边。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपने दाहिने हाथ में केटलबेल पकड़ लें। अपने घुटनों को थोड़ा मोड़ें और अपनी कोहनी को लॉक रखते हुए, अपने दाहिने हाथ से केटलबेल को ऊपर की ओर दबाएं। अपने धड़ को बाईं ओर घुमाएं, अपना वजन अपने बाएं पैर पर डालें। अपने बाएं घुटने को मोड़ें और अपने धड़ को ज़मीन की ओर नीचे करें, अपने दाहिने हाथ को ऊपर की ओर फैलाकर रखें। जैसे ही आप नीचे उतरें, अपनी आँखें केटलबेल पर रखें और अपनी छाती ऊपर उठाएँ। एक बार जब आपका बायाँ हाथ ज़मीन को छू ले, तो अपने बाएँ पैर से धक्का दें और अपने कूल्हों को आगे की ओर ले जाते हुए अपने बाएँ पैर को सीधा करें। जैसे ही आप अपने कूल्हों को आगे बढ़ाते हैं, केटलबेल को शुरुआती स्थिति में वापस दबाने के लिए अपने मूल और दाहिने हाथ का उपयोग करें। दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w prawej dłoni. Ugnij lekko kolana i wypchnij kettlebell nad głowę prawą ręką, blokując łokieć. Obróć tułów w lewo, przenosząc ciężar ciała na lewą stopę. Ugnij lewe kolano i opuść tułów w kierunku podłogi, utrzymując prawą rękę wyciągniętą nad głowę. Podczas opuszczania utrzymuj wzrok na kettlebellu, a klatkę piersiową uniesioną. Gdy lewa dłoń dotknie podłogi, odepchnij się lewą stopą i wyprostuj lewą nogę, wypychając biodra do przodu. Wypychając biodra do przodu, użyj mięśni brzucha i prawej ręki, aby wypchnąć kettlebell z powrotem do pozycji wyjściowej. Powtórz zgodnie z zaplanowaną liczbą powtórzeń, a następnie zmień stronę.","ko":"다리를 어깨 너비로 벌리고 오른손으로 케틀벨을 잡습니다. 무릎을 살짝 구부리고 오른팔의 팔꿈치를 펴면서 케틀벨을 머리 위로 누릅니다. 몸을 왼쪽으로 회전하면서 무게를 왼발로 옮깁니다. 왼쪽 무릎을 구부리고 오른팔을 머리 위로 펴진 상태로 유지하면서 몸을 땅 쪽으로 낮춥니다. 내려갈 때 케틀벨을 바라보고 가슴을 펴진 상태로 유지합니다. 왼손이 땅에 닿으면 왼발로 밀어내면서 왼다리를 펴고 엉덩이를 앞으로 밀어냅니다. 엉덩이를 앞으로 밀어내면서 코어와 오른팔을 사용하여 케틀벨을 처음 위치로 누릅니다. 원하는 반복 횟수를 완료한 후 반대쪽을 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell dans ta main droite. Fléchis légèrement les genoux et pousse la kettlebell au-dessus de ta tête avec ton bras droit en gardant ton coude verrouillé. Fais pivoter ton torse vers la gauche, en transférant ton poids sur ton pied gauche. Fléchis ton genou gauche et abaisse ton torse vers le sol en gardant ton bras droit tendu au-dessus de ta tête. En descendant, garde les yeux sur le kettlebell et la poitrine ouverte. Une fois ta main gauche en contact avec le sol, pousse sur ton pied gauche et tends ta jambe gauche, en poussant tes hanches vers l''avant. En poussant tes hanches vers l''avant, utilise ta sangle abdominale et ton bras droit pour repousser le kettlebell vers la position de départ. Répète le nombre de répétitions souhaité, puis change de côté."}'::jsonb, 'images/0524-kjE55n5.jpg', 'videos/0524-kjE55n5.gif', '© Gym visual — https://gymvisual.com/'),
(525, 'kettlebell bottoms up clean from the hang position', 'upper arms', 'strength', 'upper arms', 'kettlebell', 'forearms', 'biceps', '["forearms","shoulders"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up. Allow the kettlebell to hang down between your legs, with your arm fully extended. In one fluid motion, explosively extend your hips and knees while pulling the kettlebell up towards your shoulder. As the kettlebell reaches shoulder height, rotate your wrist so that the bottom of the kettlebell is facing up. Catch the kettlebell at shoulder height with your elbow bent and your palm facing up. Lower the kettlebell back down to the starting position by reversing the movement. Repeat for the desired number of repetitions, then switch sides.","it":"Stare con i piedi alla larghezza delle spalle, tenendo un kettlebell in una mano con una presa prona. Piega leggermente le ginocchia e fai perno in avanti sui fianchi, mantenendo la schiena dritta e il petto in alto. Lascia che il kettlebell penda tra le gambe, con il braccio completamente esteso. Con un movimento fluido, estendi in modo esplosivo i fianchi e le ginocchia mentre sollevi il kettlebell verso la spalla. Quando il kettlebell raggiunge l''altezza delle spalle, ruotare il polso in modo che la parte inferiore del kettlebell sia rivolta verso l''alto. Afferra il kettlebell all''altezza delle spalle con il gomito piegato e il palmo rivolto verso l''alto. Abbassare il kettlebell nella posizione iniziale invertendo il movimento. Ripeti per il numero di ripetizioni desiderato, quindi cambia lato.","tr":"Ayaklarınızı omuz genişliğinde açın ve bir elinizde kettlebell''i üstten kavrayarak tutun. Dizlerinizi hafifçe bükün ve kalçalarınızdan öne doğru eğilin, sırtınızı düz ve göğsünüzü yukarıda tutun. Kolunuz tamamen uzatılmış haldeyken kettlebell''in bacaklarınızın arasında asılı kalmasına izin verin. Tek bir akıcı hareketle, kettlebell''i omzunuza doğru çekerken kalçalarınızı ve dizlerinizi patlayıcı bir şekilde uzatın. Kettlebell omuz yüksekliğine ulaştığında, kettlebell''in alt kısmı yukarı bakacak şekilde bileğinizi döndürün. Dirseğiniz bükülü ve avucunuz yukarı bakacak şekilde kettlebell''i omuz hizasında yakalayın. Hareketi tersine çevirerek kettlebell''i başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından taraf değiştirin.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Deja que la pesa rusa cuelgue entre tus piernas, con el brazo completamente extendido. En un solo movimiento fluido, extiende explosivamente las caderas y las rodillas mientras tiras de la pesa rusa hacia el hombro. Cuando la pesa rusa llegue a la altura del hombro, rota la muñeca de modo que la base de la pesa rusa quede hacia arriba. Atrapa la pesa rusa a la altura del hombro con el codo flexionado y la palma hacia arriba. Baja la pesa rusa de vuelta a la posición inicial invirtiendo el movimiento. Repite el número de repeticiones deseado, luego cambia de lado.","ru":"Встаньте, ноги на ширине плеч, держите гирю в одной руке хватом сверху. Слегка согните колени и наклонитесь вперед в бедрах, держа спину прямо и грудь вверх. Позвольте гире свисать между ног, полностью вытянув руку. Одним плавным движением резко выпрямите бедра и колени, одновременно подтягивая гирю к плечу. Когда гиря достигнет уровня плеч, поверните запястье так, чтобы нижняя часть гири была обращена вверх. Возьмите гирю на уровне плеч, согнув локоть и повернув ладонь вверх. Опустите гирю обратно в исходное положение, выполняя движение в обратном направлении. Повторите желаемое количество повторений, затем поменяйте сторону.","zh":"双脚分开与肩同宽站立，一只手握住壶铃，正手握住。 稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。 让壶铃垂在双腿之间，手臂完全伸展。 以一种流畅的动作，爆发性地伸展你的臀部和膝盖，同时将壶铃拉向你的肩膀。 当壶铃到达肩膀高度时，旋转手腕，使壶铃底部朝上。 在与肩同高的位置抓住壶铃，肘部弯曲，手掌朝上。 通过反向运动将壶铃降低回到起始位置。 重复所需的重复次数，然后换边。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े रहें, एक हाथ में केटलबेल को ओवरहैंड पकड़ के साथ पकड़ें। अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ सीधी और छाती ऊपर रखें। अपनी बांह को पूरी तरह फैलाकर केटलबेल को अपने पैरों के बीच लटकने दें। एक तरल गति में, केटलबेल को अपने कंधे की ओर खींचते हुए अपने कूल्हों और घुटनों को विस्फोटक रूप से फैलाएँ। जैसे ही केटलबेल कंधे की ऊंचाई तक पहुंचे, अपनी कलाई को घुमाएं ताकि केटलबेल का निचला हिस्सा ऊपर की ओर रहे। अपनी कोहनी मोड़कर और अपनी हथेली ऊपर की ओर करके केटलबेल को कंधे की ऊंचाई पर पकड़ें। गति को उलट कर केटलबेल को वापस प्रारंभिक स्थिति में लाएँ। दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w jednej dłoni nachwytem. Ugnij lekko kolana i wykonaj skłon w biodrach, utrzymując proste plecy i uniesioną klatkę piersiową. Pozwól, aby kettlebell zwisał między nogami, z ramieniem całkowicie wyprostowanym. Jednym płynnym ruchem eksplozywnie wyprostuj biodra i kolana, podciągając kettlebell w stronę barku. Gdy kettlebell osiągnie wysokość barku, obróć nadgarstek tak, aby spód kettlebella był skierowany do góry. Złap kettlebell na wysokości barku z ugiętym łokciem i dłonią skierowaną do góry. Opuść kettlebell z powrotem do pozycji wyjściowej, odwracając ruch. Powtórz zgodnie z zaplanowaną liczbą powtórzeń, a następnie zmień stronę.","ko":"다리를 어깨 너비로 벌리고 한 손으로 오버핸드 그립으로 케틀벨을 잡습니다. 무릎을 살짝 구부리고 허리에서 구부리면서 등을 곧게 펴고 가슴을 들어올립니다. 케틀벨이 양다리 사이에 매달린 상태로 팔을 완전히 펼칩니다. 한 번의 폭발적인 동작으로 엉덩이와 무릎을 펼치면서 케틀벨을 어깨 쪽으로 당깁니다. 케틀벨이 어깨 높이에 도달하면 손목을 회전하여 케틀벨의 바닥이 위를 향하게 합니다. 팔꿈치를 구부리고 손바닥이 위를 향하는 상태로 어깨 높이에서 케틀벨을 잡습니다. 동작을 반대로 하여 케틀벨을 처음 위치로 낮춥니다. 원하는 반복 횟수를 완료한 후 반대쪽을 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell d''une main en prise pronation. Fléchis légèrement les genoux et bascule vers l''avant au niveau des hanches en gardant le dos droit et la poitrine relevée. Laisse le kettlebell pendre entre tes jambes, le bras complètement étendu. En un mouvement fluide, étends de manière explosive tes hanches et tes genoux tout en tirant la kettlebell vers ton épaule. Lorsque le kettlebell atteint la hauteur des épaules, fais pivoter ton poignet de sorte que le bas du kettlebell soit tourné vers le haut. Réceptionne la kettlebell à hauteur de l''épaule avec ton coude fléchi et ta paume tournée vers le haut. Abaisse le kettlebell jusqu''à la position de départ en inversant le mouvement. Répète le nombre de répétitions souhaité, puis change de côté."}'::jsonb, 'images/0525-4KJEpzb.jpg', 'videos/0525-4KJEpzb.gif', '© Gym visual — https://gymvisual.com/'),
(526, 'kettlebell double alternating hang clean', 'upper arms', 'strength', 'upper arms', 'kettlebell', 'forearms', 'biceps', '["forearms","shoulders"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up. Allow the kettlebells to hang straight down in front of your body. In one fluid motion, explosively extend your hips and knees while shrugging your shoulders. As the kettlebells rise, pull them up towards your shoulders, keeping your elbows high and out to the sides. Catch the kettlebells at shoulder height, with your palms facing inward and your elbows pointing forward. Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions.","it":"Stai con i piedi alla larghezza delle spalle, tenendo un kettlebell in ciascuna mano con una presa prona. Piega leggermente le ginocchia e fai perno in avanti sui fianchi, mantenendo la schiena dritta e il petto in alto. Lascia che i kettlebell pendano dritti davanti al tuo corpo. Con un movimento fluido, estendi in modo esplosivo i fianchi e le ginocchia mentre alzi le spalle. Mentre i kettlebell si alzano, tirali verso le spalle, mantenendo i gomiti alti e verso i lati. Afferra i kettlebell all''altezza delle spalle, con i palmi rivolti verso l''interno e i gomiti rivolti in avanti. Abbassare nuovamente i kettlebell nella posizione iniziale e ripetere per il numero di ripetizioni desiderato.","tr":"Ayaklarınızı omuz genişliğinde açın ve her iki elinizde birer kettlebell''i üstten kavrayarak tutun. Dizlerinizi hafifçe bükün ve kalçalarınızdan öne doğru eğilin, sırtınızı düz ve göğsünüzü yukarıda tutun. Kettlebell''lerin vücudunuzun önünde düz bir şekilde asılı kalmasına izin verin. Tek bir akıcı hareketle, omuzlarınızı silkerken kalçalarınızı ve dizlerinizi patlayıcı bir şekilde uzatın. Kettlebell''ler yükseldikçe, dirseklerinizi yüksek ve yanlara doğru tutarak onları omuzlarınıza doğru yukarı çekin. Kettlebell''leri omuz hizasında, avuçlarınız içe bakacak ve dirsekleriniz öne bakacak şekilde yakalayın. Kettlebell''leri başlangıç ​​pozisyonuna indirin ve istenilen sayıda tekrar yapın.","es":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano con agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Deja que las pesas rusas cuelguen rectas frente a tu cuerpo. En un solo movimiento fluido, extiende explosivamente las caderas y las rodillas mientras encoges los hombros. Mientras las pesas rusas suben, tira de ellas hacia los hombros, manteniendo los codos altos y hacia los lados. Atrapa las pesas rusas a la altura del hombro, con las palmas hacia adentro y los codos apuntando hacia adelante. Baja las pesas rusas de vuelta a la posición inicial y repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, возьмите в каждую руку по гире хватом сверху. Слегка согните колени и наклонитесь вперед в бедрах, держа спину прямо и грудь вверх. Позвольте гирям свисать прямо перед вашим телом. Одним плавным движением резко выпрямите бедра и колени, одновременно пожимая плечами. Когда гири поднимутся, подтяните их к плечам, держа локти высоко и в стороны. Возьмите гири на уровне плеч, ладонями внутрь, а локтями вперед. Опустите гири обратно в исходное положение и повторите желаемое количество повторений.","zh":"双脚分开与肩同宽站立，双手各握一个壶铃，正手握住。 稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。 让壶铃垂直悬挂在身体前方。 以一种流畅的动作，爆发性地伸展臀部和膝盖，同时耸肩。 当壶铃上升时，将其拉向肩膀，保持肘部高且向两侧伸展。 在与肩同高的位置抓住壶铃，手掌朝内，肘部向前。 将壶铃放回起始位置，然后重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में केटलबेल को ओवरहैंड पकड़ के साथ पकड़ें। अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ सीधी और छाती ऊपर रखें। केटलबेल्स को अपने शरीर के सामने सीधा लटकने दें। एक तरल गति में, अपने कंधों को सिकोड़ते हुए अपने कूल्हों और घुटनों को तेजी से फैलाएँ। जैसे ही केटलबेल्स ऊपर उठें, उन्हें अपने कंधों की ओर ऊपर खींचें, अपनी कोहनियों को ऊपर और बगल की ओर रखें। केटलबेल्स को कंधे की ऊंचाई पर पकड़ें, आपकी हथेलियाँ अंदर की ओर हों और आपकी कोहनियाँ आगे की ओर हों। केटलबेल्स को वापस प्रारंभिक स्थिति में लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w każdej dłoni nachwytem. Ugnij lekko kolana i wykonaj skłon w biodrach, utrzymując proste plecy i uniesioną klatkę piersiową. Pozwól, aby kettlebelle zwisały prosto przed ciałem. Jednym płynnym ruchem eksplozywnie wyprostuj biodra i kolana, unosząc jednocześnie ramiona w barkach. Gdy kettlebelle się wznoszą, podciągnij je w stronę barków, trzymając łokcie wysoko i na zewnątrz. Złap kettlebelle na wysokości barków, dłońmi skierowanymi do wewnątrz i łokciami skierowanymi do przodu. Opuść kettlebelle z powrotem do pozycji wyjściowej i powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"다리를 어깨 너비로 벌리고 양손으로 오버핸드 그립으로 케틀벨을 잡습니다. 무릎을 살짝 구부리고 허리에서 구부리면서 등을 곧게 펴고 가슴을 들어올립니다. 케틀벨이 몸 앞에 일직선으로 매달진 상태를 유지합니다. 한 번의 폭발적인 동작으로 엉덩이와 무릎을 펼치면서 어깨를 으쓱합니다. 케틀벨이 올라오면서 어깨 쪽으로 당기면서 팔꿈치를 높게 유지하고 옆으로 펼칩니다. 손바닥이 안쪽을 향하고 팔꿈치가 앞을 향하는 상태로 어깨 높이에서 케틀벨을 잡습니다. 케틀벨을 처음 위치로 낮추고 원하는 반복 횟수까지 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell dans chaque main en prise pronation. Fléchis légèrement les genoux et bascule vers l''avant au niveau des hanches en gardant le dos droit et la poitrine relevée. Laisse les kettlebells pendre bien droit devant ton corps. En un mouvement fluide, étends de manière explosive tes hanches et tes genoux tout en haussant les épaules. Lorsque les kettlebells montent, tire-les vers tes épaules en gardant tes coudes hauts et écartés vers les côtés. Réceptionne les kettlebells à hauteur des épaules, les paumes tournées vers l''intérieur et les coudes pointés vers l''avant. Abaisse les kettlebells jusqu''à la position de départ et répète pour le nombre de répétitions souhaité."}'::jsonb, 'images/0526-a4F9Oyc.jpg', 'videos/0526-a4F9Oyc.gif', '© Gym visual — https://gymvisual.com/'),
(527, 'kettlebell double jerk', 'shoulders', 'strength', 'shoulders', 'kettlebell', 'triceps', 'delts', '["triceps","core"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height. Bend your knees slightly and engage your core. Press the kettlebells overhead, fully extending your arms. Bend your knees and quickly drop into a partial squat. Explosively extend your hips and knees, driving the kettlebells overhead. Lock out your arms and catch the kettlebells overhead with your knees slightly bent. Stand up straight and return to the starting position. Repeat for the desired number of repetitions.","it":"Stare con i piedi alla larghezza delle spalle, tenendo un kettlebell in ciascuna mano all''altezza delle spalle. Piega leggermente le ginocchia e coinvolgi il core. Premi i kettlebell sopra la testa, estendendo completamente le braccia. Piega le ginocchia e scendi rapidamente in uno squat parziale. Estendi in modo esplosivo le anche e le ginocchia, portando i kettlebell sopra la testa. Blocca le braccia e afferra i kettlebell sopra la testa con le ginocchia leggermente piegate. Stai dritto e torna alla posizione di partenza. Ripetere per il numero di ripetizioni desiderato.","tr":"Ayaklarınızı omuz genişliğinde açın ve her iki elinizde de omuz hizasında birer kettlebell tutun. Dizlerinizi hafifçe bükün ve çekirdeğinizi çalıştırın. Kollarınızı tamamen uzatarak kettlebell''leri başınızın üzerine bastırın. Dizlerinizi bükün ve hızla kısmi çömelmeye bırakın. Kalçalarınızı ve dizlerinizi patlayıcı bir şekilde uzatarak kettlebell''leri yukarı doğru hareket ettirin. Kollarınızı kilitleyin ve dizleriniz hafifçe bükülmüş halde kettlebell''leri başınızın üstünde tutun. Düz durun ve başlangıç ​​pozisyonuna dönün. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros. Flexiona ligeramente las rodillas y activa el core. Presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo. Flexiona las rodillas y baja rápidamente a una sentadilla parcial. Extiende explosivamente las caderas y las rodillas, impulsando las pesas rusas hacia arriba. Bloquea los brazos y atrapa las pesas rusas por encima de la cabeza con las rodillas ligeramente flexionadas. Ponte de pie recto y vuelve a la posición inicial. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, держа в каждой руке по гире на уровне плеч. Слегка согните колени и задействуйте корпус. Жмите гири над головой, полностью выпрямляя руки. Согните колени и быстро опуститесь в частичное приседание. Резко выпрямите бедра и колени, поднимая гири над головой. Выпрямите руки и поймайте гири над головой, слегка согнув колени. Встаньте прямо и вернитесь в исходное положение. Повторите необходимое количество повторений.","zh":"双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高。 稍微弯曲膝盖并启动核心。 将壶铃压过头顶，充分伸展手臂。 弯曲膝盖并快速半蹲。 爆发性地伸展臀部和膝盖，将壶铃举过头顶。 锁定双臂，将壶铃举过头顶，膝盖稍微弯曲。 站直并回到起始位置。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में कंधे की ऊंचाई पर केटलबेल पकड़ें। अपने घुटनों को थोड़ा मोड़ें और अपने कोर को संलग्न करें। अपनी बाहों को पूरी तरह फैलाते हुए केटलबेल्स को ऊपर की ओर दबाएं। अपने घुटनों को मोड़ें और जल्दी से आंशिक स्क्वाट में बैठ जाएं। केटलबेल्स को सिर के ऊपर चलाते हुए अपने कूल्हों और घुटनों को तेजी से फैलाएँ। अपनी बाहों को लॉक करें और अपने घुटनों को थोड़ा मोड़कर केटलबेल्स को ऊपर की ओर पकड़ें। सीधे खड़े हो जाएं और प्रारंभिक स्थिति में लौट आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w każdej dłoni na wysokości barków. Ugnij lekko kolana i napnij mięśnie brzucha. Wypchnij kettlebelle nad głowę, w pełni prostując ramiona. Ugnij kolana i szybko wejdź w częściowy przysiad. Eksplozywnie wyprostuj biodra i kolana, wypychając kettlebelle nad głowę. Zablokuj ramiona i złap kettlebelle nad głową z lekko ugiętymi kolanami. Wyprostuj się i wróć do pozycji wyjściowej. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"다리를 어깨 너비로 벌리고 양손으로 어깨 높이에서 케틀벨을 잡습니다. 무릎을 살짝 구부리고 코어에 힘을 줍니다. 케틀벨을 머리 위로 누르면서 팔을 완전히 펼칩니다. 무릎을 구부리고 재빠르게 하프 스쿼트 자세로 내려갑니다. 엉덩이와 무릎을 폭발적으로 펼치면서 케틀벨을 머리 위로 밀어냅니다. 팔을 펴고 무릎을 약간 구부린 상태로 머리 위에서 케틀벨을 잡습니다. 일어서서 다리를 완전히 펼친 후 처음 위치로 돌아옵니다. 원하는 반복 횟수까지 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell dans chaque main à hauteur d''épaule. Fléchis légèrement les genoux et gaine ta sangle abdominale. Développe les kettlebells au-dessus de ta tête, en tendant complètement tes bras. Fléchis les genoux et descends rapidement en demi-accroupissement. Étends de manière explosive tes hanches et tes genoux, en propulsant les kettlebells au-dessus de ta tête. Verrouille tes bras et rattrape les kettlebells au-dessus de la tête, les genoux légèrement fléchis. Redresse-toi et reviens à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0527-tznL2Ad.jpg', 'videos/0527-tznL2Ad.gif', '© Gym visual — https://gymvisual.com/'),
(528, 'kettlebell double push press', 'shoulders', 'strength', 'shoulders', 'kettlebell', 'triceps', 'delts', '["triceps","core"]'::jsonb, '{"en":"Start by standing with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height. Bend your knees slightly and engage your core. Initiate the movement by explosively extending your hips, knees, and ankles, driving the kettlebells overhead. As the kettlebells reach the top, press them fully overhead, locking out your arms. Lower the kettlebells back to the starting position by bending your elbows and bringing them back down to shoulder height. Repeat for the desired number of repetitions.","it":"Inizia stando in piedi con i piedi alla larghezza delle spalle, tenendo un kettlebell in ciascuna mano all''altezza delle spalle. Piega leggermente le ginocchia e coinvolgi il core. Inizia il movimento estendendo in modo esplosivo anche, ginocchia e caviglie, portando i kettlebell sopra la testa. Quando i kettlebell raggiungono la cima, spingili completamente sopra la testa, bloccando le braccia. Abbassa i kettlebell nella posizione di partenza piegando i gomiti e riportandoli all''altezza delle spalle. Ripetere per il numero di ripetizioni desiderato.","tr":"Ayaklarınızı omuz genişliğinde açarak, her iki elinizde de omuz hizasında birer kettlebell tutarak başlayın. Dizlerinizi hafifçe bükün ve çekirdeğinizi çalıştırın. Kalçalarınızı, dizlerinizi ve ayak bileklerinizi patlayıcı bir şekilde uzatarak, kettlebell''leri başınızın üzerine doğru sürerek hareketi başlatın. Kettlebell''ler tepeye ulaştığında, kollarınızı kilitleyerek onları tamamen yukarı doğru bastırın. Dirseklerinizi bükerek ve tekrar omuz yüksekliğine getirerek kettlebell''leri başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Comienza de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano a la altura del hombro. Flexiona ligeramente las rodillas y activa el core. Inicia el movimiento extendiendo explosivamente las caderas, las rodillas y los tobillos, impulsando las pesas rusas por encima de la cabeza. Cuando las pesas rusas lleguen arriba, presiónalas completamente por encima de la cabeza, bloqueando los brazos. Baja las pesas rusas a la posición inicial flexionando los codos y llevándolas de vuelta a la altura del hombro. Repite el número de repeticiones deseado.","ru":"Начните с того, что встаньте, поставив ноги на ширине плеч, держа в каждой руке по гире на уровне плеч. Слегка согните колени и задействуйте корпус. Начните движение, резко выпрямляя бедра, колени и лодыжки, поднимая гири над головой. Когда гири достигнут верха, полностью выжмите их над головой, заблокировав руки. Опустите гири обратно в исходное положение, согнув локти и вернув их на высоту плеч. Повторите необходимое количество повторений.","zh":"首先，双脚分开与肩同宽，每只手握住一个壶铃，与肩同高。 稍微弯曲膝盖并启动核心。 通过爆发性伸展臀部、膝盖和脚踝来开始运动，将壶铃举过头顶。 当壶铃到达顶部时，将它们完全压过头顶，锁定手臂。 弯曲肘部并将壶铃放回至肩膀高度，将壶铃放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई से अलग करके खड़े होकर शुरुआत करें, प्रत्येक हाथ में कंधे की ऊंचाई पर केटलबेल पकड़ें। अपने घुटनों को थोड़ा मोड़ें और अपने कोर को संलग्न करें। अपने कूल्हों, घुटनों और टखनों को विस्फोटक रूप से फैलाकर, केटलबेल को ऊपर की ओर चलाकर आंदोलन शुरू करें। जैसे ही केटलबेल शीर्ष पर पहुंचें, अपनी बाहों को लॉक करते हुए, उन्हें पूरी तरह से ऊपर की ओर दबाएं। अपनी कोहनियों को मोड़कर और उन्हें वापस कंधे की ऊंचाई तक लाकर केटलबेल्स को शुरुआती स्थिति में वापस लाएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Zacznij, stojąc ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w każdej dłoni na wysokości barków. Ugnij lekko kolana i napnij mięśnie brzucha. Zainicjuj ruch, eksplozywnie prostując biodra, kolana i stawy skokowe, wypychając kettlebelle nad głowę. Gdy kettlebelle osiągną szczyt, wypchnij je całkowicie nad głowę, blokując ramiona. Opuść kettlebelle do pozycji wyjściowej, uginając łokcie i sprowadzając je z powrotem na wysokość barków. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"다리를 어깨 너비로 벌리고 양손으로 어깨 높이에서 케틀벨을 잡고 서 있습니다. 무릎을 살짝 구부리고 코어에 힘을 줍니다. 엉덩이, 무릎, 발목을 폭발적으로 펼치면서 케틀벨을 머리 위로 밀어냅니다. 케틀벨이 최고점에 도달하면 팔을 완전히 펴면서 케틀벨을 머리 위로 누릅니다. 팔꿈치를 구부리고 케틀벨을 어깨 높이로 낮추면서 처음 위치로 돌아옵니다. 원하는 반복 횟수까지 반복합니다.","fr":"Commence debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell dans chaque main à hauteur des épaules. Fléchis légèrement les genoux et gaine ta sangle abdominale. Amorce le mouvement en étendant de manière explosive tes hanches, tes genoux et tes chevilles, en propulsant les kettlebells au-dessus de ta tête. Lorsque les kettlebells atteignent le sommet, développe-les complètement au-dessus de la tête en verrouillant tes bras. Abaisse les kettlebells jusqu''à la position de départ en fléchissant tes coudes et en les ramenant à hauteur des épaules. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0528-I4KkPdl.jpg', 'videos/0528-I4KkPdl.gif', '© Gym visual — https://gymvisual.com/'),
(529, 'kettlebell double snatch', 'shoulders', 'strength', 'shoulders', 'kettlebell', 'trapezius', 'delts', '["trapezius","forearms","core"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in each hand at arm''s length in front of your thighs. Bend your knees slightly and hinge forward at the hips, keeping your back flat and chest up. In one explosive motion, extend your hips, knees, and ankles, and simultaneously pull the kettlebells up towards your shoulders. As the kettlebells reach shoulder level, rotate your wrists and punch the kettlebells overhead, fully extending your arms. Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions.","it":"Stai con i piedi alla larghezza delle spalle, tenendo un kettlebell in ciascuna mano a distanza di un braccio davanti alle cosce. Piega leggermente le ginocchia e fai perno in avanti sui fianchi, mantenendo la schiena piatta e il petto in alto. Con un movimento esplosivo, estendi i fianchi, le ginocchia e le caviglie e contemporaneamente tira i kettlebell verso le spalle. Quando i kettlebell raggiungono l''altezza delle spalle, ruota i polsi e colpisci i kettlebell sopra la testa, estendendo completamente le braccia. Abbassare nuovamente i kettlebell nella posizione iniziale e ripetere per il numero di ripetizioni desiderato.","tr":"Ayaklarınızı omuz genişliğinde açın, her iki elinizde birer kettlebell''i uyluklarınızın önünde kol uzunluğunda tutun. Dizlerinizi hafifçe bükün ve kalçalarınızdan öne doğru eğilin, sırtınızı düz ve göğsünüzü yukarıda tutun. Tek bir patlayıcı hareketle kalçalarınızı, dizlerinizi ve ayak bileklerinizi uzatın ve aynı anda kettlebell''leri omuzlarınıza doğru çekin. Kettlebell''ler omuz hizasına ulaştığında bileklerinizi döndürün ve kettlebell''leri başınızın üstüne vurarak kollarınızı tamamen uzatın. Kettlebell''leri başlangıç ​​pozisyonuna indirin ve istenilen sayıda tekrar yapın.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano con el brazo extendido frente a los muslos. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. En un solo movimiento explosivo, extiende las caderas, las rodillas y los tobillos, y al mismo tiempo tira de las pesas rusas hacia los hombros. Cuando las pesas rusas lleguen a la altura del hombro, rota las muñecas y lanza las pesas rusas por encima de la cabeza, extendiendo los brazos por completo. Baja las pesas rusas de vuelta a la posición inicial y repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, держа гирю в каждой руке на расстоянии вытянутой руки перед бедрами. Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину ровной и грудь поднятой. Одним взрывным движением вытяните бедра, колени и лодыжки и одновременно подтяните гири к плечам. Когда гири достигнут уровня плеч, поверните запястья и ударьте гирями над головой, полностью выпрямляя руки. Опустите гири обратно в исходное положение и повторите желаемое количество повторений.","zh":"双脚分开与肩同宽站立，每只手各握一个壶铃，放在大腿前面，与手臂保持一定距离。 稍微弯曲膝盖，臀部向前转动，保持背部平坦，挺胸。 以一种爆发力动作，伸展臀部、膝盖和脚踝，同时将壶铃拉向肩膀。 当壶铃达到肩膀水平时，旋转手腕并将壶铃击过头顶，充分伸展手臂。 将壶铃放回起始位置，然后重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में अपनी जांघों के सामने एक हाथ की दूरी पर केटलबेल पकड़ें। अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ को सपाट और छाती को ऊपर रखें। एक विस्फोटक गति में, अपने कूल्हों, घुटनों और टखनों को फैलाएँ, और साथ ही केटलबेल्स को अपने कंधों की ओर खींचें। जैसे ही केटलबेल कंधे के स्तर पर पहुंचें, अपनी कलाइयों को घुमाएं और अपनी बाहों को पूरी तरह फैलाते हुए केटलबेल को ऊपर की ओर मुक्का मारें। केटलबेल्स को वापस प्रारंभिक स्थिति में लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w każdej dłoni na wyciągnięcie ramion przed udami. Ugnij lekko kolana i wykonaj skłon w biodrach, utrzymując plecy proste i klatkę piersiową uniesioną. Jednym eksplozywnym ruchem wyprostuj biodra, kolana i stawy skokowe, jednocześnie podciągając kettlebelle w stronę barków. Gdy kettlebelle osiągną wysokość barków, obróć nadgarstki i wypchnij kettlebelle nad głowę, w pełni prostując ramiona. Opuść kettlebelle z powrotem do pozycji wyjściowej i powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"다리를 어깨 너비로 벌리고 양손으로 허벅지 앞에 팔을 쭉 펼친 상태로 케틀벨을 잡습니다. 무릎을 살짝 구부리고 허리에서 구부리면서 등을 곧게 펴고 가슴을 들어올립니다. 한 번의 폭발적인 동작으로 엉덩이, 무릎, 발목을 펼치면서 동시에 케틀벨을 어깨 쪽으로 당깁니다. 케틀벨이 어깨 높이에 도달하면 손목을 회전하고 팔을 완전히 펴면서 케틀벨을 머리 위로 밀어냅니다. 케틀벨을 처음 위치로 낮추고 원하는 반복 횟수까지 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell dans chaque main, bras tendus devant tes cuisses. Fléchis légèrement les genoux et bascule vers l''avant au niveau des hanches en gardant le dos plat et la poitrine relevée. En un seul mouvement explosif, étends tes hanches, tes genoux et tes chevilles, et tire simultanément les kettlebells vers tes épaules. Lorsque les kettlebells atteignent la hauteur des épaules, fais pivoter tes poignets et propulse les kettlebells au-dessus de la tête en étendant complètement tes bras. Abaisse les kettlebells jusqu''à la position de départ et répète pour le nombre de répétitions souhaité."}'::jsonb, 'images/0529-M74kdvm.jpg', 'videos/0529-M74kdvm.gif', '© Gym visual — https://gymvisual.com/'),
(530, 'kettlebell double windmill', 'waist', 'strength', 'waist', 'kettlebell', 'shoulders', 'abs', '["shoulders","hamstrings"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in your right hand. Extend your right arm overhead, keeping your eyes on the kettlebell. Rotate your left foot 45 degrees to the left and your right foot 90 degrees to the right. Bend at the waist to the left, keeping your right arm extended overhead. Lower the kettlebell towards the ground, reaching towards your left foot. Pause for a moment, then engage your core and push through your right foot to return to the starting position. Repeat for the desired number of repetitions, then switch sides.","it":"Stai con i piedi alla larghezza delle spalle, tenendo un kettlebell nella mano destra. Estendi il braccio destro sopra la testa, mantenendo gli occhi sul kettlebell. Ruota il piede sinistro di 45 gradi a sinistra e il piede destro di 90 gradi a destra. Piega la vita verso sinistra, mantenendo il braccio destro esteso sopra la testa. Abbassa il kettlebell verso terra, allungandolo verso il piede sinistro. Fai una pausa per un momento, quindi coinvolgi il core e spingi attraverso il piede destro per tornare alla posizione di partenza. Ripeti per il numero di ripetizioni desiderato, quindi cambia lato.","tr":"Ayaklarınızı omuz genişliğinde açın ve sağ elinizde bir kettlebell tutun. Gözlerinizi kettlebell''den ayırmadan sağ kolunuzu yukarı doğru uzatın. Sol ayağınızı 45 derece sola, sağ ayağınızı ise 90 derece sağa döndürün. Sağ kolunuzu başınızın üzerinde uzatarak belinizi sola doğru bükün. Kettlebell''i sol ayağınıza doğru uzanarak yere doğru indirin. Bir an duraklayın, ardından merkez bölgenizi devreye sokun ve başlangıç ​​pozisyonuna dönmek için sağ ayağınızı itin. İstenilen tekrar sayısı kadar tekrarlayın, ardından taraf değiştirin.","es":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en la mano derecha. Extiende el brazo derecho por encima de la cabeza, manteniendo la mirada en la pesa rusa. Rota el pie izquierdo 45 grados hacia la izquierda y el pie derecho 90 grados hacia la derecha. Flexiona la cintura hacia la izquierda, manteniendo el brazo derecho extendido por encima de la cabeza. Baja la pesa rusa hacia el suelo, extendiéndote hacia el pie izquierdo. Haz una pausa breve, luego activa el core y empuja con el pie derecho para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.","ru":"Встаньте, ноги на ширине плеч, в правой руке держите гирю. Вытяните правую руку над головой, не отрывая глаз от гири. Поверните левую ногу на 45 градусов влево, а правую — на 90 градусов вправо. Согнитесь в талии влево, удерживая правую руку вытянутой над головой. Опустите гирю к земле, дотягиваясь до левой ноги. Сделайте паузу на мгновение, затем задействуйте корпус и толкните правую ногу, чтобы вернуться в исходное положение. Повторите желаемое количество повторений, затем поменяйте сторону.","zh":"双脚分开与肩同宽站立，右手握住壶铃。 将右臂伸过头顶，眼睛盯着壶铃。 左脚向左旋转 45 度，右脚向右旋转 90 度。 腰部向左弯曲，保持右臂伸过头顶。 将壶铃向地面降低，伸向左脚。 暂停片刻，然后启动核心并推动右脚返回起始位置。 重复所需的重复次数，然后换边。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपने दाहिने हाथ में केटलबेल पकड़ लें। अपनी आँखें केटलबेल पर रखते हुए, अपना दाहिना हाथ ऊपर की ओर फैलाएँ। अपने बाएँ पैर को बाईं ओर 45 डिग्री और अपने दाहिने पैर को दाईं ओर 90 डिग्री घुमाएँ। अपने दाहिने हाथ को ऊपर की ओर फैलाए रखते हुए, कमर को बाईं ओर झुकाएँ। अपने बाएँ पैर की ओर पहुँचते हुए केटलबेल को ज़मीन की ओर नीचे करें। एक पल के लिए रुकें, फिर अपने कोर को संलग्न करें और प्रारंभिक स्थिति में लौटने के लिए अपने दाहिने पैर से धक्का दें। दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w prawej dłoni. Wyciągnij prawą rękę nad głowę, utrzymując wzrok na kettlebellu. Obróć lewą stopę o 45 stopni w lewo, a prawą stopę o 90 stopni w prawo. Wykonaj skłon w talii w lewo, utrzymując prawą rękę wyciągniętą nad głowę. Opuść kettlebell w kierunku podłogi, sięgając w stronę lewej stopy. Zatrzymaj się na chwilę, a następnie napnij mięśnie brzucha i odepchnij się przez prawą stopę, wracając do pozycji wyjściowej. Powtórz zgodnie z zaplanowaną liczbą powtórzeń, a następnie zmień stronę.","ko":"다리를 어깨 너비로 벌리고 오른손으로 케틀벨을 잡습니다. 오른팔을 머리 위로 펼치고 케틀벨을 바라봅니다. 왼발을 45도 왼쪽으로 회전하고 오른발을 90도 오른쪽으로 회전합니다. 왼쪽으로 허리를 구부리면서 오른팔을 머리 위로 펼친 상태를 유지합니다. 케틀벨을 땅 쪽으로 낮추면서 왼발 쪽을 향해 뻗습니다. 잠깐 멈춘 후 코어에 힘을 주고 오른발로 밀어내면서 처음 위치로 돌아옵니다. 원하는 반복 횟수를 완료한 후 반대쪽을 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell dans ta main droite. Étends ton bras droit au-dessus de la tête, en gardant les yeux sur le kettlebell. Fais tourner ton pied gauche de 45 degrés vers la gauche et ton pied droit de 90 degrés vers la droite. Penche-toi vers la gauche au niveau de la taille en gardant ton bras droit tendu au-dessus de ta tête. Abaisse le kettlebell vers le sol, en tendant vers ton pied gauche. Marque une pause, puis gaine ta sangle abdominale et pousse sur ton pied droit pour revenir à la position de départ. Répète le nombre de répétitions souhaité, puis change de côté."}'::jsonb, 'images/0530-OaE7CpD.jpg', 'videos/0530-OaE7CpD.gif', '© Gym visual — https://gymvisual.com/'),
(531, 'kettlebell extended range one arm press on floor', 'chest', 'strength', 'chest', 'kettlebell', 'triceps', 'pectorals', '["triceps","shoulders"]'::jsonb, '{"en":"Start by lying on your back on the floor with your knees bent and feet flat on the ground. Hold a kettlebell in one hand, with your palm facing towards your feet. Extend your arm straight up towards the ceiling, keeping your elbow locked and your wrist straight. Slowly lower the kettlebell back down to the starting position, maintaining control throughout the movement. Repeat for the desired number of repetitions, then switch to the other arm.","it":"Inizia sdraiandoti sulla schiena sul pavimento con le ginocchia piegate e i piedi appoggiati a terra. Tieni un kettlebell in una mano, con il palmo rivolto verso i piedi. Estendi il braccio verso il soffitto, mantenendo il gomito bloccato e il polso dritto. Abbassa lentamente il kettlebell nella posizione iniziale, mantenendo il controllo durante tutto il movimento. Ripeti per il numero di ripetizioni desiderato, quindi passa all''altro braccio.","tr":"Dizleriniz bükülmüş ve ayaklarınız yere düz basacak şekilde yere sırt üstü yatarak başlayın. Avucunuz ayaklarınıza bakacak şekilde bir elinizde kettlebell''i tutun. Dirseğinizi kilitli ve bileğinizi düz tutarak kolunuzu düz bir şekilde tavana doğru uzatın. Hareket boyunca kontrolü koruyarak kettlebell''i yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından diğer kola geçin.","es":"Comienza acostado boca arriba en el suelo con las rodillas dobladas y los pies planos sobre el suelo. Sujeta una pesa rusa con una mano, con la palma hacia los pies. Extiende el brazo recto hacia el techo, manteniendo el codo bloqueado y la muñeca recta. Baja lentamente la pesa rusa de vuelta a la posición inicial, manteniendo el control durante todo el movimiento. Repite el número de repeticiones deseado, luego cambia al otro brazo.","ru":"Начните с того, что лягте на спину на пол, согните колени и поставьте ступни на землю. Возьмите гирю в одну руку ладонью к ногам. Вытяните руку прямо вверх к потолку, сохраняя локоть зафиксированным, а запястье прямым. Медленно опустите гирю обратно в исходное положение, сохраняя контроль на протяжении всего движения. Повторите желаемое количество повторений, затем переключитесь на другую руку.","zh":"首先仰卧在地板上，膝盖弯曲，双脚平放在地面上。 一只手握住壶铃，手掌朝向脚部。 将手臂伸直向上伸向天花板，保持肘部锁定且手腕伸直。 慢慢地将壶铃放回起始位置，在整个运动过程中保持控制。 重复所需的重复次数，然后换到另一只手臂。","hi":"अपने घुटनों को मोड़कर और पैरों को जमीन पर सपाट रखते हुए अपनी पीठ के बल फर्श पर लेटकर शुरुआत करें। एक हाथ में केटलबेल पकड़ें, आपकी हथेली आपके पैरों की ओर हो। अपनी बांह को छत की ओर सीधा फैलाएं, अपनी कोहनी को लॉक रखें और अपनी कलाई को सीधा रखें। पूरे आंदोलन के दौरान नियंत्रण बनाए रखते हुए, केटलबेल को धीरे-धीरे प्रारंभिक स्थिति में वापस लाएँ। दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।","pl":"Zacznij, leżąc na plecach na podłodze z ugiętymi kolanami i stopami płasko opartymi o podłogę. Trzymaj kettlebell w jednej dłoni, dłoń skierowana w stronę stóp. Wyprostuj ramię prosto w kierunku sufitu, trzymając łokieć zablokowany, a nadgarstek prosty. Powoli opuść kettlebell do pozycji wyjściowej, zachowując kontrolę przez cały ruch. Powtórz zgodnie z zaplanowaną liczbą powtórzeń, a następnie zmień rękę.","ko":"바닥에 등을 대고 누워 무릎을 구부리고 발을 땅에 놓습니다. 한 손으로 케틀벨을 잡되 손바닥이 발을 향하도록 합니다. 팔꿈치를 펴고 천장을 향해 팔을 쭉 펼칩니다. 케틀벨을 천천히 처음 위치로 낮추면서 전 동작을 통제합니다. 원하는 반복 횟수를 완료한 후 반대쪽 팔로 반복합니다.","fr":"Commence allongé sur le dos sur le sol, les genoux fléchis et les pieds à plat sur le sol. Tiens un kettlebell dans une main, la paume tournée vers tes pieds. Étends ton bras droit vers le plafond, en gardant ton coude verrouillé et ton poignet droit. Abaisse lentement le kettlebell vers la position de départ, en gardant le contrôle tout au long du mouvement. Répète le nombre de répétitions souhaité, puis passe à l''autre bras."}'::jsonb, 'images/0531-rseLfH3.jpg', 'videos/0531-rseLfH3.gif', '© Gym visual — https://gymvisual.com/'),
(532, 'kettlebell figure 8', 'waist', 'strength', 'waist', 'kettlebell', 'shoulders', 'abs', '["shoulders","forearms"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in one hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Pass the kettlebell between your legs, switching hands as it reaches the back of your legs. As the kettlebell comes forward, pass it to the other hand between your legs. Continue passing the kettlebell between your legs in a figure 8 motion. Maintain a steady pace and engage your core throughout the exercise. Repeat for the desired number of repetitions.","it":"Stai con i piedi alla larghezza delle spalle, tenendo un kettlebell in una mano. Piega leggermente le ginocchia e fai perno in avanti sui fianchi, mantenendo la schiena dritta. Passa il kettlebell tra le gambe, cambiando mano quando raggiunge la parte posteriore delle gambe. Mentre il kettlebell si fa avanti, passalo all''altra mano tra le gambe. Continua a passare il kettlebell tra le gambe con un movimento a figura 8. Mantieni un ritmo costante e coinvolgi il core durante l''esercizio. Ripetere per il numero di ripetizioni desiderato.","tr":"Bir elinizde kettlebell tutarak ayaklarınızı omuz genişliğinde açın. Dizlerinizi hafifçe bükün ve sırtınızı düz tutarak kalçalarınızdan öne doğru eğilin. Kettlebell''i bacaklarınızın arasından geçirin, bacaklarınızın arkasına ulaştığında ellerinizi değiştirin. Kettlebell öne doğru geldiğinde onu bacaklarınızın arasından diğer elinize geçirin. Kettlebell''i bacaklarınızın arasından 8 şeklindeki hareketle geçirmeye devam edin. Sabit bir tempoyu koruyun ve egzersiz boyunca merkez bölgenizi meşgul edin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Pasa la pesa rusa entre las piernas, cambiándola de mano cuando llegue detrás de las piernas. Cuando la pesa rusa vuelva hacia adelante, pásala a la otra mano entre las piernas. Continúa pasando la pesa rusa entre las piernas con un movimiento en forma de ocho. Mantén un ritmo constante y activa el core durante todo el ejercicio. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, в одной руке держите гирю. Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой. Пропустите гирю между ног, меняя руки, когда она достигает задней части ног. Когда гиря выйдет вперед, передайте ее в другую руку между ног. Продолжайте передавать гирю между ног, совершая движения в форме восьмерки. Поддерживайте устойчивый темп и задействуйте мышцы корпуса на протяжении всего упражнения. Повторите необходимое количество повторений.","zh":"双脚分开与肩同宽站立，一只手握住壶铃。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将壶铃放在双腿之间，当壶铃到达双腿后部时交换双手。 当壶铃向前移动时，将其传递到两腿之间的另一只手。 继续以 8 字形动作将壶铃传递到双腿之间。 在整个练习过程中保持稳定的节奏并调动核心力量。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और एक हाथ में केटलबेल पकड़ लें। अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें। केटलबेल को अपने पैरों के बीच से गुजारें, जैसे ही यह आपके पैरों के पीछे तक पहुंचे, हाथ बदल लें। जैसे ही केटलबेल आगे आए, उसे अपने पैरों के बीच दूसरे हाथ में दे दें। अपने पैरों के बीच केटलबेल को आकृति 8 की गति में घुमाना जारी रखें। एक स्थिर गति बनाए रखें और पूरे अभ्यास के दौरान अपने कोर को संलग्न रखें। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w jednej dłoni. Ugnij lekko kolana i wykonaj skłon w biodrach, utrzymując proste plecy. Przełóż kettlebell między nogami, zmieniając rękę, gdy dotrze za nogi. Gdy kettlebell wraca do przodu, przekaż go do drugiej dłoni między nogami. Kontynuuj przekładanie kettlebella między nogami ruchem w kształcie ósemki. Utrzymuj stałe tempo i napinaj mięśnie brzucha przez cały czas trwania ćwiczenia. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"다리를 어깨 너비로 벌리고 한 손으로 케틀벨을 잡습니다. 무릎을 살짝 구부리고 허리에서 구부리면서 등을 곧게 펴줍니다. 케틀벨을 양다리 사이를 통과시키고 다리 뒤쪽에 도달할 때 손을 바꿉니다. 케틀벨이 앞으로 올 때 양다리 사이를 통과시키면서 손을 다시 바꿉니다. 케틀벨을 양다리 사이에서 피겨 8 모양으로 계속 움직입니다. 전체 운동 중 꾸준한 속도를 유지하고 코어에 힘을 줍니다. 원하는 반복 횟수까지 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell d''une main. Fléchis légèrement les genoux et bascule vers l''avant au niveau des hanches en gardant le dos droit. Fais passer la kettlebell entre tes jambes, en changeant de main lorsqu''elle arrive derrière tes jambes. Lorsque le kettlebell revient vers l''avant, passe-le à l''autre main entre tes jambes. Continue à passer la kettlebell entre tes jambes dans un mouvement en huit. Maintiens un rythme régulier et gaine ta sangle abdominale pendant tout l''exercice. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0532-L4ay0PW.jpg', 'videos/0532-L4ay0PW.gif', '© Gym visual — https://gymvisual.com/'),
(533, 'kettlebell front squat', 'upper legs', 'strength', 'upper legs', 'kettlebell', 'quadriceps', 'glutes', '["quadriceps","hamstrings","calves"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, toes slightly turned out. Hold the kettlebell with both hands in front of your chest, close to your body. Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair. Lower until your thighs are parallel to the ground, or as low as you can comfortably go. Drive through your heels to stand back up, squeezing your glutes at the top. Repeat for the desired number of repetitions.","it":"Stai con i piedi alla larghezza delle spalle, le dita leggermente rivolte verso l''esterno. Tieni il kettlebell con entrambe le mani davanti al petto, vicino al corpo. Coinvolgi il tuo core e mantieni il petto sollevato mentre abbassi i fianchi verso il basso e all''indietro, come se fossi seduto su una sedia. Abbassati finché le cosce non sono parallele al suolo o il più in basso possibile. Spingi i talloni per rialzarti, contraendo i glutei nella parte superiore. Ripetere per il numero di ripetizioni desiderato.","tr":"Ayaklarınız omuz genişliğinde açık, ayak parmaklarınız hafifçe dışa dönük olacak şekilde ayakta durun. Kettlebell''i iki elinizle göğsünüzün önünde, vücudunuza yakın tutun. Merkez bölgenizi devreye sokun ve sanki bir sandalyede oturuyormuş gibi kalçalarınızı aşağı ve geriye doğru indirirken göğsünüzü yukarıda tutun. Uyluklarınız yere paralel veya rahatça gidebildiğiniz kadar alçaltın. Kalçalarınızı üst kısımda sıkarak ayağa kalkmak için topuklarınızın üzerinden geçin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la pesa rusa con ambas manos frente al pecho, cerca del cuerpo. Activa el core y mantén el pecho elevado mientras bajas las caderas hacia abajo y hacia atrás, como si te sentaras en una silla. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte más alta. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, носки слегка развернуты наружу. Держите гирю обеими руками перед грудью, близко к телу. Напрягите корпус и держите грудь поднятой, опуская бедра вниз и назад, как будто вы садитесь на стул. Опускайтесь до тех пор, пока бедра не станут параллельны земле или настолько низко, насколько вам будет удобно. Протолкните пятки, чтобы встать, сжимая ягодицы вверху. Повторите необходимое количество повторений.","zh":"站立，双脚分开与肩同宽，脚趾稍微向外。 双手将壶铃放在胸前，靠近身体。 收紧核心并保持挺胸，同时降低臀部和向后倾斜，就像坐在椅子上一样。 降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。 通过脚跟发力站起来，在顶部挤压臀部。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर निकली हुई हों। केटलबेल को दोनों हाथों से अपनी छाती के सामने, अपने शरीर के करीब पकड़ें। अपने कोर को संलग्न करें और अपने कूल्हों को नीचे और पीछे करते समय अपनी छाती को ऊपर रखें, जैसे कि एक कुर्सी पर बैठे हों। तब तक नीचे जाएँ जब तक आपकी जाँघें ज़मीन के समानांतर न हो जाएँ, या जितना नीचे आप आराम से जा सकें। वापस खड़े होने के लिए अपनी एड़ियों के माध्यम से ड्राइव करें, शीर्ष पर अपने ग्लूट्स को निचोड़ें। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań ze stopami rozstawionymi na szerokość barków, palce stóp lekko skierowane na zewnątrz. Trzymaj kettlebell obiema dłońmi przed klatką piersiową, blisko ciała. Napnij mięśnie brzucha i utrzymuj uniesioną klatkę piersiową, opuszczając biodra w dół i do tyłu, jakbyś siadał na krześle. Opuść się, aż uda będą równoległe do podłoża, lub tak nisko, jak potrafisz wygodnie sięgnąć. Odepchnij się przez pięty, aby wrócić do pozycji stojącej, ściskając pośladki na górze ruchu. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"다리를 어깨 너비로 벌리고 발가락을 살짝 바깥쪽으로 향하게 합니다. 양손으로 케틀벨을 잡고 가슴 앞에 가깝게 유지합니다. 코어에 힘을 주고 가슴을 들어올린 상태로 엉덩이를 내렸다 뒤로 향하게 합니다. 다리가 바닥과 평행이 될 때까지 또는 편하게 할 수 있는 만큼 낮춥니다. 발 뒤꿈치로 밀어 일어나면서 둔부에 힘을 줍니다. 원하는 반복 횟수까지 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, les orteils légèrement tournés vers l''extérieur. Tiens le kettlebell des deux mains devant ta poitrine, près de ton corps. Gaine ta sangle abdominale et garde ta poitrine relevée pendant que tu abaisses tes hanches vers le bas et l''arrière, comme si tu t''asseyais sur une chaise. Descends jusqu''à ce que tes cuisses soient parallèles au sol, ou aussi bas que tu peux confortablement aller. Pousse sur tes talons pour te relever, en contractant tes fessiers en haut. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0533-DB0n8AG.jpg', 'videos/0533-DB0n8AG.gif', '© Gym visual — https://gymvisual.com/'),
(534, 'kettlebell goblet squat', 'upper legs', 'strength', 'upper legs', 'kettlebell', 'quadriceps', 'glutes', '["quadriceps","hamstrings","calves"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell close to your chest with both hands. Keeping your chest up and core engaged, lower your body down into a squat position by bending at the knees and hips. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.","it":"Stai con i piedi alla larghezza delle spalle, tenendo un kettlebell vicino al petto con entrambe le mani. Mantenendo il petto in alto e il core impegnato, abbassa il corpo in una posizione tozza piegando le ginocchia e i fianchi. Continua ad abbassare finché le cosce non sono parallele al suolo o il più in basso possibile. Fai una pausa per un momento in fondo, quindi spingi i talloni per tornare alla posizione di partenza. Ripetere per il numero di ripetizioni desiderato.","tr":"Ayaklarınızı omuz genişliğinde açın ve kettlebell''i iki elinizle göğsünüze yakın tutun. Göğsünüzü yukarıda ve göbek bölgenizi kapalı tutarak, dizlerinizi ve kalçalarınızı bükerek vücudunuzu çömelme pozisyonuna indirin. Uyluklarınız yere paralel veya rahatça gidebileceğiniz kadar alçalana kadar alçaltmaya devam edin. Altta bir an duraklayın, ardından başlangıç ​​pozisyonuna dönmek için topuklarınızı itin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa cerca del pecho con ambas manos. Manteniendo el pecho elevado y el core activado, baja el cuerpo a una posición de sentadilla flexionando las rodillas y las caderas. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, держите гирю обеими руками близко к груди. Удерживая грудь поднятой и напряженным корпус, опустите тело в присед, сгибая колени и бедра. Продолжайте опускаться до тех пор, пока ваши бедра не станут параллельны земле или настолько низко, насколько вам будет удобно. Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение. Повторите необходимое количество повторений.","zh":"双脚分开与肩同宽站立，双手握住壶铃靠近胸部。 保持胸部挺直，核心收紧，弯曲膝盖和臀部，将身体降低至蹲姿。 继续降低，直到大腿与地面平行，或者尽可能低。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, दोनों हाथों से केटलबेल को अपनी छाती के पास पकड़ें। अपनी छाती को ऊपर और मुख्य भाग को ऊपर रखते हुए, घुटनों और कूल्हों पर झुकते हुए अपने शरीर को स्क्वाट स्थिति में नीचे लाएँ। तब तक नीचे उतरना जारी रखें जब तक कि आपकी जांघें ज़मीन के समानांतर न हो जाएं, या उतना नीचे न आ जाएं जितना आप आराम से जा सकें। नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell blisko klatki piersiowej obiema dłońmi. Utrzymując uniesioną klatkę piersiową i napięty brzuch, opuść ciało do przysiadu, uginając kolana i biodra. Kontynuuj opuszczanie, aż uda będą równoległe do podłoża, lub tak nisko, jak potrafisz wygodnie sięgnąć. Zatrzymaj się na chwilę na dole, a następnie odepchnij się przez pięty, aby wrócić do pozycji wyjściowej. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"다리를 어깨 너비로 벌리고 양손으로 케틀벨을 가슴 가까이 잡습니다. 가슴을 들어올리고 코어에 힘을 주면서 무릎과 엉덩이를 구부려 스쿼트 자세로 내려갑니다. 다리가 바닥과 평행이 될 때까지 또는 편하게 할 수 있는 만큼 계속 낮춥니다. 바닥에서 잠깐 멈춘 후 발 뒤꿈치로 밀어 처음 위치로 돌아옵니다. 원하는 반복 횟수까지 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell près de ta poitrine à deux mains. En gardant la poitrine relevée et la sangle abdominale gainée, abaisse ton corps en position de squat en fléchissant les genoux et les hanches. Continue à descendre jusqu''à ce que tes cuisses soient parallèles au sol, ou aussi bas que tu peux confortablement aller. Marque une pause en bas, puis pousse sur tes talons pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0534-ZA8b5hc.jpg', 'videos/0534-ZA8b5hc.gif', '© Gym visual — https://gymvisual.com/'),
(535, 'kettlebell hang clean', 'upper legs', 'strength', 'upper legs', 'kettlebell', 'glutes', 'hamstrings', '["glutes","quadriceps","calves"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Lower the kettlebell towards the ground, allowing it to swing between your legs. Quickly extend your hips and knees, using the momentum to swing the kettlebell up to shoulder height. As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbow tucked in and the kettlebell resting on your forearm. Lower the kettlebell back down to the starting position between your legs, and repeat for the desired number of repetitions.","it":"Stai con i piedi alla larghezza delle spalle, tenendo un kettlebell davanti alle cosce. Piega leggermente le ginocchia e fai perno in avanti sui fianchi, mantenendo la schiena dritta. Abbassa il kettlebell verso terra, lasciandolo oscillare tra le gambe. Estendi rapidamente le anche e le ginocchia, sfruttando lo slancio per far oscillare il kettlebell all''altezza delle spalle. Quando il kettlebell raggiunge l''altezza delle spalle, ruota i polsi e afferra il kettlebell nella posizione di rack, con il gomito piegato e il kettlebell appoggiato sull''avambraccio. Abbassa il kettlebell nella posizione iniziale tra le gambe e ripeti per il numero di ripetizioni desiderato.","tr":"Ayaklarınızı omuz genişliğinde açarak, kettlebell''i uyluklarınızın önünde tutun. Dizlerinizi hafifçe bükün ve sırtınızı düz tutarak kalçalarınızdan öne doğru eğilin. Kettlebell''i yere doğru indirin ve bacaklarınızın arasında sallanmasına izin verin. Kettlebell''i omuz yüksekliğine kadar sallamak için momentumu kullanarak kalçalarınızı ve dizlerinizi hızla uzatın. Kettlebell omuz yüksekliğine ulaştığında, bileklerinizi döndürün ve kettlebell''i raf pozisyonunda, dirseğiniz içeri sokulmuş ve kettlebell ön kolunuza dayanacak şekilde yakalayın. Kettlebell''i bacaklarınızın arasındaki başlangıç ​​pozisyonuna indirin ve istediğiniz tekrar sayısı kadar tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente a los muslos. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Baja la pesa rusa hacia el suelo, dejando que se balancee entre las piernas. Extiende rápidamente las caderas y las rodillas, usando el impulso para hacer que la pesa rusa suba hasta la altura del hombro. Cuando la pesa rusa llegue a la altura del hombro, rota las muñecas y atrápala en posición de descanso, con el codo pegado al cuerpo y la pesa rusa apoyada en el antebrazo. Baja la pesa rusa de vuelta a la posición inicial entre las piernas y repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, держа гирю перед бедрами. Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой. Опустите гирю к земле, позволяя ей покачиваться между ног. Быстро выпрямите бедра и колени, используя инерцию, чтобы поднять гирю на высоту плеч. Когда гиря достигнет уровня плеч, поверните запястья и поймайте гирю в положении стойки, прижав локоть к себе и положив гирю на предплечье. Опустите гирю обратно в исходное положение между ног и повторите желаемое количество повторений.","zh":"双脚分开与肩同宽站立，将壶铃放在大腿前面。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将壶铃放低至地面，使其在双腿之间摆动。 快速伸展臀部和膝盖，利用动量将壶铃摆动到肩膀高度。 当壶铃达到肩膀高度时，旋转手腕，将壶铃置于架子位置，肘部内收，壶铃靠在前臂上。 将壶铃放回双腿之间的起始位置，然后重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी जांघों के सामने केटलबेल पकड़ लें। अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें। केटलबेल को ज़मीन की ओर नीचे करें, जिससे यह आपके पैरों के बीच झूल सके। केटलबेल को कंधे की ऊंचाई तक घुमाने के लिए गति का उपयोग करते हुए, जल्दी से अपने कूल्हों और घुटनों को फैलाएं। जैसे ही केटलबेल कंधे की ऊंचाई तक पहुंचती है, अपनी कलाइयों को घुमाएं और केटलबेल को रैक स्थिति में पकड़ें, अपनी कोहनी को अंदर की ओर रखें और केटलबेल को अपने अग्रबाहु पर टिकाएं। केटलबेल को वापस अपने पैरों के बीच प्रारंभिक स्थिति में लाएँ, और वांछित संख्या में दोहराव के लिए दोहराएं।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell przed udami. Ugnij lekko kolana i wykonaj skłon w biodrach, utrzymując proste plecy. Opuść kettlebell w kierunku podłogi, pozwalając mu huśtać się między nogami. Szybko wyprostuj biodra i kolana, wykorzystując pęd, aby wywindować kettlebell na wysokość barku. Gdy kettlebell osiągnie wysokość barku, obróć nadgarstki i złap go w pozycji podpartej, z łokciem przy tułowiu, a kettlebellem opartym na przedramieniu. Opuść kettlebell z powrotem do pozycji wyjściowej między nogami i powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"다리를 어깨 너비로 벌리고 허벅지 앞에 케틀벨을 잡습니다. 무릎을 살짝 구부리고 허리에서 구부리면서 등을 곧게 펴줍니다. 케틀벨을 아래로 낮추면서 양다리 사이에서 흔들리게 합니다. 빠르게 엉덩이와 무릎을 펼치면서 모멘텀을 사용하여 케틀벨을 어깨 높이까지 흔듭니다. 케틀벨이 어깨 높이에 도달하면 손목을 회전시키고 랙 자세로 잡습니다. 팔꿈치를 안쪽으로 모으고 케틀벨이 팔뚝에 얹혀 있습니다. 케틀벨을 양다리 사이 처음 위치로 낮춘 후 원하는 반복 횟수까지 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell devant tes cuisses. Fléchis légèrement les genoux et bascule vers l''avant au niveau des hanches en gardant le dos droit. Abaisse le kettlebell vers le sol, en le laissant se balancer entre tes jambes. Étends rapidement tes hanches et tes genoux, en utilisant l''élan pour faire monter le kettlebell à hauteur des épaules. Lorsque le kettlebell atteint la hauteur des épaules, fais pivoter tes poignets et réceptionne le kettlebell en position rack, le coude rentré et le kettlebell reposant sur ton avant-bras. Abaisse le kettlebell jusqu''à la position de départ entre tes jambes, et répète pour le nombre de répétitions souhaité."}'::jsonb, 'images/0535-LHWF7us.jpg', 'videos/0535-LHWF7us.gif', '© Gym visual — https://gymvisual.com/'),
(536, 'kettlebell lunge pass through', 'upper legs', 'strength', 'upper legs', 'kettlebell', 'quadriceps', 'glutes', '["quadriceps","hamstrings","calves"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands. Take a step forward with your right foot, lowering your body into a lunge position. As you lunge forward, pass the kettlebell under your right thigh and transfer it to your left hand. Push off with your right foot to return to the starting position, while simultaneously passing the kettlebell back to your right hand. Repeat the lunge on the opposite side, passing the kettlebell under your left thigh. Continue alternating lunges and passing the kettlebell between hands for the desired number of repetitions.","it":"Stai con i piedi alla larghezza delle spalle, tenendo un kettlebell davanti al petto con entrambe le mani. Fai un passo avanti con il piede destro, abbassando il corpo in una posizione di affondo. Mentre ti affondi in avanti, passa il kettlebell sotto la coscia destra e trasferiscilo nella mano sinistra. Spingi con il piede destro per tornare alla posizione di partenza, mentre contemporaneamente passi il kettlebell alla mano destra. Ripeti l''affondo sul lato opposto, passando il kettlebell sotto la coscia sinistra. Continua alternando gli affondi e passando il kettlebell tra le mani per il numero desiderato di ripetizioni.","tr":"Ayaklarınızı omuz genişliğinde açın ve kettlebell''i iki elinizle göğsünüzün önünde tutun. Sağ ayağınızla öne doğru bir adım atın ve vücudunuzu hamle pozisyonuna indirin. İleriye doğru hamle yaparken kettlebell''i sağ uyluğunuzun altından geçirin ve sol elinize aktarın. Başlangıç ​​pozisyonuna dönmek için sağ ayağınızla itin ve aynı anda kettlebell''i tekrar sağ elinize geçirin. Kettlebell''i sol uyluğunuzun altından geçirerek hamleyi karşı tarafta tekrarlayın. İstenilen sayıda tekrar için alternatif hamlelere ve kettlebell''i elleriniz arasında geçirmeye devam edin.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Mientras avanzas en la zancada, pasa la pesa rusa por debajo del muslo derecho y trasládala a la mano izquierda. Empuja con el pie derecho para volver a la posición inicial, mientras pasas la pesa rusa de vuelta a la mano derecha al mismo tiempo. Repite la zancada en el lado opuesto, pasando la pesa rusa por debajo del muslo izquierdo. Continúa alternando zancadas y pasando la pesa rusa entre las manos durante el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, удерживая гирю перед грудью обеими руками. Сделайте шаг вперед правой ногой, опуская тело в положение выпада. Делая выпад вперед, пропустите гирю под правое бедро и перенесите ее в левую руку. Оттолкнитесь правой ногой, чтобы вернуться в исходное положение, одновременно передавая гирю обратно в правую руку. Повторите выпад на противоположную сторону, проведя гирю под левым бедром. Продолжайте чередовать выпады и передавать гирю между руками желаемое количество повторений.","zh":"双脚分开与肩同宽站立，双手握住壶铃放在胸前。 右脚向前迈出一步，将身体降低至弓步位置。 当你向前弓步时，将壶铃传递到右大腿下方，然后将其转移到左手。 用右脚蹬地回到起始位置，同时将壶铃传回右手。 在另一侧重复弓步，将壶铃传递到左大腿下方。 继续交替弓步并在双手之间传递壶铃，达到所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, दोनों हाथों से अपनी छाती के सामने केटलबेल पकड़ें। अपने दाहिने पैर से एक कदम आगे बढ़ाएं, अपने शरीर को नीचे झुकाकर स्थिति में लाएं। जैसे ही आप आगे बढ़ते हैं, केटलबेल को अपनी दाहिनी जांघ के नीचे से गुजारें और इसे अपने बाएं हाथ में स्थानांतरित करें। प्रारंभिक स्थिति में लौटने के लिए अपने दाहिने पैर से धक्का दें, साथ ही केटलबेल को अपने दाहिने हाथ पर वापस पास करें। केटलबेल को अपनी बायीं जांघ के नीचे से गुजारते हुए, विपरीत दिशा में लंज को दोहराएं। दोहराव की वांछित संख्या के लिए बारी-बारी से फेफड़े चलाना और केटलबेल को हाथों के बीच से गुजारना जारी रखें।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell przed klatką piersiową obiema dłońmi. Zrób krok do przodu prawą nogą, opuszczając ciało do wykroku. Wykonując wykrok do przodu, przełóż kettlebell pod prawym udem i przekaż go do lewej dłoni. Odepchnij się prawą stopą, aby wrócić do pozycji wyjściowej, jednocześnie przekazując kettlebell z powrotem do prawej dłoni. Powtórz wykrok po przeciwnej stronie, przekładając kettlebell pod lewym udem. Kontynuuj naprzemienne wykroki i przekładanie kettlebella między dłońmi zgodnie z zaplanowaną liczbą powtórzeń.","ko":"다리를 어깨 너비로 벌리고 양손으로 가슴 앞에 케틀벨을 잡습니다. 오른발로 한 걸음 앞으로 내디디면서 런지 자세로 내려갑니다. 앞으로 런지할 때 케틀벨을 오른쪽 허벅지 아래로 통과시키고 왼손으로 옮깁니다. 오른발로 밀어 처음 위치로 돌아오면서 동시에 케틀벨을 오른손으로 다시 옮깁니다. 왼발로 반대쪽 런지를 하고 케틀벨을 왼쪽 허벅지 아래로 통과시킵니다. 원하는 반복 횟수까지 런지와 케틀벨 패싱을 교대로 계속합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell devant ta poitrine à deux mains. Fais un pas en avant avec le pied droit, en abaissant ton corps en position de fente. En te fendant vers l''avant, fais passer le kettlebell sous ta cuisse droite et transfère-le dans ta main gauche. Pousse sur ton pied droit pour revenir à la position de départ, tout en repassant simultanément le kettlebell dans ta main droite. Répète la fente du côté opposé, en passant le kettlebell sous ta cuisse gauche. Continue à alterner les fentes et à passer la kettlebell d''une main à l''autre pour le nombre de répétitions souhaité."}'::jsonb, 'images/0536-WKMQzCD.jpg', 'videos/0536-WKMQzCD.gif', '© Gym visual — https://gymvisual.com/'),
(537, 'kettlebell one arm clean and jerk', 'shoulders', 'strength', 'shoulders', 'kettlebell', 'triceps', 'delts', '["triceps","core"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip. Bend your knees slightly and hinge at the hips, lowering the kettlebell between your legs. Explosively extend your hips, knees, and ankles, using the momentum to swing the kettlebell up to shoulder height. As the kettlebell reaches shoulder height, rotate your wrist and punch your hand straight up, locking out your arm overhead. Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions.","it":"Stare con i piedi alla larghezza delle spalle, tenendo un kettlebell in una mano con una presa prona. Piega leggermente le ginocchia e fai perno sui fianchi, abbassando il kettlebell tra le gambe. Estendi in modo esplosivo anche, ginocchia e caviglie, sfruttando lo slancio per far oscillare il kettlebell fino all''altezza delle spalle. Quando il kettlebell raggiunge l''altezza delle spalle, ruota il polso e colpisci con la mano verso l''alto, bloccando il braccio sopra la testa. Abbassare nuovamente il kettlebell nella posizione iniziale e ripetere per il numero di ripetizioni desiderato.","tr":"Ayaklarınızı omuz genişliğinde açın ve bir elinizde kettlebell''i üstten kavrayarak tutun. Dizlerinizi hafifçe bükün ve kalçalarınıza yaslanın, kettlebell''i bacaklarınızın arasına indirin. Kettlebell''i omuz yüksekliğine kadar sallamak için momentumu kullanarak kalçalarınızı, dizlerinizi ve ayak bileklerinizi patlayıcı bir şekilde uzatın. Kettlebell omuz yüksekliğine ulaştığında bileğinizi döndürün ve elinizi yukarı doğru yumruklayarak kolunuzu başınızın üzerinde kilitleyin. Kettlebell''i başlangıç ​​pozisyonuna indirin ve istenilen sayıda tekrar yapın.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono. Flexiona ligeramente las rodillas y inclínate desde las caderas, bajando la pesa rusa entre las piernas. Extiende explosivamente las caderas, las rodillas y los tobillos, usando el impulso para hacer que la pesa rusa suba hasta la altura del hombro. Cuando la pesa rusa llegue a la altura del hombro, rota la muñeca y lanza la mano recta hacia arriba, bloqueando el brazo por encima de la cabeza. Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, держите гирю в одной руке хватом сверху. Слегка согните колени и наклонитесь в бедрах, опуская гирю между ног. Резко выпрямите бедра, колени и лодыжки, используя инерцию, чтобы поднять гирю на высоту плеч. Когда гиря достигнет уровня плеч, поверните запястье и поднимите руку прямо вверх, зафиксировав руку над головой. Опустите гирю обратно в исходное положение и повторите желаемое количество повторений.","zh":"双脚分开与肩同宽站立，一只手握住壶铃，正手握住。 稍微弯曲膝盖并以臀部为铰链，将壶铃放在两腿之间。 爆发性地伸展你的臀部、膝盖和脚踝，利用动量将壶铃摆动到肩膀的高度。 当壶铃到达肩膀高度时，旋转手腕并向上挥拳，将手臂锁定在头顶上方。 将壶铃放回起始位置，然后重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े रहें, एक हाथ में केटलबेल को ओवरहैंड पकड़ के साथ पकड़ें। अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर टिकाएं, अपने पैरों के बीच केटलबेल को नीचे करें। केटलबेल को कंधे की ऊंचाई तक घुमाने के लिए गति का उपयोग करते हुए, अपने कूल्हों, घुटनों और टखनों को तेजी से फैलाएं। जैसे ही केटलबेल कंधे की ऊंचाई तक पहुंचती है, अपनी कलाई को घुमाएं और अपने हाथ को सीधा ऊपर की ओर मुक्का मारें, जिससे आपका हाथ ऊपर की ओर लॉक हो जाए। केटलबेल को वापस प्रारंभिक स्थिति में लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w jednej dłoni nachwytem. Ugnij lekko kolana i wykonaj skłon w biodrach, opuszczając kettlebell między nogami. Eksplozywnie wyprostuj biodra, kolana i stawy skokowe, wykorzystując pęd, aby wywindować kettlebell na wysokość barku. Gdy kettlebell osiągnie wysokość barku, obróć nadgarstek i wypchnij dłoń prosto w górę, blokując ramię nad głową. Opuść kettlebell z powrotem do pozycji wyjściowej i powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"다리를 어깨 너비로 벌리고 한 손으로 오버핸드 그립으로 케틀벨을 잡습니다. 무릎을 살짝 구부리고 허리에서 구부리면서 케틀벨을 양다리 사이로 낮춥니다. 엉덩이, 무릎, 발목을 폭발적으로 펼치면서 모멘텀을 사용하여 케틀벨을 어깨 높이까지 흔듭니다. 케틀벨이 어깨 높이에 도달하면 손목을 회전하고 팔을 펴면서 머리 위로 밀어냅니다. 케틀벨을 처음 위치로 낮추고 원하는 반복 횟수까지 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell d''une main en prise pronation. Fléchis légèrement les genoux et bascule au niveau des hanches en abaissant la kettlebell entre tes jambes. Étends de manière explosive tes hanches, tes genoux et tes chevilles, en utilisant l''élan pour balancer la kettlebell jusqu''à hauteur des épaules. Lorsque le kettlebell atteint la hauteur des épaules, fais pivoter ton poignet et propulse ta main bien droit vers le haut en verrouillant ton bras au-dessus de la tête. Abaisse le kettlebell jusqu''à la position de départ et répète pour le nombre de répétitions souhaité."}'::jsonb, 'images/0537-vzAxBtt.jpg', 'videos/0537-vzAxBtt.gif', '© Gym visual — https://gymvisual.com/'),
(1298, 'kettlebell one arm floor press', 'chest', 'strength', 'chest', 'kettlebell', 'triceps', 'pectorals', '["triceps","shoulders"]'::jsonb, '{"en":"Lie flat on your back on the floor with your knees bent and feet flat on the ground. Hold the kettlebell in one hand with your palm facing towards your feet and your arm extended straight up towards the ceiling. Slowly lower the kettlebell towards your chest by bending your elbow, keeping your upper arm close to your body. Pause for a moment when the kettlebell is just above your chest, then push it back up to the starting position by extending your elbow. Repeat for the desired number of repetitions, then switch to the other arm.","it":"Sdraiati sulla schiena sul pavimento con le ginocchia piegate e i piedi appoggiati a terra. Tieni il kettlebell in una mano con il palmo rivolto verso i piedi e il braccio teso verso il soffitto. Abbassa lentamente il kettlebell verso il petto piegando il gomito, mantenendo la parte superiore del braccio vicino al corpo. Fai una pausa per un momento quando il kettlebell è appena sopra il petto, quindi spingilo nuovamente nella posizione iniziale estendendo il gomito. Ripeti per il numero di ripetizioni desiderato, quindi passa all''altro braccio.","tr":"Dizleriniz bükülü ve ayaklarınız yere düz basacak şekilde yere sırt üstü yatın. Avucunuz ayaklarınıza bakacak ve kolunuz tavana doğru uzatılacak şekilde kettlebell''i bir elinizde tutun. Dirseğinizi bükerek, üst kolunuzu vücudunuza yakın tutarak kettlebell''i yavaşça göğsünüze doğru indirin. Kettlebell göğsünüzün hemen üzerindeyken bir an duraklayın, ardından dirseğinizi uzatarak başlangıç ​​pozisyonuna geri itin. İstenilen tekrar sayısı kadar tekrarlayın, ardından diğer kola geçin.","es":"Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo. Sujeta la pesa rusa con una mano con la palma hacia los pies y el brazo extendido recto hacia el techo. Baja lentamente la pesa rusa hacia el pecho flexionando el codo, manteniendo el brazo superior cerca del cuerpo. Haz una pausa cuando la pesa rusa esté justo encima del pecho, luego empújala de vuelta hacia arriba a la posición inicial extendiendo el codo. Repite el número de repeticiones deseado, luego cambia al otro brazo.","ru":"Лягте на спину на пол, согните колени и поставьте ступни на землю. Держите гирю в одной руке ладонью к ногам, а руку вытяните прямо к потолку. Медленно опустите гирю к груди, согнув локоть, держа плечо близко к телу. Сделайте паузу на мгновение, когда гиря окажется чуть выше груди, затем поднимите ее обратно в исходное положение, вытянув локоть. Повторите желаемое количество повторений, затем переключитесь на другую руку.","zh":"仰卧在地板上，膝盖弯曲，双脚平放在地面上。 一只手握住壶铃，手掌朝向脚部，手臂笔直向上伸向天花板。 弯曲肘部，慢慢将壶铃降低到胸部，保持上臂靠近身体。 当壶铃位于胸部正上方时暂停片刻，然后通过伸展肘部将壶铃推回起始位置。 重复所需的重复次数，然后换到另一只手臂。","hi":"अपने घुटनों को मोड़कर और पैरों को जमीन पर सपाट रखते हुए फर्श पर अपनी पीठ के बल लेट जाएं। केटलबेल को एक हाथ में पकड़ें, अपनी हथेली को अपने पैरों की ओर रखें और आपका हाथ छत की ओर सीधा फैला हुआ हो। अपनी कोहनी को मोड़कर, अपनी ऊपरी भुजा को अपने शरीर के पास रखते हुए केटलबेल को धीरे-धीरे अपनी छाती की ओर नीचे लाएँ। जब केटलबेल आपकी छाती के ठीक ऊपर हो तो एक पल के लिए रुकें, फिर अपनी कोहनी बढ़ाकर इसे वापस प्रारंभिक स्थिति में धकेलें। दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।","pl":"Połóż się płasko na plecach na podłodze z ugiętymi kolanami i stopami płasko opartymi o podłogę. Trzymaj kettlebell w jednej dłoni, dłoń skierowana w stronę stóp, ramię wyprostowane prosto w kierunku sufitu. Powoli opuść kettlebell w stronę klatki piersiowej, uginając łokieć i trzymając ramię blisko ciała. Zatrzymaj się na chwilę, gdy kettlebell znajdzie się tuż nad klatką piersiową, a następnie wypchnij go z powrotem do pozycji wyjściowej, prostując łokieć. Powtórz zgodnie z zaplanowaną liczbą powtórzeń, a następnie zmień rękę.","ko":"바닥에 등을 대고 누워 무릎을 구부리고 발을 땅에 놓습니다. 한 손으로 케틀벨을 잡되 손바닥이 발을 향하고 팔을 천장을 향해 쭉 펼칩니다. 팔꿈치를 구부리면서 케틀벨을 천천히 가슴 쪽으로 낮춥니다. 팔을 몸에 가깝게 유지합니다. 케틀벨이 가슴 바로 위에 오면 잠깐 멈춘 후 팔꿈치를 펴면서 처음 위치로 밀어 올립니다. 원하는 반복 횟수를 완료한 후 반대쪽 팔로 반복합니다.","fr":"Allonge-toi sur le dos au sol, les genoux fléchis et les pieds à plat au sol. Tiens le kettlebell dans une main, la paume tournée vers tes pieds et le bras étendu droit vers le plafond. Abaisse lentement le kettlebell vers ta poitrine en fléchissant le coude, en gardant le haut de ton bras près de ton corps. Marque une pause lorsque le kettlebell est juste au-dessus de ta poitrine, puis repousse-le vers le haut pour revenir à la position de départ en étendant ton coude. Répète le nombre de répétitions souhaité, puis passe à l''autre bras."}'::jsonb, 'images/1298-rg59QCH.jpg', 'videos/1298-rg59QCH.gif', '© Gym visual — https://gymvisual.com/'),
(538, 'kettlebell one arm jerk', 'shoulders', 'strength', 'shoulders', 'kettlebell', 'triceps', 'delts', '["triceps","core"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height. Bend your knees slightly and engage your core. Press the kettlebell overhead in a straight line, fully extending your arm. As you press the kettlebell overhead, simultaneously dip your knees and quickly straighten them to generate momentum. As the kettlebell reaches its highest point, quickly drop underneath it by bending your knees and hips. Catch the kettlebell with a slight bend in your knees and hips, and your arm fully extended overhead. Stand up straight, fully extending your knees and hips, and stabilize the kettlebell overhead. Lower the kettlebell back to the starting position by bending your knees and hips, and repeat for the desired number of repetitions.","it":"Stare con i piedi alla larghezza delle spalle, tenendo un kettlebell in una mano all''altezza delle spalle. Piega leggermente le ginocchia e coinvolgi il core. Premi il kettlebell sopra la testa in linea retta, estendendo completamente il braccio. Mentre premi il kettlebell sopra la testa, abbassa contemporaneamente le ginocchia e raddrizzale rapidamente per generare slancio. Quando il kettlebell raggiunge il punto più alto, scendi rapidamente sotto di esso piegando le ginocchia e le anche. Afferra il kettlebell con una leggera piegatura delle ginocchia e dei fianchi e con il braccio completamente esteso sopra la testa. Stai dritto, estendendo completamente le ginocchia e le anche, e stabilizza il kettlebell sopra la testa. Abbassa il kettlebell nella posizione iniziale piegando le ginocchia e le anche e ripeti per il numero di ripetizioni desiderato.","tr":"Ayaklarınızı omuz genişliğinde açın ve bir elinizde kettlebell''i omuz hizasında tutun. Dizlerinizi hafifçe bükün ve çekirdeğinizi çalıştırın. Kolunuzu tamamen uzatarak kettlebell''i düz bir çizgide yukarı doğru bastırın. Kettlebell''i başınızın üzerine doğru bastırırken aynı anda dizlerinizi indirin ve ivme oluşturmak için hızla düzeltin. Kettlebell en yüksek noktasına ulaştığında dizlerinizi ve kalçalarınızı bükerek hızla altına inin. Kettlebell''i dizlerinizi ve kalçalarınızı hafif bir şekilde bükerek ve kolunuz tamamen yukarı doğru uzatılmış halde yakalayın. Dizlerinizi ve kalçalarınızı tamamen uzatarak dik durun ve kettlebell''i başınızın üzerinde sabitleyin. Dizlerinizi ve kalçalarınızı bükerek kettlebell''i başlangıç ​​pozisyonuna indirin ve istediğiniz sayıda tekrar yapın.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro. Flexiona ligeramente las rodillas y activa el core. Presiona la pesa rusa por encima de la cabeza en línea recta, extendiendo el brazo por completo. Mientras presionas la pesa rusa por encima de la cabeza, flexiona las rodillas simultáneamente y estíralas rápidamente para generar impulso. Cuando la pesa rusa llegue a su punto más alto, baja rápidamente por debajo de ella flexionando las rodillas y las caderas. Atrapa la pesa rusa con una ligera flexión de rodillas y caderas, y el brazo completamente extendido por encima de la cabeza. Ponte de pie recto, extendiendo por completo las rodillas y las caderas, y estabiliza la pesa rusa por encima de la cabeza. Baja la pesa rusa de vuelta a la posición inicial flexionando las rodillas y las caderas, y repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, держа гирю в одной руке на уровне плеч. Слегка согните колени и задействуйте корпус. Выжмите гирю над головой по прямой линии, полностью выпрямляя руку. Жмя гирю над головой, одновременно опускайте колени и быстро выпрямляйте их, чтобы создать импульс. Когда гиря достигнет высшей точки, быстро опуститесь под нее, согнув колени и бедра. Возьмите гирю, слегка согнув колени и бедра и полностью вытянув руку над головой. Встаньте прямо, полностью выпрямив колени и бедра, и зафиксируйте гирю над головой. Опустите гирю обратно в исходное положение, сгибая колени и бедра, и повторите желаемое количество повторений.","zh":"双脚分开与肩同宽站立，一只手握住壶铃，与肩同高。 稍微弯曲膝盖并启动核心。 将壶铃沿直线压过头顶，充分伸展手臂。 当你将壶铃举过头顶时，同时弯曲膝盖并快速伸直以产生动力。 当壶铃到达最高点时，弯曲膝盖和臀部，快速落到壶铃下方。 膝盖和臀部稍微弯曲，抓住壶铃，手臂完全伸过头顶。 站直，充分伸展膝盖和臀部，并将壶铃稳定在头顶上。 弯曲膝盖和臀部，将壶铃放回起始位置，然后重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, एक हाथ में कंधे की ऊंचाई पर केटलबेल पकड़ें। अपने घुटनों को थोड़ा मोड़ें और अपने कोर को संलग्न करें। अपनी बांह को पूरी तरह फैलाते हुए केटलबेल को एक सीधी रेखा में ऊपर की ओर दबाएं। जैसे ही आप केटलबेल को ऊपर की ओर दबाते हैं, उसी समय अपने घुटनों को डुबोएं और गति उत्पन्न करने के लिए उन्हें जल्दी से सीधा करें। जैसे ही केटलबेल अपने उच्चतम बिंदु पर पहुंचे, अपने घुटनों और कूल्हों को मोड़कर जल्दी से इसके नीचे आ जाएं। अपने घुटनों और कूल्हों को थोड़ा मोड़कर और अपनी बांह को पूरी तरह ऊपर की ओर फैलाकर केटलबेल को पकड़ें। अपने घुटनों और कूल्हों को पूरी तरह फैलाते हुए सीधे खड़े हो जाएं और केटलबेल को सिर के ऊपर स्थिर कर लें। अपने घुटनों और कूल्हों को मोड़कर केटलबेल को शुरुआती स्थिति में वापस लाएं और वांछित संख्या में दोहराव के लिए दोहराएं।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w jednej dłoni na wysokości barku. Ugnij lekko kolana i napnij mięśnie brzucha. Wypchnij kettlebell nad głowę w linii prostej, w pełni prostując ramię. Wypychając kettlebell nad głowę, jednocześnie ugnij kolana i szybko je wyprostuj, aby wygenerować pęd. Gdy kettlebell osiągnie najwyższy punkt, szybko wejdź pod niego, uginając kolana i biodra. Złap kettlebell z lekkim ugięciem kolan i bioder, a ramię w pełni wyprostowane nad głową. Wyprostuj się, w pełni prostując kolana i biodra, oraz ustabilizuj kettlebell nad głową. Opuść kettlebell do pozycji wyjściowej, uginając kolana i biodra, i powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"다리를 어깨 너비로 벌리고 한 손으로 어깨 높이에서 케틀벨을 잡습니다. 무릎을 살짝 구부리고 코어에 힘을 줍니다. 일직선으로 케틀벨을 머리 위로 누르면서 팔을 완전히 펼칩니다. 케틀벨을 누를 때 무릎을 함께 구부렸다 재빠르게 펴서 모멘텀을 만듭니다. 케틀벨이 최고점에 도달하면 무릎과 엉덩이를 구부려 그 아래로 빠르게 내려갑니다. 무릎과 엉덩이를 약간 구부린 상태로 팔을 완전히 펴서 케틀벨을 잡습니다. 무릎과 엉덩이를 완전히 펼쳐 일어나 머리 위에서 케틀벨을 안정시킵니다. 무릎과 엉덩이를 구부려 케틀벨을 처음 위치로 낮춘 후 원하는 반복 횟수까지 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell d''une main à hauteur d''épaule. Fléchis légèrement les genoux et gaine ta sangle abdominale. Développe le kettlebell au-dessus de ta tête en ligne droite, en tendant complètement ton bras. En poussant le kettlebell au-dessus de ta tête, fléchis simultanément tes genoux et redresse-les rapidement pour générer de l''élan. Lorsque le kettlebell atteint son point le plus haut, glisse-toi rapidement en dessous en fléchissant tes genoux et tes hanches. Réceptionne la kettlebell avec une légère flexion des genoux et des hanches, et ton bras complètement tendu au-dessus de ta tête. Tiens-toi bien droit, en étendant complètement les genoux et les hanches, et stabilise le kettlebell au-dessus de la tête. Abaisse le kettlebell jusqu''à la position de départ en fléchissant tes genoux et tes hanches, et répète pour le nombre de répétitions souhaité."}'::jsonb, 'images/0538-S37C94C.jpg', 'videos/0538-S37C94C.gif', '© Gym visual — https://gymvisual.com/'),
(539, 'kettlebell one arm military press to the side', 'shoulders', 'strength', 'shoulders', 'kettlebell', 'triceps', 'delts', '["triceps","core"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height. Engage your core and keep your back straight. Press the kettlebell overhead, extending your arm fully. Pause for a moment at the top, then slowly lower the kettlebell back to the starting position. Repeat for the desired number of repetitions, then switch sides.","it":"Stare con i piedi alla larghezza delle spalle, tenendo un kettlebell in una mano all''altezza delle spalle. Coinvolgi il tuo core e mantieni la schiena dritta. Premi il kettlebell sopra la testa, estendendo completamente il braccio. Fermati per un momento in alto, quindi abbassa lentamente il kettlebell nella posizione iniziale. Ripeti per il numero di ripetizioni desiderato, quindi cambia lato.","tr":"Ayaklarınızı omuz genişliğinde açın ve bir elinizde kettlebell''i omuz hizasında tutun. Merkez bölgenizi devreye sokun ve sırtınızı düz tutun. Kolunuzu tamamen uzatarak kettlebell''i başınızın üzerine bastırın. Tepe noktasında bir süre duraklayın, ardından kettlebell''i yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından taraf değiştirin.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro. Activa el core y mantén la espalda recta. Presiona la pesa rusa por encima de la cabeza, extendiendo el brazo por completo. Haz una pausa breve en lo alto, luego baja lentamente la pesa rusa de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.","ru":"Встаньте, ноги на ширине плеч, держа гирю в одной руке на уровне плеч. Напрягите корпус и держите спину прямо. Жмите гирю над головой, полностью выпрямляя руку. Задержитесь на мгновение в верхней точке, затем медленно опустите гирю обратно в исходное положение. Повторите желаемое количество повторений, затем поменяйте сторону.","zh":"双脚分开与肩同宽站立，一只手握住壶铃，与肩同高。 启动你的核心并保持背部挺直。 将壶铃压过头顶，充分伸展手臂。 在顶部暂停片刻，然后慢慢将壶铃放回起始位置。 重复所需的重复次数，然后换边。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, एक हाथ में कंधे की ऊंचाई पर केटलबेल पकड़ें। अपने कोर को व्यस्त रखें और अपनी पीठ सीधी रखें। अपनी बांह को पूरी तरह फैलाते हुए केटलबेल को ऊपर की ओर दबाएं। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे केटलबेल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w jednej dłoni na wysokości barku. Napnij mięśnie brzucha i utrzymuj proste plecy. Wypchnij kettlebell nad głowę, w pełni prostując ramię. Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść kettlebell do pozycji wyjściowej. Powtórz zgodnie z zaplanowaną liczbą powtórzeń, a następnie zmień stronę.","ko":"다리를 어깨 너비로 벌리고 한 손으로 어깨 높이에서 케틀벨을 잡습니다. 코어에 힘을 주고 등을 곧게 펴줍니다. 케틀벨을 머리 위로 누르면서 팔을 완전히 펼칩니다. 최고점에서 잠깐 멈춘 후 케틀벨을 천천히 처음 위치로 낮춥니다. 원하는 반복 횟수를 완료한 후 반대쪽을 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell d''une main à hauteur d''épaule. Gaine ta sangle abdominale et garde ton dos droit. Développe le kettlebell au-dessus de ta tête, en tendant complètement ton bras. Marque une pause en haut, puis abaisse lentement le kettlebell pour revenir à la position de départ. Répète le nombre de répétitions souhaité, puis change de côté."}'::jsonb, 'images/0539-yCvYdi7.jpg', 'videos/0539-yCvYdi7.gif', '© Gym visual — https://gymvisual.com/'),
(540, 'kettlebell one arm push press', 'shoulders', 'strength', 'shoulders', 'kettlebell', 'triceps', 'delts', '["triceps","core"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder level. Bend your knees slightly and engage your core. Press the kettlebell overhead by extending your arm and fully extending your legs. Lower the kettlebell back to the starting position by bending your knees and bringing the kettlebell back to your shoulder. Repeat for the desired number of repetitions, then switch sides.","it":"Stai con i piedi alla larghezza delle spalle, tenendo un kettlebell in una mano all''altezza delle spalle. Piega leggermente le ginocchia e coinvolgi il core. Premi il kettlebell sopra la testa estendendo il braccio e estendendo completamente le gambe. Abbassa il kettlebell nella posizione iniziale piegando le ginocchia e riportando il kettlebell alla spalla. Ripeti per il numero di ripetizioni desiderato, quindi cambia lato.","tr":"Ayaklarınız omuz genişliğinde açık, bir elinizde kettlebell''i omuz hizasında tutarak ayakta durun. Dizlerinizi hafifçe bükün ve çekirdeğinizi çalıştırın. Kolunuzu uzatarak ve bacaklarınızı tamamen uzatarak kettlebell''i başınızın üzerine bastırın. Dizlerinizi bükerek ve kettlebell''i tekrar omzunuza getirerek kettlebell''i başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından taraf değiştirin.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro. Flexiona ligeramente las rodillas y activa el core. Presiona la pesa rusa por encima de la cabeza extendiendo el brazo y estirando por completo las piernas. Baja la pesa rusa de vuelta a la posición inicial flexionando las rodillas y devolviendo la pesa rusa al hombro. Repite el número de repeticiones deseado, luego cambia de lado.","ru":"Встаньте, ноги на ширине плеч, держа гирю в одной руке на уровне плеч. Слегка согните колени и задействуйте корпус. Нажмите гирю над головой, вытянув руку и полностью вытянув ноги. Опустите гирю обратно в исходное положение, согнув колени и вернув гирю на плечо. Повторите желаемое количество повторений, затем поменяйте сторону.","zh":"双脚分开与肩同宽站立，一只手握住壶铃，与肩同高。 稍微弯曲膝盖并启动核心。 伸展手臂并完全伸展双腿，将壶铃压过头顶。 弯曲膝盖并将壶铃放回肩膀，将壶铃放回起始位置。 重复所需的重复次数，然后换边。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, एक हाथ में कंधे के स्तर पर केटलबेल पकड़ें। अपने घुटनों को थोड़ा मोड़ें और अपने कोर को संलग्न करें। अपनी बांह को फैलाकर और अपने पैरों को पूरी तरह फैलाकर केटलबेल को ऊपर की ओर दबाएं। अपने घुटनों को मोड़कर और केटलबेल को वापस अपने कंधे पर लाकर केटलबेल को शुरुआती स्थिति में वापस लाएँ। दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w jednej dłoni na wysokości barku. Ugnij lekko kolana i napnij mięśnie brzucha. Wypchnij kettlebell nad głowę, prostując ramię i w pełni prostując nogi. Opuść kettlebell do pozycji wyjściowej, uginając kolana i sprowadzając kettlebell z powrotem do barku. Powtórz zgodnie z zaplanowaną liczbą powtórzeń, a następnie zmień stronę.","ko":"다리를 어깨 너비로 벌리고 한 손으로 어깨 높이에서 케틀벨을 잡습니다. 무릎을 살짝 구부리고 코어에 힘을 줍니다. 팔을 펴면서 다리를 완전히 펴서 케틀벨을 머리 위로 누릅니다. 무릎을 구부려 케틀벨을 어깨로 다시 낮춘 후 처음 위치로 돌아옵니다. 원하는 반복 횟수를 완료한 후 반대쪽을 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell d''une main à hauteur d''épaule. Fléchis légèrement les genoux et gaine ta sangle abdominale. Développe le kettlebell au-dessus de ta tête en tendant ton bras et en tendant complètement tes jambes. Abaisse le kettlebell jusqu''à la position de départ en fléchissant tes genoux et en ramenant le kettlebell à ton épaule. Répète le nombre de répétitions souhaité, puis change de côté."}'::jsonb, 'images/0540-osdXT3K.jpg', 'videos/0540-osdXT3K.gif', '© Gym visual — https://gymvisual.com/'),
(541, 'kettlebell one arm row', 'back', 'strength', 'back', 'kettlebell', 'biceps', 'upper back', '["biceps","forearms"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip. Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged. Pull the kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the kettlebell back down to the starting position. Repeat for the desired number of repetitions, then switch sides and repeat with the other arm.","it":"Stare con i piedi alla larghezza delle spalle, tenendo un kettlebell in una mano con una presa prona. Piega leggermente le ginocchia e fai perno in avanti sui fianchi, mantenendo la schiena dritta e il core impegnato. Tirare il kettlebell verso il petto, mantenendo il gomito vicino al corpo e stringendo insieme le scapole. Fare una pausa per un momento in alto, quindi abbassare lentamente il kettlebell nella posizione iniziale. Ripeti per il numero di ripetizioni desiderato, quindi cambia lato e ripeti con l''altro braccio.","tr":"Ayaklarınızı omuz genişliğinde açın ve bir elinizde kettlebell''i üstten kavrayarak tutun. Dizlerinizi hafifçe bükün ve kalçalarınızdan öne doğru eğilin, sırtınızı düz ve merkez bölgenizi meşgul tutun. Dirseğinizi vücudunuza yakın tutarak ve kürek kemiklerinizi birbirine sıkıştırarak kettlebell''i göğsünüze doğru yukarı çekin. Tepe noktasında bir süre duraklayın, ardından kettlebell''i yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından taraf değiştirin ve diğer kolla tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Tira de la pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos. Haz una pausa breve en lo alto, luego baja lentamente la pesa rusa de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado y repite con el otro brazo.","ru":"Встаньте, ноги на ширине плеч, держите гирю в одной руке хватом сверху. Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой и напряженный корпус. Подтяните гирю к груди, держа локоть близко к телу и сжимая лопатки вместе. Задержитесь на мгновение в верхней точке, затем медленно опустите гирю обратно в исходное положение. Повторите желаемое количество повторений, затем поменяйте сторону и повторите с другой рукой.","zh":"双脚分开与肩同宽站立，一只手握住壶铃，正手握住。 稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心肌群参与。 将壶铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。 在顶部暂停片刻，然后慢慢将壶铃放回起始位置。 重复所需的重复次数，然后换边并用另一只手臂重复。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े रहें, एक हाथ में केटलबेल को ओवरहैंड पकड़ के साथ पकड़ें। अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें। केटलबेल को अपनी छाती की ओर ऊपर खींचें, अपनी कोहनी को अपने शरीर के करीब रखें और अपने कंधे के ब्लेड को एक साथ निचोड़ें। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे केटलबेल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें और दूसरे हाथ से दोहराएं।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w jednej dłoni nachwytem. Ugnij lekko kolana i wykonaj skłon w biodrach, utrzymując proste plecy i napięte mięśnie brzucha. Podciągnij kettlebell w stronę klatki piersiowej, trzymając łokieć blisko ciała i ściskając łopatki. Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść kettlebell do pozycji wyjściowej. Powtórz zgodnie z zaplanowaną liczbą powtórzeń, a następnie zmień stronę i powtórz drugą ręką.","ko":"다리를 어깨 너비로 벌리고 한 손으로 오버핸드 그립으로 케틀벨을 잡습니다. 무릎을 살짝 구부리고 허리에서 구부리면서 등을 곧게 펴고 코어에 힘을 줍니다. 팔꿈치를 몸에 붙인 상태로 케틀벨을 가슴 쪽으로 당기면서 어깨 날개뼈를 모아줍니다. 최고점에서 잠깐 멈춘 후 케틀벨을 천천히 처음 위치로 낮춥니다. 원하는 반복 횟수를 완료한 후 반대쪽 팔로 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell d''une main en prise pronation. Fléchis légèrement les genoux et bascule vers l''avant au niveau des hanches en gardant le dos droit et ta sangle abdominale gainée. Tire le kettlebell vers le haut en direction de ta poitrine en gardant ton coude près de ton corps et en contractant tes omoplates l''une vers l''autre. Marque une pause en haut, puis abaisse lentement le kettlebell pour revenir à la position de départ. Répète le nombre de répétitions souhaité, puis change de côté et recommence avec l''autre bras."}'::jsonb, 'images/0541-g9AsZ8P.jpg', 'videos/0541-g9AsZ8P.gif', '© Gym visual — https://gymvisual.com/'),
(542, 'kettlebell one arm snatch', 'shoulders', 'strength', 'shoulders', 'kettlebell', 'trapezius', 'delts', '["trapezius","forearms","core"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in one hand between your legs. Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground. Explosively extend your hips and knees, using the momentum to swing the kettlebell up towards your shoulder. As the kettlebell reaches shoulder height, rotate your hand and punch it straight up overhead, fully extending your arm. Lower the kettlebell back down between your legs and repeat for the desired number of repetitions.","it":"Stai con i piedi alla larghezza delle spalle, tenendo un kettlebell in una mano tra le gambe. Piega leggermente le ginocchia e fai perno sui fianchi, abbassando il kettlebell verso terra. Estendi in modo esplosivo i fianchi e le ginocchia, sfruttando lo slancio per far oscillare il kettlebell verso la spalla. Quando il kettlebell raggiunge l''altezza delle spalle, ruota la mano e colpiscilo verso l''alto, estendendo completamente il braccio. Abbassa nuovamente il kettlebell tra le gambe e ripeti per il numero di ripetizioni desiderato.","tr":"Ayaklarınızı omuz genişliğinde açın ve bir elinizde kettlebell''i bacaklarınızın arasında tutun. Dizlerinizi hafifçe bükün ve kalçalardan destek alarak kettlebell''i yere doğru indirin. Kettlebell''i omzunuza doğru sallamak için momentumu kullanarak kalçalarınızı ve dizlerinizi patlayıcı bir şekilde uzatın. Kettlebell omuz hizasına ulaştığında elinizi çevirin ve kolunuzu tamamen uzatarak başınızın üzerine doğru yumruklayın. Kettlebell''i bacaklarınızın arasına indirin ve istediğiniz sayıda tekrar yapın.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano entre las piernas. Flexiona ligeramente las rodillas e inclínate desde las caderas, bajando la pesa rusa hacia el suelo. Extiende explosivamente las caderas y las rodillas, usando el impulso para hacer que la pesa rusa suba hacia el hombro. Cuando la pesa rusa llegue a la altura del hombro, rota la mano y lánzala recta hacia arriba por encima de la cabeza, extendiendo el brazo por completo. Baja la pesa rusa de vuelta entre las piernas y repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, держа гирю в одной руке между ног. Слегка согните колени и наклонитесь в бедрах, опуская гирю к земле. Резко выпрямите бедра и колени, используя инерцию, чтобы подвести гирю к плечу. Когда гиря достигнет уровня плеч, поверните руку и ударьте ее прямо над головой, полностью выпрямляя руку. Опустите гирю обратно между ног и повторите желаемое количество повторений.","zh":"双脚分开与肩同宽站立，一只手将壶铃放在两腿之间。 稍微弯曲膝盖并铰接臀部，将壶铃降低到地面。 爆发性地伸展你的臀部和膝盖，利用动量将壶铃向上摆动到你的肩膀上。 当壶铃到达肩膀高度时，旋转你的手并将其直接击打到头顶，完全伸展你的手臂。 将壶铃放回到双腿之间，然后重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, अपने पैरों के बीच एक हाथ में केटलबेल पकड़ लें। अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर टिकाएं, केटलबेल को ज़मीन की ओर नीचे करें। केटलबेल को अपने कंधे की ओर ऊपर घुमाने के लिए गति का उपयोग करते हुए, अपने कूल्हों और घुटनों को तेजी से फैलाएं। जैसे ही केटलबेल कंधे की ऊंचाई तक पहुंचती है, अपने हाथ को घुमाएं और अपनी बांह को पूरी तरह फैलाते हुए इसे सीधे ऊपर की ओर मुक्का मारें। केटलबेल को वापस अपने पैरों के बीच नीचे लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w jednej dłoni między nogami. Ugnij lekko kolana i wykonaj skłon w biodrach, opuszczając kettlebell w kierunku podłogi. Eksplozywnie wyprostuj biodra i kolana, wykorzystując pęd, aby wywindować kettlebell w stronę barku. Gdy kettlebell osiągnie wysokość barku, obróć dłoń i wypchnij ją prosto w górę nad głowę, w pełni prostując ramię. Opuść kettlebell z powrotem między nogi i powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"다리를 어깨 너비로 벌리고 한 손으로 양다리 사이에 케틀벨을 잡습니다. 무릎을 살짝 구부리고 허리에서 구부리면서 케틀벨을 땅 쪽으로 낮춥니다. 엉덩이와 무릎을 폭발적으로 펼치면서 모멘텀을 사용하여 케틀벨을 어깨 쪽으로 흔듭니다. 케틀벨이 어깨 높이에 도달하면 손을 회전하고 팔을 펴서 머리 위로 밀어냅니다. 케틀벨을 양다리 사이로 다시 낮춘 후 원하는 반복 횟수까지 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell d''une main entre tes jambes. Fléchis légèrement les genoux et bascule au niveau des hanches en abaissant la kettlebell vers le sol. Étends de manière explosive tes hanches et tes genoux, en utilisant l''élan pour balancer la kettlebell vers ton épaule. Lorsque le kettlebell atteint la hauteur des épaules, fais pivoter ta main et propulse-le bien droit au-dessus de la tête en étendant complètement ton bras. Abaisse le kettlebell entre tes jambes et répète pour le nombre de répétitions souhaité."}'::jsonb, 'images/0542-aXcUyKb.jpg', 'videos/0542-aXcUyKb.gif', '© Gym visual — https://gymvisual.com/'),
(543, 'kettlebell pirate supper legs', 'shoulders', 'strength', 'shoulders', 'kettlebell', 'triceps', 'delts', '["triceps","forearms"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in one hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Raise the kettlebell up to shoulder height, keeping your elbow close to your body. Extend your arm fully overhead, straightening your elbow. Lower the kettlebell back down to shoulder height, then return to the starting position. Repeat for the desired number of repetitions, then switch sides.","it":"Stai con i piedi alla larghezza delle spalle, tenendo un kettlebell in una mano. Piega leggermente le ginocchia e fai perno in avanti sui fianchi, mantenendo la schiena dritta. Sollevare il kettlebell all''altezza delle spalle, mantenendo il gomito vicino al corpo. Estendi il braccio completamente sopra la testa, raddrizzando il gomito. Abbassare nuovamente il kettlebell all''altezza delle spalle, quindi tornare alla posizione di partenza. Ripeti per il numero di ripetizioni desiderato, quindi cambia lato.","tr":"Bir elinizde kettlebell tutarak ayaklarınızı omuz genişliğinde açın. Dizlerinizi hafifçe bükün ve sırtınızı düz tutarak kalçalarınızdan öne doğru eğilin. Dirseğinizi vücudunuza yakın tutarak kettlebell''i omuz yüksekliğine kadar kaldırın. Dirseğinizi düzleştirerek kolunuzu tamamen yukarı doğru uzatın. Kettlebell''i omuz yüksekliğine kadar indirin ve ardından başlangıç ​​pozisyonuna dönün. İstenilen tekrar sayısı kadar tekrarlayın, ardından taraf değiştirin.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Levanta la pesa rusa hasta la altura del hombro, manteniendo el codo cerca del cuerpo. Extiende el brazo por completo por encima de la cabeza, enderezando el codo. Baja la pesa rusa de vuelta a la altura del hombro, luego vuelve a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.","ru":"Встаньте, ноги на ширине плеч, в одной руке держите гирю. Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой. Поднимите гирю до уровня плеч, держа локоть близко к телу. Вытяните руку полностью над головой, выпрямляя локоть. Опустите гирю обратно на высоту плеч, затем вернитесь в исходное положение. Повторите желаемое количество повторений, затем поменяйте сторону.","zh":"双脚分开与肩同宽站立，一只手握住壶铃。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将壶铃举至肩膀高度，保持肘部靠近身体。 将手臂完全伸过头顶，伸直肘部。 将壶铃降低至肩膀高度，然后返回起始位置。 重复所需的重复次数，然后换边。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और एक हाथ में केटलबेल पकड़ लें। अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें। अपनी कोहनी को अपने शरीर के करीब रखते हुए केटलबेल को कंधे की ऊंचाई तक उठाएं। अपनी कोहनी को सीधा करते हुए अपने हाथ को पूरी तरह ऊपर की ओर फैलाएँ। केटलबेल को वापस कंधे की ऊँचाई तक नीचे लाएँ, फिर प्रारंभिक स्थिति में लौट आएँ। दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w jednej dłoni. Ugnij lekko kolana i wykonaj skłon w biodrach, utrzymując proste plecy. Unieś kettlebell na wysokość barku, trzymając łokieć blisko ciała. Wyprostuj ramię całkowicie nad głową, prostując łokieć. Opuść kettlebell z powrotem na wysokość barku, a następnie wróć do pozycji wyjściowej. Powtórz zgodnie z zaplanowaną liczbą powtórzeń, a następnie zmień stronę.","ko":"다리를 어깨 너비로 벌리고 한 손으로 케틀벨을 잡습니다. 무릎을 살짝 구부리고 허리에서 구부리면서 등을 곧게 펴줍니다. 팔꿈치를 몸에 붙인 상태로 케틀벨을 어깨 높이까지 들어올립니다. 팔꿈치를 펴면서 팔을 완전히 머리 위로 펼칩니다. 케틀벨을 어깨 높이로 다시 낮춘 후 처음 위치로 돌아옵니다. 원하는 반복 횟수를 완료한 후 반대쪽을 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell d''une main. Fléchis légèrement les genoux et bascule vers l''avant au niveau des hanches en gardant le dos droit. Lève le kettlebell à hauteur des épaules en gardant ton coude près de ton corps. Étends complètement ton bras au-dessus de la tête, en redressant ton coude. Abaisse le kettlebell à hauteur des épaules, puis reviens à la position de départ. Répète le nombre de répétitions souhaité, puis change de côté."}'::jsonb, 'images/0543-kuXhl0o.jpg', 'videos/0543-kuXhl0o.gif', '© Gym visual — https://gymvisual.com/'),
(544, 'kettlebell pistol squat', 'upper legs', 'strength', 'upper legs', 'kettlebell', 'quadriceps', 'glutes', '["quadriceps","hamstrings","calves"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands. Lift your left foot off the ground and extend it forward, keeping it parallel to the ground. Slowly lower your body down into a squat position, keeping your right foot flat on the ground and your left leg extended. Pause for a moment at the bottom of the squat, then push through your right heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.","it":"Stai con i piedi alla larghezza delle spalle, tenendo un kettlebell davanti al petto con entrambe le mani. Solleva il piede sinistro da terra ed estendilo in avanti, mantenendolo parallelo al suolo. Abbassa lentamente il corpo in posizione tozza, mantenendo il piede destro appoggiato a terra e la gamba sinistra estesa. Fai una pausa per un momento nella parte inferiore dello squat, quindi spingi attraverso il tallone destro per tornare alla posizione di partenza. Ripeti per il numero di ripetizioni desiderato, quindi cambia gamba.","tr":"Ayaklarınızı omuz genişliğinde açın ve kettlebell''i iki elinizle göğsünüzün önünde tutun. Sol ayağınızı yerden kaldırın ve yere paralel tutarak ileri doğru uzatın. Sağ ayağınızı yerde düz bir şekilde ve sol bacağınızı uzatarak vücudunuzu yavaşça çömelme pozisyonuna indirin. Çömelmenin alt noktasında bir an duraklayın, ardından başlangıç ​​pozisyonuna dönmek için sağ topuğunuzu itin. İstenilen tekrar sayısı kadar tekrarlayın, ardından bacakları değiştirin.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos. Levanta el pie izquierdo del suelo y extiéndelo hacia adelante, manteniéndolo paralelo al suelo. Baja lentamente el cuerpo a una posición de sentadilla, manteniendo el pie derecho plano en el suelo y la pierna izquierda extendida. Haz una pausa breve en la parte baja de la sentadilla, luego empuja con el talón derecho para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.","ru":"Встаньте, ноги на ширине плеч, удерживая гирю перед грудью обеими руками. Поднимите левую ногу от земли и вытяните ее вперед, удерживая параллельно земле. Медленно опустите тело в положение приседа, удерживая правую ногу на земле, а левую ногу вытянув. Задержитесь на мгновение в нижней части приседа, затем оттолкнитесь правой пяткой, чтобы вернуться в исходное положение. Повторите необходимое количество повторений, затем поменяйте ногу.","zh":"双脚分开与肩同宽站立，双手握住壶铃放在胸前。 将左脚抬离地面并向前伸展，保持与地面平行。 慢慢地将身体降低到蹲姿，保持右脚平放在地面上，左腿伸展。 在深蹲底部暂停片刻，然后推动右脚跟返回到起始位置。 重复所需的重复次数，然后换腿。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, दोनों हाथों से अपनी छाती के सामने केटलबेल पकड़ें। अपने बाएँ पैर को ज़मीन से उठाएँ और ज़मीन के समानांतर रखते हुए आगे की ओर फैलाएँ। धीरे-धीरे अपने शरीर को स्क्वाट स्थिति में नीचे लाएँ, अपने दाहिने पैर को ज़मीन पर सपाट रखें और अपने बाएँ पैर को फैलाएँ। स्क्वाट के निचले हिस्से में एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी दाहिनी एड़ी से धक्का दें। दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदल लें।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell przed klatką piersiową obiema dłońmi. Unieś lewą stopę nad podłogę i wyciągnij ją do przodu, utrzymując równolegle do podłoża. Powoli opuść ciało do przysiadu, trzymając prawą stopę płasko na podłodze, a lewą nogę wyprostowaną. Zatrzymaj się na chwilę na dole przysiadu, a następnie odepchnij się przez prawą piętę, wracając do pozycji wyjściowej. Powtórz zgodnie z zaplanowaną liczbą powtórzeń, a następnie zmień nogę.","ko":"다리를 어깨 너비로 벌리고 양손으로 가슴 앞에 케틀벨을 잡습니다. 왼발을 땅에서 들어 앞으로 펼쳐 바닥과 평행하게 유지합니다. 오른발은 땅에 붙인 상태로 유지하면서 몸을 천천히 스쿼트 자세로 내려갑니다. 왼다리는 펼친 상태를 유지합니다. 스쿼트의 바닥에서 잠깐 멈춘 후 오른발 뒤꿈치로 밀어 처음 위치로 돌아옵니다. 원하는 반복 횟수를 완료한 후 반대쪽 다리로 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell devant ta poitrine à deux mains. Décolle ton pied gauche du sol et étends-le vers l''avant, en le gardant parallèle au sol. Abaisse lentement ton corps en position accroupie, en gardant ton pied droit à plat sur le sol et ta jambe gauche tendue. Marque une pause en bas du squat, puis pousse sur ton talon droit pour revenir à la position de départ. Répète le nombre de répétitions souhaité, puis change de jambe."}'::jsonb, 'images/0544-5bpPTHv.jpg', 'videos/0544-5bpPTHv.gif', '© Gym visual — https://gymvisual.com/'),
(545, 'kettlebell plyo push-up', 'chest', 'strength', 'chest', 'kettlebell', 'triceps', 'pectorals', '["triceps","shoulders","core"]'::jsonb, '{"en":"Start in a high plank position with your hands on the kettlebells, shoulder-width apart. Lower your chest towards the ground, keeping your elbows close to your body. Push through your hands explosively, lifting your hands off the kettlebells and extending your arms fully. Land softly back on the kettlebells and immediately lower your chest back down for the next repetition. Repeat for the desired number of repetitions.","it":"Inizia in una posizione di plancia alta con le mani sui kettlebell, alla larghezza delle spalle. Abbassa il petto verso terra, mantenendo i gomiti vicini al corpo. Spingi le mani in modo esplosivo, sollevando le mani dai kettlebell ed estendendo completamente le braccia. Atterra dolcemente sui kettlebell e abbassa immediatamente il petto per la ripetizione successiva. Ripetere per il numero di ripetizioni desiderato.","tr":"Elleriniz kettlebell''lerin üzerinde, omuz genişliğinde açık olacak şekilde yüksek bir plank pozisyonuyla başlayın. Dirseklerinizi vücudunuza yakın tutarak göğsünüzü yere doğru indirin. Ellerinizi patlayıcı bir şekilde itin, ellerinizi kettlebell''lerden kaldırın ve kollarınızı tamamen uzatın. Kettlebell''lerin üzerine yavaşça inin ve bir sonraki tekrar için hemen göğsünüzü aşağıya doğru indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Comienza en una posición de plancha alta con las manos sobre las pesas rusas, separadas a la altura de los hombros. Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo. Empuja con las manos de forma explosiva, levantándolas de las pesas rusas y extendiendo los brazos por completo. Aterriza suavemente sobre las pesas rusas y baja el pecho de inmediato para la siguiente repetición. Repite el número de repeticiones deseado.","ru":"Начните с позиции высокой планки, положив руки на гири на ширине плеч. Опустите грудь к земле, держа локти близко к телу. Резко оттолкнитесь руками, отрывая руки от гири и полностью выпрямляя руки. Мягко приземлитесь на гири и сразу же опустите грудь вниз для следующего повторения. Повторите необходимое количество повторений.","zh":"从高平板支撑位置开始，双手放在壶铃上，距离与肩同宽。 将胸部压向地面，保持肘部靠近身体。 爆发性地推动你的手，将你的手从壶铃上抬起并完全伸展你的手臂。 轻轻地回到壶铃上，并立即降低胸部以进行下一次重复。 重复所需的重复次数。","hi":"अपने हाथों को केटलबेल्स पर कंधे की चौड़ाई की दूरी पर रखते हुए ऊंची तख़्त स्थिति में शुरुआत करें। अपनी कोहनियों को अपने शरीर के पास रखते हुए, अपनी छाती को ज़मीन की ओर झुकाएँ। अपने हाथों को विस्फोटक तरीके से दबाएं, अपने हाथों को केटलबेल से उठाएं और अपनी बाहों को पूरी तरह फैलाएं। धीरे से केटलबेल्स पर वापस आएँ और अगली पुनरावृत्ति के लिए तुरंत अपनी छाती को वापस नीचे कर लें। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Zacznij w wysokiej podporze przodem, dłonie oparte na kettlebellach, rozstawione na szerokość barków. Opuść klatkę piersiową w stronę podłogi, trzymając łokcie blisko ciała. Wypchnij się dłońmi eksplozywnie, unosząc dłonie znad kettlebelli i w pełni prostując ramiona. Wyląduj miękko z powrotem na kettlebellach i od razu opuść klatkę piersiową, rozpoczynając kolejne powtórzenie. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"양손을 케틀벨 위에 어깨너비로 벌려 높은 플랭크 자세로 시작합니다. 팔꿈치를 몸 가까이 유지하면서 가슴을 땅 쪽으로 내립니다. 손으로 폭발적으로 밀어 케틀벨에서 손을 떼고 팔을 완전히 펼칩니다. 케틀벨에 부드럽게 착지한 후 다음 반복을 위해 즉시 가슴을 다시 내립니다. 원하는 횟수만큼 반복합니다.","fr":"Commence en position de planche haute, les mains sur les kettlebells, écartées à la largeur des épaules. Abaisse ta poitrine vers le sol, en gardant les coudes près de ton corps. Pousse à travers tes mains de manière explosive en soulevant tes mains des kettlebells et en tendant complètement tes bras. Atterris en douceur sur les kettlebells et rabaisse immédiatement ta poitrine pour la répétition suivante. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0545-ktf3nvW.jpg', 'videos/0545-ktf3nvW.gif', '© Gym visual — https://gymvisual.com/'),
(546, 'kettlebell seated press', 'shoulders', 'strength', 'shoulders', 'kettlebell', 'triceps', 'delts', '["triceps","core"]'::jsonb, '{"en":"Sit on a bench with your back straight and feet flat on the ground. Hold a kettlebell in each hand at shoulder height, palms facing forward. Press the kettlebells overhead, fully extending your arms. Lower the kettlebells back to shoulder height. Repeat for the desired number of repetitions.","it":"Siediti su una panca con la schiena dritta e i piedi appoggiati a terra. Tieni un kettlebell in ciascuna mano all''altezza delle spalle, con i palmi rivolti in avanti. Premi i kettlebell sopra la testa, estendendo completamente le braccia. Abbassare i kettlebell all''altezza delle spalle. Ripetere per il numero di ripetizioni desiderato.","tr":"Sırtınız dik ve ayaklarınız yere düz basacak şekilde bir bankta oturun. Her iki elinizde de omuz hizasında, avuç içleriniz öne bakacak şekilde bir kettlebell tutun. Kollarınızı tamamen uzatarak kettlebell''leri başınızın üzerine bastırın. Kettlebell''leri omuz yüksekliğine kadar indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una pesa rusa en cada mano a la altura del hombro, con las palmas hacia adelante. Presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo. Baja las pesas rusas de vuelta a la altura del hombro. Repite el número de repeticiones deseado.","ru":"Сядьте на скамью, выпрямив спину и поставив ноги на землю. Держите гирю в каждой руке на уровне плеч, ладонями вперед. Жмите гири над головой, полностью выпрямляя руки. Опустите гири обратно на высоту плеч. Повторите необходимое количество повторений.","zh":"坐在长凳上，背部挺直，双脚平放在地上。 每只手握住一个壶铃，与肩同高，手掌朝前。 将壶铃压过头顶，充分伸展手臂。 将壶铃降低至肩膀高度。 重复所需的重复次数。","hi":"अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें। प्रत्येक हाथ में कंधे की ऊंचाई पर केटलबेल पकड़ें, हथेलियाँ आगे की ओर हों। अपनी बाहों को पूरी तरह फैलाते हुए केटलबेल्स को ऊपर की ओर दबाएं। केटलबेल्स को वापस कंधे की ऊँचाई तक नीचे लाएँ। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Usiądź na ławce z prostymi plecami i stopami płasko opartymi o podłogę. Trzymaj kettlebell w każdej dłoni na wysokości barków, dłonie skierowane do przodu. Wypchnij kettlebelle nad głowę, w pełni prostując ramiona. Opuść kettlebelle z powrotem na wysokość barków. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"벤치에 앉아 등은 곧게 펴고 발은 땅에 닿은 상태에서 시작합니다. 각 손에 케틀벨을 어깨 높이에서 잡고 손은 앞을 향합니다. 케틀벨을 머리 위로 눌러 팔을 완전히 펼칩니다. 케틀벨을 어깨 높이로 다시 내립니다. 원하는 횟수만큼 반복합니다.","fr":"Assieds-toi sur un banc, le dos droit et les pieds à plat sur le sol. Tiens un kettlebell dans chaque main à hauteur des épaules, les paumes tournées vers l''avant. Développe les kettlebells au-dessus de ta tête, en tendant complètement tes bras. Abaisse les kettlebells à hauteur des épaules. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0546-BkxB8LW.jpg', 'videos/0546-BkxB8LW.gif', '© Gym visual — https://gymvisual.com/'),
(1438, 'kettlebell seated two arm military press', 'shoulders', 'strength', 'shoulders', 'kettlebell', 'triceps', 'delts', '["triceps","upper back"]'::jsonb, '{"en":"Sit on a bench with your back straight and feet flat on the ground. Hold a kettlebell in each hand at shoulder level with your palms facing forward. Press the kettlebells overhead by extending your arms fully. Pause for a moment at the top, then slowly lower the kettlebells back to shoulder level. Repeat for the desired number of repetitions.","it":"Siediti su una panca con la schiena dritta e i piedi appoggiati a terra. Tieni un kettlebell in ciascuna mano all''altezza delle spalle con i palmi rivolti in avanti. Premi i kettlebell sopra la testa estendendo completamente le braccia. Fermati per un momento in alto, quindi abbassa lentamente i kettlebell all''altezza delle spalle. Ripetere per il numero di ripetizioni desiderato.","tr":"Sırtınız dik ve ayaklarınız yere düz basacak şekilde bir bankta oturun. Avuç içleriniz öne bakacak şekilde her iki elinizde omuz hizasında bir kettlebell tutun. Kollarınızı tamamen uzatarak kettlebell''leri başınızın üzerine doğru bastırın. Üstte bir an duraklayın, ardından kettlebell''leri yavaşça omuz hizasına indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una pesa rusa en cada mano a la altura del hombro con las palmas hacia adelante. Presiona las pesas rusas por encima de la cabeza extendiendo los brazos por completo. Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la altura del hombro. Repite el número de repeticiones deseado.","ru":"Сядьте на скамью, выпрямив спину и поставив ноги на землю. Держите гирю в каждой руке на уровне плеч ладонями вперед. Выжмите гири над головой, полностью выпрямив руки. Задержитесь на мгновение в верхней точке, затем медленно опустите гири обратно на уровень плеч. Повторите необходимое количество повторений.","zh":"坐在长凳上，背部挺直，双脚平放在地上。 每只手握住一个壶铃，与肩同高，手掌朝前。 完全伸展双臂，将壶铃压过头顶。 在顶部暂停片刻，然后慢慢将壶铃放回肩部水平。 重复所需的重复次数。","hi":"अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें। अपनी हथेलियों को आगे की ओर रखते हुए प्रत्येक हाथ में कंधे के स्तर पर केटलबेल पकड़ें। अपनी भुजाओं को पूरा फैलाकर केटलबेल्स को ऊपर की ओर दबाएँ। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे केटलबेल्स को वापस कंधे के स्तर तक नीचे लाएँ। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Usiądź na ławce z prostymi plecami i stopami płasko opartymi o podłogę. Trzymaj kettlebell w każdej dłoni na wysokości barków, dłonie skierowane do przodu. Wypchnij kettlebelle nad głowę, w pełni prostując ramiona. Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść kettlebelle na wysokość barków. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"벤치에 앉아 등은 곧게 펴고 발은 땅에 닿은 상태에서 시작합니다. 각 손에 케틀벨을 어깨 높이에서 잡고 손은 앞을 향합니다. 케틀벨을 머리 위로 눌러 팔을 완전히 펼칩니다. 맨 위에서 잠깐 멈춘 후 케틀벨을 천천히 어깨 높이로 내립니다. 원하는 횟수만큼 반복합니다.","fr":"Assieds-toi sur un banc, le dos droit et les pieds à plat sur le sol. Tiens un kettlebell dans chaque main à hauteur d''épaule, les paumes tournées vers l''avant. Développe les kettlebells au-dessus de ta tête en tendant complètement tes bras. Marque une pause en haut, puis abaisse lentement les kettlebells à hauteur des épaules. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/1438-ZEkjZDi.jpg', 'videos/1438-ZEkjZDi.gif', '© Gym visual — https://gymvisual.com/'),
(547, 'kettlebell seesaw press', 'shoulders', 'strength', 'shoulders', 'kettlebell', 'triceps', 'delts', '["triceps","core"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height. Press one kettlebell overhead while keeping the other kettlebell at shoulder height. Lower the pressed kettlebell back to shoulder height while simultaneously pressing the other kettlebell overhead. Continue alternating the pressing motion, creating a seesaw-like movement. Repeat for the desired number of repetitions.","it":"Stare con i piedi alla larghezza delle spalle, tenendo un kettlebell in ciascuna mano all''altezza delle spalle. Premi un kettlebell sopra la testa mantenendo l''altro kettlebell all''altezza delle spalle. Abbassare il kettlebell premuto all''altezza delle spalle mentre si preme contemporaneamente l''altro kettlebell sopra la testa. Continua alternando il movimento di pressione, creando un movimento ad altalena. Ripetere per il numero di ripetizioni desiderato.","tr":"Ayaklarınızı omuz genişliğinde açın ve her iki elinizde de omuz hizasında birer kettlebell tutun. Diğer kettlebell''i omuz yüksekliğinde tutarken bir kettlebell''i başınızın üstüne bastırın. Preslenmiş kettlebell''i tekrar omuz yüksekliğine indirin ve aynı anda diğer kettlebell''i başınızın üzerine bastırın. Tahterevalli benzeri bir hareket yaratarak basma hareketini değiştirmeye devam edin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros. Presiona una pesa rusa por encima de la cabeza mientras mantienes la otra pesa rusa a la altura del hombro. Baja la pesa rusa presionada de vuelta a la altura del hombro mientras presionas simultáneamente la otra pesa rusa por encima de la cabeza. Continúa alternando el movimiento de presión, creando un movimiento similar a un balancín. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, держа в каждой руке по гире на уровне плеч. Выжмите одну гирю над головой, удерживая другую гирю на уровне плеч. Опустите отжатую гирю обратно на высоту плеч, одновременно выжимая другую гирю над головой. Продолжайте чередовать нажимающие движения, создавая движение, напоминающее качели. Повторите необходимое количество повторений.","zh":"双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高。 将一个壶铃压过头顶，同时将另一个壶铃保持在肩膀高度。 将按下的壶铃降低至肩膀高度，同时将另一个壶铃压过头顶。 继续交替按压动作，形成跷跷板状的运动。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में कंधे की ऊंचाई पर केटलबेल पकड़ें। एक केटलबेल को ऊपर की ओर दबाएं जबकि दूसरे केटलबेल को कंधे की ऊंचाई पर रखें। दबाए गए केटलबेल को वापस कंधे की ऊंचाई तक कम करें, साथ ही दूसरे केटलबेल को ऊपर की ओर दबाएं। झूले जैसी गति बनाते हुए, दबाने की गति को बारी-बारी से जारी रखें। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w każdej dłoni na wysokości barków. Wypchnij jeden kettlebell nad głowę, utrzymując drugi na wysokości barku. Opuść wypchnięty kettlebell z powrotem na wysokość barku, jednocześnie wypychając drugi kettlebell nad głowę. Kontynuuj naprzemienne wypychanie, tworząc ruch podobny do bujania na wadze. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"발을 어깨너비로 벌리고 선 자세에서 각 손에 케틀벨을 어깨 높이에서 잡습니다. 한쪽 케틀벨을 머리 위로 누르면서 다른 쪽 케틀벨은 어깨 높이에 유지합니다. 누른 케틀벨을 어깨 높이로 내리면서 동시에 다른 쪽 케틀벨을 머리 위로 누릅니다. 시소우 같은 움직임을 만들면서 교대로 누르는 동작을 계속합니다. 원하는 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell dans chaque main à hauteur d''épaule. Développe un kettlebell au-dessus de ta tête tout en gardant l''autre kettlebell à hauteur des épaules. Abaisse le kettlebell pressé à hauteur des épaules tout en pressant simultanément l''autre kettlebell au-dessus de la tête. Continue à alterner le mouvement de poussée en créant un mouvement de bascule. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0547-UDm6cGl.jpg', 'videos/0547-UDm6cGl.gif', '© Gym visual — https://gymvisual.com/'),
(548, 'kettlebell sumo high pull', 'back', 'strength', 'back', 'kettlebell', 'shoulders', 'traps', '["shoulders","glutes","hamstrings"]'::jsonb, '{"en":"Stand with your feet wider than shoulder-width apart, toes pointing outwards. Hold a kettlebell with both hands in front of your body, arms extended downwards. Bend your knees and lower your hips into a squat position, keeping your back straight. Drive through your heels and explosively extend your hips and knees, pulling the kettlebell up towards your chin. As you pull the kettlebell up, keep your elbows high and wide, and squeeze your shoulder blades together. Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions.","it":"Stare con i piedi più larghi della larghezza delle spalle, con le dita rivolte verso l''esterno. Tieni un kettlebell con entrambe le mani davanti al corpo, le braccia tese verso il basso. Piega le ginocchia e abbassa i fianchi in una posizione tozza, mantenendo la schiena dritta. Guida attraverso i talloni ed estendi in modo esplosivo i fianchi e le ginocchia, tirando il kettlebell verso il mento. Mentre sollevi il kettlebell, tieni i gomiti alti e larghi e stringi insieme le scapole. Abbassare nuovamente il kettlebell nella posizione iniziale e ripetere per il numero di ripetizioni desiderato.","tr":"Ayaklarınız omuz genişliğinden daha geniş, ayak parmaklarınız dışarı bakacak şekilde ayakta durun. Kettlebell''i iki elinizle vücudunuzun önünde tutun, kollarınız aşağı doğru uzatılmış olsun. Dizlerinizi bükün ve kalçalarınızı çömelme pozisyonuna indirin, sırtınızı düz tutun. Topuklarınızın üzerinden geçin ve kettlebell''i çenenize doğru çekerek kalçalarınızı ve dizlerinizi patlayıcı bir şekilde uzatın. Kettlebell''i yukarı çekerken dirseklerinizi yüksek ve geniş tutun ve kürek kemiklerinizi birbirine doğru sıkın. Kettlebell''i başlangıç ​​pozisyonuna indirin ve istenilen sayıda tekrar yapın.","es":"Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera. Sujeta una pesa rusa con ambas manos frente al cuerpo, con los brazos extendidos hacia abajo. Flexiona las rodillas y baja las caderas hasta una posición de sentadilla, manteniendo la espalda recta. Empuja con los talones y extiende explosivamente las caderas y las rodillas, tirando de la pesa rusa hacia la barbilla. Mientras tiras de la pesa rusa hacia arriba, mantén los codos altos y abiertos, y junta los omóplatos. Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado.","ru":"Встаньте, расставив ноги шире плеч, носки наружу. Держите гирю обеими руками перед телом, руки вытянуты вниз. Согните ноги в коленях и опустите бедра в положение приседа, сохраняя спину прямой. Проведите пятками и резко выпрямите бедра и колени, подтягивая гирю к подбородку. Подтягивая гирю вверх, держите локти высоко и широко, а лопатки сведите вместе. Опустите гирю обратно в исходное положение и повторите желаемое количество повторений.","zh":"站立，双脚分开比肩宽，脚趾朝外。 双手握住壶铃放在身体前方，手臂向下伸展。 弯曲膝盖，降低臀部至下蹲位置，保持背部挺直。 脚后跟发力，爆发性伸展臀部和膝盖，将壶铃拉向下巴。 当你向上拉壶铃时，保持肘部高且宽，并将肩胛骨挤压在一起。 将壶铃放回起始位置，然后重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई से अधिक चौड़ा करके खड़े रहें, पैर की उंगलियां बाहर की ओर हों। अपने शरीर के सामने दोनों हाथों से केटलबेल को पकड़ें, बाहें नीचे की ओर फैली हुई हों। अपने घुटनों को मोड़ें और अपनी पीठ को सीधा रखते हुए अपने कूल्हों को स्क्वाट स्थिति में लाएँ। अपनी एड़ी के माध्यम से ड्राइव करें और अपने कूल्हों और घुटनों को विस्फोटक रूप से फैलाएं, केटलबेल को अपनी ठोड़ी की ओर खींचें। जैसे ही आप केटलबेल को ऊपर खींचते हैं, अपनी कोहनियों को ऊंचा और चौड़ा रखें, और अपने कंधे के ब्लेड को एक साथ दबाएं। केटलबेल को वापस प्रारंभिक स्थिति में लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।","pl":"Stań ze stopami rozstawionymi szerzej niż barki, palce stóp skierowane na zewnątrz. Trzymaj kettlebell obiema dłońmi przed ciałem, ramiona wyprostowane w dół. Ugnij kolana i opuść biodra do przysiadu, utrzymując proste plecy. Odepchnij się przez pięty i eksplozywnie wyprostuj biodra i kolana, podciągając kettlebell w stronę brody. Podciągając kettlebell w górę, trzymaj łokcie wysoko i szeroko oraz ściskaj łopatki. Opuść kettlebell z powrotem do pozycji wyjściowej i powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"발을 어깨너비보다 넓게 벌리고 발가락은 바깥쪽을 향하게 선 자세에서 시작합니다. 양손으로 케틀벨을 몸 앞에서 잡고 팔을 아래로 펼칩니다. 무릎을 구부리고 엉덩이를 낮춰 스쿼트 자세를 하면서 등은 곧게 유지합니다. 발뒤꿈치로 밀어 폭발적으로 엉덩이와 무릎을 펴면서 케틀벨을 턱 쪽으로 잡아당깁니다. 케틀벨을 잡아당길 때 팔꿈치는 높고 넓게 유지하고 어깨 날개뼈를 함께 조입니다. 케틀벨을 시작 위치로 내린 후 원하는 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds plus écartés que la largeur des épaules, les orteils tournés vers l''extérieur. Tiens un kettlebell des deux mains devant ton corps, les bras étendus vers le bas. Fléchis les genoux et abaisse tes hanches en position accroupie en gardant le dos droit. Pousse sur tes talons et étends explosivement tes hanches et tes genoux, en tirant le kettlebell vers ton menton. En tirant le kettlebell vers le haut, garde tes coudes hauts et écartés et contracte tes omoplates l''une vers l''autre. Abaisse le kettlebell jusqu''à la position de départ et répète pour le nombre de répétitions souhaité."}'::jsonb, 'images/0548-8ARQ9Hw.jpg', 'videos/0548-8ARQ9Hw.gif', '© Gym visual — https://gymvisual.com/'),
(549, 'kettlebell swing', 'upper legs', 'strength', 'upper legs', 'kettlebell', 'hamstrings', 'glutes', '["hamstrings","core"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, toes pointed slightly outward. Hold the kettlebell with both hands in front of your body, arms extended. Bend your knees slightly and hinge at the hips, pushing your butt back. Swing the kettlebell back between your legs, keeping your arms straight and maintaining a flat back. Drive your hips forward and swing the kettlebell up to shoulder height, using the momentum generated by your hips. Allow the kettlebell to swing back down between your legs and repeat the movement for the desired number of repetitions.","it":"Stare con i piedi alla larghezza delle spalle, le dita dei piedi leggermente rivolte verso l''esterno. Tieni il kettlebell con entrambe le mani davanti al corpo, con le braccia tese. Piega leggermente le ginocchia e fai perno sui fianchi, spingendo indietro i glutei. Fai oscillare il kettlebell tra le gambe, mantenendo le braccia dritte e la schiena piatta. Porta i fianchi in avanti e fai oscillare il kettlebell all''altezza delle spalle, sfruttando lo slancio generato dai fianchi. Lascia che il kettlebell oscilli indietro tra le gambe e ripeti il ​​movimento per il numero desiderato di ripetizioni.","tr":"Ayaklarınız omuz genişliğinde açık, ayak parmaklarınız hafifçe dışarı dönük olacak şekilde ayakta durun. Kettlebell''i iki elinizle vücudunuzun önünde, kollarınız uzatılmış şekilde tutun. Dizlerinizi hafifçe bükün ve kalçalarınıza yaslanın, kıçınızı geriye doğru itin. Kettlebell''i bacaklarınızın arasında geriye doğru sallayın, kollarınızı düz tutun ve sırtınızı düz tutun. Kalçalarınızı ileri doğru itin ve kalçalarınızın oluşturduğu momentumu kullanarak kettlebell''i omuz yüksekliğine kadar sallayın. Kettlebell''in bacaklarınızın arasından aşağı doğru sallanmasına izin verin ve hareketi istenen sayıda tekrarla tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la pesa rusa con ambas manos frente al cuerpo, con los brazos extendidos. Flexiona ligeramente las rodillas e inclínate desde las caderas, empujando los glúteos hacia atrás. Lleva la pesa rusa hacia atrás entre las piernas, manteniendo los brazos rectos y la espalda plana. Lleva las caderas hacia adelante y haz que la pesa rusa suba hasta la altura del hombro, usando el impulso generado por las caderas. Deja que la pesa rusa se balancee de vuelta hacia abajo entre las piernas y repite el movimiento el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, носки слегка направлены наружу. Держите гирю обеими руками перед телом, руки вытянуты. Слегка согните колени и наклонитесь в бедрах, отводя ягодицы назад. Поверните гирю назад между ног, держа руки прямыми и сохраняя ровную спину. Поднимите бедра вперед и поднимите гирю на высоту плеч, используя инерцию, создаваемую бедрами. Позвольте гире опуститься между ног и повторите движение желаемое количество повторений.","zh":"双脚分开与肩同宽站立，脚趾稍微向外。 双手握住壶铃放在身体前方，双臂伸展。 稍微弯曲膝盖并铰接臀部，将臀部向后推。 将壶铃在两腿之间向后摆动，保持手臂伸直并保持背部平坦。 利用臀部产生的动量，向前推动臀部并将壶铃摆动到肩膀高度。 让壶铃在双腿之间向下摆动，然后重复该动作达到所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर की ओर हों। अपने शरीर के सामने दोनों हाथों से केटलबेल को पकड़ें, बाहें फैली हुई। अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर टिकाएं, अपने बट को पीछे धकेलें। अपनी बाहों को सीधा रखते हुए और अपनी पीठ को सपाट रखते हुए, केटलबेल को अपने पैरों के बीच वापस घुमाएँ। अपने कूल्हों को आगे बढ़ाएं और अपने कूल्हों द्वारा उत्पन्न गति का उपयोग करते हुए केटलबेल को कंधे की ऊंचाई तक घुमाएं। केटलबेल को अपने पैरों के बीच वापस झूलने दें और वांछित संख्या में दोहराव के लिए इस क्रिया को दोहराएं।","pl":"Stań ze stopami rozstawionymi na szerokość barków, palce stóp lekko skierowane na zewnątrz. Trzymaj kettlebell obiema dłońmi przed ciałem, ramiona wyprostowane. Ugnij lekko kolana i wykonaj skłon w biodrach, cofając pośladki. Machnij kettlebellem do tyłu między nogami, utrzymując proste ramiona i płaskie plecy. Wypchnij biodra do przodu i wymachnij kettlebell na wysokość barków, wykorzystując pęd generowany przez biodra. Pozwól, aby kettlebell wrócił między nogi, i powtórz ruch zgodnie z zaplanowaną liczbą powtórzeń.","ko":"발을 어깨너비로 벌리고 발가락은 약간 바깥쪽을 향하게 선 자세에서 시작합니다. 양손으로 케틀벨을 몸 앞에서 잡고 팔을 펼칩니다. 무릎을 약간 구부리고 엉덩이를 뒤로 밀면서 허리에서 구부립니다. 케틀벨을 두 다리 사이로 뒤로 스윙하면서 팔은 곧게 유지하고 등은 평평하게 유지합니다. 엉덩이를 앞으로 밀어 케틀벨을 어깨 높이까지 스윙하면서 엉덩이가 생성한 모멘텀을 사용합니다. 케틀벨을 두 다리 사이로 뒤로 스윙하도록 내린 후 원하는 횟수만큼 동작을 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, les orteils légèrement tournés vers l''extérieur. Tiens le kettlebell des deux mains devant ton corps, les bras étendus. Fléchis légèrement les genoux et bascule au niveau des hanches en poussant tes fesses vers l''arrière. Balance le kettlebell vers l''arrière entre tes jambes, en gardant les bras tendus et le dos plat. Pousse tes hanches vers l''avant et balance le kettlebell jusqu''à hauteur d''épaule, en utilisant l''élan généré par tes hanches. Laisse le kettlebell revenir en balancier entre tes jambes et répète le mouvement pour le nombre de répétitions souhaité."}'::jsonb, 'images/0549-UHJlbu3.jpg', 'videos/0549-UHJlbu3.gif', '© Gym visual — https://gymvisual.com/'),
(550, 'kettlebell thruster', 'shoulders', 'strength', 'shoulders', 'kettlebell', 'quadriceps', 'delts', '["quadriceps","glutes","core"]'::jsonb, '{"en":"Start by standing with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands, palms facing each other. Lower into a squat position by bending your knees and pushing your hips back, keeping your chest up and your back straight. As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the kettlebell overhead. Lock out your arms at the top of the movement, fully extending your elbows. Lower the kettlebell back to the starting position by reversing the movement, bending your elbows and lowering the weight back to your chest. Repeat for the desired number of repetitions.","it":"Inizia stando in piedi con i piedi alla larghezza delle spalle, tenendo un kettlebell davanti al petto con entrambe le mani, i palmi uno di fronte all''altro. Abbassati in una posizione tozza piegando le ginocchia e spingendo indietro i fianchi, mantenendo il petto sollevato e la schiena dritta. Quando raggiungi la fine dello squat, spingi in modo esplosivo i talloni per alzarti in piedi, premendo contemporaneamente il kettlebell sopra la testa. Blocca le braccia nella parte superiore del movimento, estendendo completamente i gomiti. Riporta il kettlebell nella posizione iniziale invertendo il movimento, piegando i gomiti e riportando il peso sul petto. Ripetere per il numero di ripetizioni desiderato.","tr":"Ayaklarınızı omuz genişliğinde açarak, iki elinizle göğsünüzün önünde bir kettlebell tutarak, avuçlarınız birbirine bakacak şekilde ayakta durarak başlayın. Dizlerinizi bükerek ve kalçalarınızı geriye doğru iterek göğsünüzü yukarıda ve sırtınızı düz tutarak çömelme pozisyonuna inin. Squat''ın alt kısmına ulaştığınızda, ayağa kalkmak için topuklarınızın üzerinden patlayıcı bir şekilde ilerleyin ve aynı anda kettlebell''i başınızın üzerine bastırın. Dirseklerinizi tamamen uzatarak hareketin üst noktasında kollarınızı kilitleyin. Hareketi tersine çevirerek, dirseklerinizi bükerek ve ağırlığı tekrar göğsünüze indirerek kettlebell''i başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Comienza de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos, con las palmas una frente a la otra. Baja a una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás, manteniendo el pecho elevado y la espalda recta. Al llegar a la parte baja de la sentadilla, empuja explosivamente con los talones para ponerte de pie, presionando al mismo tiempo la pesa rusa por encima de la cabeza. Bloquea los brazos en la parte alta del movimiento, extendiendo los codos por completo. Baja la pesa rusa de vuelta a la posición inicial invirtiendo el movimiento, flexionando los codos y bajando el peso de vuelta al pecho. Repite el número de repeticiones deseado.","ru":"Начните с того, что встаньте, поставив ноги на ширине плеч, держа гирю перед грудью обеими руками, ладони обращены друг к другу. Опуститесь в присед, согнув колени и отведя бедра назад, сохраняя грудь поднятой, а спину прямой. Достигнув нижней точки приседа, резко поднимите пятки, чтобы встать, одновременно нажимая гирю над головой. Зафиксируйте руки в верхней точке движения, полностью разгибая локти. Опустите гирю обратно в исходное положение, изменив движение, согнув локти и опустив вес обратно на грудь. Повторите необходимое количество повторений.","zh":"首先，双脚分开与肩同宽站立，双手将壶铃放在胸前，手掌相对。 弯曲膝盖并将臀部向后推，保持挺胸、背部挺直，进入蹲姿。 当你到达深蹲底部时，爆发性地通过脚后跟站起来，同时将壶铃压过头顶。 在动作的最高点锁定你的手臂，完全伸展你的肘部。 通过反转动作，弯曲肘部并将重量放回胸部，将壶铃放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े होकर शुरुआत करें, दोनों हाथों से अपनी छाती के सामने केटलबेल पकड़ें, हथेलियाँ एक-दूसरे के सामने हों। अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए, अपनी छाती को ऊपर और अपनी पीठ को सीधा रखते हुए स्क्वाट स्थिति में आ जाएँ। जैसे ही आप स्क्वाट के निचले भाग तक पहुँचते हैं, खड़े होने के लिए अपनी एड़ी के माध्यम से विस्फोटक रूप से ड्राइव करें, साथ ही केटलबेल को ऊपर की ओर दबाएँ। अपनी कोहनियों को पूरी तरह फैलाते हुए, अपनी भुजाओं को गति के शीर्ष पर लॉक कर लें। गति को उलट कर, अपनी कोहनियों को मोड़कर और वजन को वापस अपनी छाती पर लाकर केटलबेल को प्रारंभिक स्थिति में वापस लाएँ। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Zacznij, stojąc ze stopami rozstawionymi na szerokość barków, trzymając kettlebell przed klatką piersiową obiema dłońmi, dłonie skierowane do siebie. Opuść się do przysiadu, uginając kolana i cofając biodra, utrzymując uniesioną klatkę piersiową i proste plecy. Osiągając dół przysiadu, eksplozywnie odepchnij się przez pięty, aby wstać, jednocześnie wypychając kettlebell nad głowę. Zablokuj ramiona na górze ruchu, w pełni prostując łokcie. Opuść kettlebell do pozycji wyjściowej, odwracając ruch, uginając łokcie i sprowadzając ciężar z powrotem do klatki piersiowej. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"발을 어깨너비로 벌리고 선 자세에서 시작하여 양손으로 케틀벨을 가슴 앞에 잡고 손은 서로를 향합니다. 무릎을 구부리고 엉덩이를 뒤로 밀면서 스쿼트 자세로 내려가고 가슴은 올린 상태로 등은 곧게 유지합니다. 스쿼트 맨 아래에 도달했을 때 발뒤꿈치로 폭발적으로 밀어 일어나면서 동시에 케틀벨을 머리 위로 누릅니다. 맨 위에서 팔꿈치를 완전히 펴 잠금 상태를 만듭니다. 팔을 구부리고 무게를 가슴으로 다시 낮추면서 동작을 역으로 하여 시작 위치로 케틀벨을 내립니다. 원하는 횟수만큼 반복합니다.","fr":"Commence debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell devant ta poitrine à deux mains, les paumes tournées l''une vers l''autre. Descends en position de squat en fléchissant tes genoux et en poussant tes hanches vers l''arrière, en gardant ta poitrine relevée et ton dos droit. Une fois au bas du squat, pousse explosivement sur tes talons pour te relever tout en poussant simultanément le kettlebell au-dessus de ta tête. Verrouille tes bras en haut du mouvement, en étendant complètement tes coudes. Abaisse le kettlebell jusqu''à la position de départ en inversant le mouvement, en fléchissant tes coudes et en ramenant le poids à ta poitrine. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0550-yWxMvB5.jpg', 'videos/0550-yWxMvB5.gif', '© Gym visual — https://gymvisual.com/'),
(551, 'kettlebell turkish get up (squat style)', 'upper legs', 'strength', 'upper legs', 'kettlebell', 'quadriceps', 'glutes', '["quadriceps","hamstrings","core"]'::jsonb, '{"en":"Start by lying on your back with your legs extended and the kettlebell held in your right hand, arm fully extended above your shoulder. Bend your right knee and place your right foot flat on the ground, keeping your left leg extended. Pressing through your right foot, lift your hips off the ground, coming into a bridge position. Slide your left leg underneath your body, bending your left knee and placing your left foot flat on the ground. Rotate your torso to the left, bringing your left hand to the ground for support. Pressing through your right foot and left hand, lift your torso off the ground, coming into a kneeling position. From the kneeling position, stand up, keeping the kettlebell extended overhead. Reverse the movement to return to the starting position. Repeat the exercise on the other side, starting with the kettlebell in your left hand.","it":"Inizia sdraiandoti sulla schiena con le gambe distese e il kettlebell tenuto nella mano destra, il braccio completamente esteso sopra la spalla. Piega il ginocchio destro e appoggia il piede destro a terra, mantenendo la gamba sinistra estesa. Premendo con il piede destro, solleva i fianchi da terra, assumendo la posizione del ponte. Fai scivolare la gamba sinistra sotto il corpo, piegando il ginocchio sinistro e appoggiando il piede sinistro a terra. Ruota il busto verso sinistra, portando la mano sinistra a terra per supporto. Premendo il piede destro e la mano sinistra, solleva il busto da terra, mettendoti in ginocchio. Dalla posizione in ginocchio, alzati in piedi, mantenendo il kettlebell esteso sopra la testa. Invertire il movimento per tornare alla posizione di partenza. Ripeti l''esercizio dall''altro lato, iniziando con il kettlebell nella mano sinistra.","tr":"Bacaklarınız uzatılmış ve kettlebell''i sağ elinizde tutarak, kolunuz omzunuzun üzerinde tamamen uzatılmış şekilde sırt üstü yatarak başlayın. Sağ dizinizi bükün ve sol bacağınızı uzatarak sağ ayağınızı yere düz bir şekilde yerleştirin. Sağ ayağınıza basarak kalçalarınızı yerden kaldırın ve köprü pozisyonuna gelin. Sol bacağınızı vücudunuzun altına kaydırın, sol dizinizi bükün ve sol ayağınızı düz bir şekilde yere koyun. Gövdenizi sola döndürün ve sol elinizi destek için yere getirin. Sağ ayağınıza ve sol elinize basarak gövdenizi yerden kaldırın ve diz çökme pozisyonuna gelin. Diz çökme pozisyonundan ayağa kalkın ve kettlebell''i başınızın üzerinde uzatın. Başlangıç ​​pozisyonuna dönmek için hareketi tersten yapın. Sol elinizdeki kettlebell''den başlayarak egzersizi diğer tarafta tekrarlayın.","es":"Comienza tumbado boca arriba con las piernas extendidas y la pesa rusa sostenida en la mano derecha, con el brazo completamente extendido por encima del hombro. Flexiona la rodilla derecha y coloca el pie derecho plano en el suelo, manteniendo la pierna izquierda extendida. Presionando con el pie derecho, levanta las caderas del suelo, llegando a una posición de puente. Desliza la pierna izquierda por debajo del cuerpo, flexionando la rodilla izquierda y colocando el pie izquierdo plano en el suelo. Rota el torso hacia la izquierda, llevando la mano izquierda al suelo como apoyo. Presionando con el pie derecho y la mano izquierda, levanta el torso del suelo, llegando a una posición de rodillas. Desde la posición de rodillas, ponte de pie, manteniendo la pesa rusa extendida por encima de la cabeza. Invierte el movimiento para volver a la posición inicial. Repite el ejercicio en el otro lado, comenzando con la pesa rusa en la mano izquierda.","ru":"Начните с того, что лягте на спину, вытянув ноги и держа гирю в правой руке, рука полностью вытянута над плечом. Согните правое колено и поставьте правую ступню на землю, сохраняя левую ногу вытянутой. Нажимая правой ногой, поднимите бедра от земли, приняв положение мостика. Подведите левую ногу под тело, согнув левое колено и поставив левую ступню на землю. Поверните туловище влево, опустив левую руку на землю для поддержки. Опираясь на правую ногу и левую руку, поднимите туловище от земли и встаньте на колени. Из положения стоя на коленях встаньте, держа гирю вытянутой над головой. Выполните обратное движение, чтобы вернуться в исходное положение. Повторите упражнение в другую сторону, начиная с гири в левой руке.","zh":"首先仰卧，双腿伸展，右手握住壶铃，手臂完全伸展到肩膀上方。 弯曲右膝，将右脚平放在地面上，保持左腿伸展。 压右脚，将臀部抬离地面，进入桥位。 将左腿滑到身体下方，弯曲左膝并将左脚平放在地面上。 将躯干向左旋转，将左手放在地面上以获得支撑。 压右脚和左手，将躯干抬离地面，形成跪姿。 从跪姿站起来，保持壶铃伸过头顶。 反向运动以返回到起始位置。 从左手的壶铃开始，在另一侧重复练习。","hi":"अपने पैरों को फैलाकर अपनी पीठ के बल लेटकर शुरुआत करें और केटलबेल को अपने दाहिने हाथ में पकड़ें, हाथ पूरी तरह से आपके कंधे के ऊपर फैला हुआ हो। अपने दाहिने घुटने को मोड़ें और अपने दाहिने पैर को जमीन पर सपाट रखें, अपने बाएं पैर को फैलाए रखें। अपने दाहिने पैर से दबाव डालते हुए, पुल की स्थिति में आते हुए, अपने कूल्हों को ज़मीन से ऊपर उठाएं। अपने बाएँ पैर को अपने शरीर के नीचे सरकाएँ, अपने बाएँ घुटने को मोड़ें और अपने बाएँ पैर को ज़मीन पर सपाट रखें। अपने धड़ को बाईं ओर घुमाएं, समर्थन के लिए अपने बाएं हाथ को जमीन पर लाएं। अपने दाहिने पैर और बाएं हाथ से दबाव डालते हुए, घुटने टेकने की स्थिति में आते हुए, अपने धड़ को जमीन से ऊपर उठाएं। घुटनों के बल बैठने की स्थिति से, केटलबेल को सिर के ऊपर रखते हुए खड़े हो जाएं। प्रारंभिक स्थिति में लौटने के लिए आंदोलन को उल्टा करें। अपने बाएं हाथ में केटलबेल से शुरुआत करते हुए व्यायाम को दूसरी तरफ से दोहराएं।","pl":"Zacznij, leżąc na plecach z wyprostowanymi nogami i kettlebellem trzymanym w prawej dłoni, ramię całkowicie wyprostowane nad barkiem. Ugnij prawe kolano i postaw prawą stopę płasko na podłodze, utrzymując lewą nogę wyprostowaną. Naciskając prawą stopą, unieś biodra znad podłogi, wchodząc w pozycję mostu. Przesuń lewą nogę pod ciało, uginając lewe kolano i stawiając lewą stopę płasko na podłodze. Obróć tułów w lewo, opierając lewą dłoń na podłodze dla wsparcia. Naciskając prawą stopą i lewą dłonią, unieś tułów znad podłogi, przechodząc do pozycji klęczącej. Z pozycji klęczącej wstań, utrzymując kettlebell wyprostowany nad głową. Odwróć ruch, aby wrócić do pozycji wyjściowej. Powtórz ćwiczenie po drugiej stronie, zaczynając z kettlebellem w lewej dłoni.","ko":"등을 대고 누운 자세에서 시작하며 다리는 펼치고 케틀벨을 오른쪽 손으로 잡아 어깨 위로 팔을 완전히 펼칩니다. 오른쪽 무릎을 구부리고 오른쪽 발을 땅에 평평하게 놓으면서 왼쪽 다리는 펼친 상태를 유지합니다. 오른쪽 발로 밀어 엉덩이를 들어올려 브릿지 자세를 만듭니다. 왼쪽 다리를 몸 아래로 미끄러뜨리면서 왼쪽 무릎을 구부리고 왼쪽 발을 땅에 평평하게 놓습니다. 몸통을 왼쪽으로 회전시키면서 왼쪽 손을 땅에 놓아 지탱합니다. 오른쪽 발과 왼쪽 손으로 밀어 몸통을 들어올려 무릎을 꿇은 자세를 만듭니다. 무릎을 꿇은 자세에서 케틀벨은 계속 머리 위로 펼친 상태로 일어섭니다. 동작을 역으로 하여 시작 위치로 돌아옵니다. 케틀벨을 왼쪽 손에 들고 시작하여 다른 쪽에서도 반복합니다.","fr":"Commence allongé sur le dos, les jambes tendues et le kettlebell tenu dans ta main droite, le bras complètement tendu au-dessus de ton épaule. Fléchis ton genou droit et pose ton pied droit à plat sur le sol en gardant ta jambe gauche tendue. En poussant sur ton pied droit, soulève tes hanches du sol, en venant dans une position de pont. Fais glisser ta jambe gauche sous ton corps, en fléchissant le genou gauche et en posant le pied gauche à plat sur le sol. Fais pivoter ton torse vers la gauche, en amenant ta main gauche au sol pour te soutenir. En poussant sur ton pied droit et ta main gauche, soulève ton torse du sol, en venant dans une position agenouillée. Depuis la position à genoux, lève-toi en gardant le kettlebell tendu au-dessus de la tête. Inverse le mouvement pour revenir à la position de départ. Répète l''exercice de l''autre côté, en commençant avec le kettlebell dans ta main gauche."}'::jsonb, 'images/0551-Ha7SZ3y.jpg', 'videos/0551-Ha7SZ3y.gif', '© Gym visual — https://gymvisual.com/'),
(552, 'kettlebell two arm clean', 'shoulders', 'strength', 'shoulders', 'kettlebell', 'traps', 'delts', '["traps","forearms"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs with both hands, palms facing towards you. Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground. Explosively extend your hips and knees, using the momentum to pull the kettlebell up towards your shoulders. As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbows tucked in and the kettlebell resting on the back of your forearm. Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions.","it":"Stai con i piedi alla larghezza delle spalle, tenendo un kettlebell davanti alle cosce con entrambe le mani, i palmi rivolti verso di te. Piega leggermente le ginocchia e fai perno sui fianchi, abbassando il kettlebell verso terra. Estendi in modo esplosivo i fianchi e le ginocchia, sfruttando lo slancio per sollevare il kettlebell verso le spalle. Quando il kettlebell raggiunge l''altezza delle spalle, ruota i polsi e afferra il kettlebell nella posizione di rack, con i gomiti piegati e il kettlebell appoggiato sulla parte posteriore dell''avambraccio. Abbassare nuovamente il kettlebell nella posizione iniziale e ripetere per il numero di ripetizioni desiderato.","tr":"Ayaklarınız omuz genişliğinde açık olacak şekilde ayakta durun, kettlebell''i iki elinizle uyluklarınızın önünde tutun, avuçlarınız size doğru baksın. Dizlerinizi hafifçe bükün ve kalçalardan destek alarak kettlebell''i yere doğru indirin. Kettlebell''i omuzlarınıza doğru çekmek için momentumu kullanarak kalçalarınızı ve dizlerinizi patlayıcı bir şekilde uzatın. Kettlebell omuz yüksekliğine ulaştığında, bileklerinizi döndürün ve kettlebell''i raf konumunda, dirsekleriniz içeri sokulmuş ve kettlebell ön kolunuzun arkasına yaslanmış halde yakalayın. Kettlebell''i başlangıç ​​pozisyonuna indirin ve istenilen sayıda tekrar yapın.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente a los muslos con ambas manos, con las palmas hacia ti. Flexiona ligeramente las rodillas e inclínate desde las caderas, bajando la pesa rusa hacia el suelo. Extiende explosivamente las caderas y las rodillas, usando el impulso para tirar de la pesa rusa hacia los hombros. Cuando la pesa rusa llegue a la altura del hombro, rota las muñecas y atrápala en posición de descanso, con los codos pegados al cuerpo y la pesa rusa apoyada en la parte posterior del antebrazo. Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, держите гирю перед бедрами обеими руками, ладонями к себе. Слегка согните колени и наклонитесь в бедрах, опуская гирю к земле. Резко выпрямите бедра и колени, используя инерцию, чтобы подтянуть гирю к плечам. Когда гиря достигнет уровня плеч, поверните запястья и поймайте гирю в стойке, согнув локти и положив гирю на тыльную сторону предплечья. Опустите гирю обратно в исходное положение и повторите желаемое количество повторений.","zh":"双脚分开与肩同宽站立，双手握住壶铃放在大腿前，手掌朝向自己。 稍微弯曲膝盖并铰接臀部，将壶铃降低到地面。 爆发性伸展臀部和膝盖，利用动量将壶铃拉向肩膀。 当壶铃达到肩膀高度时，旋转手腕，将壶铃放在架子上，肘部内收，壶铃放在前臂背面。 将壶铃放回起始位置，然后重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, दोनों हाथों से अपनी जांघों के सामने केटलबेल पकड़ें, हथेलियाँ आपकी ओर हों। अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर टिकाएं, केटलबेल को ज़मीन की ओर नीचे करें। केटलबेल को अपने कंधों की ओर खींचने के लिए गति का उपयोग करते हुए, अपने कूल्हों और घुटनों को तेजी से फैलाएं। जैसे ही केटलबेल कंधे की ऊंचाई तक पहुंचती है, अपनी कलाइयों को घुमाएं और केटलबेल को रैक स्थिति में पकड़ें, अपनी कोहनियों को अंदर की ओर रखते हुए और केटलबेल को अपनी बांह के पिछले हिस्से पर टिकाते हुए। केटलबेल को वापस प्रारंभिक स्थिति में लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell przed udami obiema dłońmi, dłonie skierowane do siebie. Ugnij lekko kolana i wykonaj skłon w biodrach, opuszczając kettlebell w kierunku podłogi. Eksplozywnie wyprostuj biodra i kolana, wykorzystując pęd, aby podciągnąć kettlebell w stronę barków. Gdy kettlebell osiągnie wysokość barków, obróć nadgarstki i złap kettlebell w pozycji podpartej, z łokciami przy tułowiu, a kettlebellem opartym na tylnej stronie przedramienia. Opuść kettlebell z powrotem do pozycji wyjściowej i powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"발을 어깨너비로 벌리고 선 자세에서 양손으로 케틀벨을 허벅지 앞에 잡고 손은 자신을 향합니다. 무릎을 약간 구부리고 허리에서 구부려 케틀벨을 땅 쪽으로 낮춥니다. 폭발적으로 엉덩이와 무릎을 펴면서 모멘텀을 이용하여 케틀벨을 어깨 쪽으로 잡아당깁니다. 케틀벨이 어깨 높이에 도달했을 때 손목을 회전시키고 팔꿈치를 안쪽으로 당기며 케틀벨을 팔뚝 뒤쪽에 얹은 랙 위치에서 잡습니다. 케틀벨을 시작 위치로 내린 후 원하는 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell devant tes cuisses à deux mains, paumes tournées vers toi. Fléchis légèrement les genoux et bascule au niveau des hanches en abaissant la kettlebell vers le sol. Étends de manière explosive tes hanches et tes genoux, en utilisant l''élan pour tirer la kettlebell vers tes épaules. Lorsque le kettlebell atteint la hauteur des épaules, fais pivoter tes poignets et réceptionne le kettlebell en position rack, les coudes rentrés et le kettlebell reposant sur l''arrière de ton avant-bras. Abaisse le kettlebell jusqu''à la position de départ et répète pour le nombre de répétitions souhaité."}'::jsonb, 'images/0552-7Ba7bQ2.jpg', 'videos/0552-7Ba7bQ2.gif', '© Gym visual — https://gymvisual.com/'),
(553, 'kettlebell two arm military press', 'shoulders', 'strength', 'shoulders', 'kettlebell', 'triceps', 'delts', '["triceps","upper back"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder level with your palms facing forward. Engage your core and press the kettlebells overhead, fully extending your arms. Pause for a moment at the top, then slowly lower the kettlebells back to the starting position. Repeat for the desired number of repetitions.","it":"Stare con i piedi alla larghezza delle spalle, tenendo un kettlebell in ciascuna mano all''altezza delle spalle con i palmi rivolti in avanti. Coinvolgi il core e premi i kettlebell sopra la testa, estendendo completamente le braccia. Fermati per un momento in alto, quindi abbassa lentamente i kettlebell nella posizione iniziale. Ripetere per il numero di ripetizioni desiderato.","tr":"Ayaklarınız omuz genişliğinde açık, avuçlarınız öne bakacak şekilde her iki elinizde de omuz hizasında birer kettlebell tutun. Merkez bölgenizi devreye sokun ve kollarınızı tamamen uzatarak kettlebell''leri başınızın üzerine bastırın. Tepe noktasında bir süre duraklayın, ardından kettlebell''leri yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano a la altura del hombro con las palmas hacia adelante. Activa el core y presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo. Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Встаньте, поставив ноги на ширине плеч, держа в каждой руке по гире на уровне плеч ладонями вперед. Напрягите корпус и выжмите гири над головой, полностью выпрямляя руки. Задержитесь на мгновение в верхней точке, затем медленно опустите гири обратно в исходное положение. Повторите необходимое количество повторений.","zh":"双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高，手掌朝前。 启动你的核心并将壶铃压过头顶，充分伸展你的手臂。 在顶部暂停片刻，然后慢慢将壶铃放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, अपनी हथेलियों को आगे की ओर रखते हुए प्रत्येक हाथ में कंधे के स्तर पर केटलबेल पकड़ें। अपने कोर को संलग्न करें और अपनी बाहों को पूरी तरह फैलाते हुए केटलबेल्स को ऊपर की ओर दबाएं। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे केटलबेल्स को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w każdej dłoni na wysokości barków, dłonie skierowane do przodu. Napnij mięśnie brzucha i wypchnij kettlebelle nad głowę, w pełni prostując ramiona. Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść kettlebelle do pozycji wyjściowej. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"발을 어깨너비로 벌리고 선 자세에서 각 손에 케틀벨을 어깨 높이에서 잡고 손은 앞을 향합니다. 코어에 힘을 주고 케틀벨을 머리 위로 눌러 팔을 완전히 펼칩니다. 맨 위에서 잠깐 멈춘 후 케틀벨을 천천히 시작 위치로 내립니다. 원하는 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell dans chaque main à hauteur d''épaule, paumes tournées vers l''avant. Gaine ta sangle abdominale et pousse les kettlebells au-dessus de ta tête, en étendant complètement tes bras. Marque une pause en haut, puis abaisse lentement les kettlebells pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0553-blBXysN.jpg', 'videos/0553-blBXysN.gif', '© Gym visual — https://gymvisual.com/'),
(1345, 'kettlebell two arm row', 'back', 'strength', 'back', 'kettlebell', 'biceps', 'upper back', '["biceps","forearms"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body. Bend forward at the hips, keeping your back straight and your core engaged. Pull the kettlebells up towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the kettlebells back down to the starting position. Repeat for the desired number of repetitions.","it":"Stare con i piedi alla larghezza delle spalle, le ginocchia leggermente piegate e tenere un kettlebell in ciascuna mano con i palmi rivolti verso il corpo. Piegati in avanti sui fianchi, mantenendo la schiena dritta e il core impegnato. Tira i kettlebell verso il petto, stringendo insieme le scapole. Fermati per un momento in alto, quindi abbassa lentamente i kettlebell nella posizione iniziale. Ripetere per il numero di ripetizioni desiderato.","tr":"Ayaklarınızı omuz genişliğinde açın, dizlerinizi hafifçe bükün ve avuçlarınız vücudunuza bakacak şekilde her iki elinizde bir kettlebell tutun. Kalçalarınızı öne doğru eğin, sırtınızı düz ve merkez bölgenizi meşgul tutun. Kettlebell''leri göğsünüze doğru çekin ve kürek kemiklerinizi birbirine doğru sıkıştırın. Tepe noktasında bir süre duraklayın, ardından kettlebell''leri yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sostén una pesa rusa en cada mano con las palmas hacia el cuerpo. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Tira de las pesas rusas hacia el pecho, juntando los omóplatos. Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, колени слегка согнуты, в каждой руке держите по гире ладонями к телу. Наклонитесь вперед в бедрах, сохраняя спину прямой и напряженный корпус. Подтяните гири к груди, сведя лопатки вместе. Задержитесь на мгновение в верхней точке, затем медленно опустите гири обратно в исходное положение. Повторите необходимое количество повторений.","zh":"双脚分开与肩同宽站立，膝盖稍微弯曲，双手各握一个壶铃，手掌朝向身体。 臀部向前弯曲，保持背部挺直，核心肌群参与。 将壶铃拉向胸部，将肩胛骨挤压在一起。 在顶部暂停片刻，然后慢慢将壶铃放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, घुटने थोड़े मुड़े हुए हों और अपनी हथेलियों को अपने शरीर की ओर रखते हुए प्रत्येक हाथ में एक केटलबेल पकड़ें। अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, कूल्हों के बल आगे की ओर झुकें। अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, केटलबेल को अपनी छाती की ओर खींचें। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे केटलबेल्स को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań ze stopami rozstawionymi na szerokość barków, kolana lekko ugięte, i trzymaj kettlebell w każdej dłoni, dłonie skierowane w stronę ciała. Pochyl się do przodu w biodrach, utrzymując proste plecy i napięte mięśnie brzucha. Podciągnij kettlebelle w stronę klatki piersiowej, ściskając łopatki. Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść kettlebelle do pozycji wyjściowej. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"발을 어깨너비로 벌리고 무릎을 약간 구부린 자세에서 각 손에 케틀벨을 잡고 손은 몸을 향합니다. 허리에서 구부려 몸을 앞으로 기울이면서 등은 곧게 유지하고 코어에 힘을 줍니다. 케틀벨을 가슴 쪽으로 잡아당기면서 어깨 날개뼈를 함께 조입니다. 맨 위에서 잠깐 멈춘 후 케틀벨을 천천히 시작 위치로 내립니다. 원하는 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, les genoux légèrement fléchis, et tiens un kettlebell dans chaque main, paumes tournées vers ton corps. Penche-toi vers l''avant au niveau des hanches en gardant ton dos droit et ta sangle abdominale gainée. Tire les kettlebells vers le haut en direction de ta poitrine en contractant tes omoplates l''une vers l''autre. Marque une pause en haut, puis abaisse lentement les kettlebells pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/1345-wf24o8S.jpg', 'videos/1345-wf24o8S.gif', '© Gym visual — https://gymvisual.com/'),
(554, 'kettlebell windmill', 'waist', 'strength', 'waist', 'kettlebell', 'obliques', 'abs', '["obliques","shoulders"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a kettlebell in your right hand overhead. Rotate your left foot outwards about 45 degrees and keep your right foot pointing forward. Bend your torso to the left side, keeping your right arm extended overhead and your eyes on the kettlebell. Lower your torso as far as you can while keeping your right arm straight and your left arm extended to the side. Pause for a moment, then return to the starting position by pushing through your right foot and engaging your obliques. Repeat for the desired number of repetitions, then switch sides.","it":"Stai con i piedi alla larghezza delle spalle, tenendo un kettlebell nella mano destra sopra la testa. Ruota il piede sinistro verso l''esterno di circa 45 gradi e tieni il piede destro rivolto in avanti. Piega il busto verso sinistra, mantenendo il braccio destro esteso sopra la testa e gli occhi sul kettlebell. Abbassa il busto il più possibile mantenendo il braccio destro dritto e il braccio sinistro esteso di lato. Fai una pausa per un momento, quindi torna alla posizione di partenza spingendo con il piede destro e impegnando i tuoi obliqui. Ripeti per il numero di ripetizioni desiderato, quindi cambia lato.","tr":"Ayaklarınızı omuz genişliğinde açın ve sağ elinizde bir kettlebell''i başınızın üstünde tutun. Sol ayağınızı yaklaşık 45 derece dışarı doğru döndürün ve sağ ayağınızı ileriyi gösterecek şekilde tutun. Sağ kolunuzu yukarı doğru uzatarak ve gözlerinizi kettlebell''de tutarak gövdenizi sol tarafa doğru eğin. Sağ kolunuzu düz ve sol kolunuzu yana doğru uzatarak gövdenizi mümkün olduğu kadar indirin. Bir an duraklayın, ardından sağ ayağınızı iterek ve eğik kaslarınızı çalıştırarak başlangıç ​​pozisyonuna dönün. İstenilen tekrar sayısı kadar tekrarlayın, ardından taraf değiştirin.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en la mano derecha por encima de la cabeza. Rota el pie izquierdo hacia afuera unos 45 grados y mantén el pie derecho apuntando hacia adelante. Inclina el torso hacia el lado izquierdo, manteniendo el brazo derecho extendido por encima de la cabeza y la mirada en la pesa rusa. Baja el torso tanto como puedas mientras mantienes el brazo derecho recto y el brazo izquierdo extendido hacia el lado. Haz una pausa breve, luego vuelve a la posición inicial empujando con el pie derecho y activando los oblicuos. Repite el número de repeticiones deseado, luego cambia de lado.","ru":"Встаньте, ноги на ширине плеч, держа гирю в правой руке над головой. Поверните левую ногу наружу примерно на 45 градусов и держите правую ногу направленной вперед. Наклоните туловище в левую сторону, держа правую руку вытянутой над головой и глядя на гирю. Опустите туловище как можно ниже, сохраняя правую руку прямой, а левую — вытянутой в сторону. Сделайте паузу на мгновение, затем вернитесь в исходное положение, отталкивая правую ногу и задействуя косые мышцы живота. Повторите желаемое количество повторений, затем поменяйте сторону.","zh":"双脚分开与肩同宽站立，右手握住壶铃举过头顶。 将左脚向外旋转约 45 度，并保持右脚指向前方。 将你的躯干向左侧弯曲，保持右臂伸过头顶，眼睛盯着壶铃。 尽可能降低躯干，同时保持右臂伸直，左臂向一侧伸展。 暂停片刻，然后通过推动右脚并接合斜肌返回到起始位置。 重复所需的重复次数，然后换边。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपने दाहिने हाथ में केटलबेल को सिर के ऊपर पकड़ लें। अपने बाएँ पैर को लगभग 45 डिग्री तक बाहर की ओर घुमाएँ और अपने दाहिने पैर को आगे की ओर रखें। अपने धड़ को बायीं ओर मोड़ें, अपने दाहिने हाथ को ऊपर की ओर फैलाकर रखें और अपनी आँखें केटलबेल पर रखें। अपने दाहिने हाथ को सीधा रखते हुए और अपने बाएं हाथ को बगल की ओर फैलाते हुए अपने धड़ को जितना हो सके नीचे करें। एक पल के लिए रुकें, फिर अपने दाहिने पैर से धक्का देकर और अपनी तिरछी उंगलियों को जोड़कर प्रारंभिक स्थिति में लौट आएं। दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।","pl":"Stań ze stopami rozstawionymi na szerokość barków, trzymając kettlebell w prawej dłoni nad głową. Obróć lewą stopę na zewnątrz o około 45 stopni, trzymając prawą stopę skierowaną do przodu. Zegnij tułów w lewą stronę, utrzymując prawą rękę wyciągniętą nad głowę i wzrok skierowany na kettlebell. Opuść tułów tak nisko, jak potrafisz, utrzymując prawą rękę prostą, a lewą rękę wyciągniętą na bok. Zatrzymaj się na chwilę, a następnie wróć do pozycji wyjściowej, odpychając się przez prawą stopę i napinając mięśnie skośne brzucha. Powtórz zgodnie z zaplanowaną liczbą powtórzeń, a następnie zmień stronę.","ko":"발을 어깨너비로 벌리고 선 자세에서 오른쪽 손으로 케틀벨을 머리 위에서 잡습니다. 왼쪽 발을 약 45도 바깥쪽으로 회전시키고 오른쪽 발은 앞을 향하도록 유지합니다. 몸통을 왼쪽으로 구부리면서 오른팔은 머리 위로 펼친 상태를 유지하고 눈은 케틀벨을 봅니다. 오른쪽 팔을 곧게 유지하고 왼쪽 팔을 옆으로 펼친 상태로 몸통을 최대한 낮춥니다. 잠깐 멈춘 후 오른쪽 발로 밀어 옆구리에 힘을 주면서 시작 위치로 돌아옵니다. 원하는 횟수만큼 반복한 후 반대쪽으로 바꾸어 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un kettlebell dans ta main droite au-dessus de ta tête. Fais tourner ton pied gauche vers l''extérieur d''environ 45 degrés et garde ton pied droit pointé vers l''avant. Penche ton torse vers le côté gauche en gardant ton bras droit tendu au-dessus de ta tête et les yeux sur la kettlebell. Abaisse ton torse aussi bas que possible en gardant ton bras droit tendu et ton bras gauche étendu sur le côté. Marque une pause, puis reviens à la position de départ en poussant sur ton pied droit et en gainant tes obliques. Répète le nombre de répétitions souhaité, puis change de côté."}'::jsonb, 'images/0554-9Tkqa9O.jpg', 'videos/0554-9Tkqa9O.gif', '© Gym visual — https://gymvisual.com/'),
(555, 'kick out sit', 'upper legs', 'strength', 'upper legs', 'body weight', 'quadriceps', 'hamstrings', '["quadriceps","glutes"]'::jsonb, '{"en":"Sit on the edge of a bench or chair with your feet flat on the ground and your knees bent at a 90-degree angle. Lean back slightly and place your hands on the edge of the bench or chair for support. Engaging your hamstrings, lift your feet off the ground and extend your legs straight out in front of you. Pause for a moment at the top, then slowly bend your knees and bring your feet back towards your body. Repeat for the desired number of repetitions.","it":"Siediti sul bordo di una panca o di una sedia con i piedi appoggiati a terra e le ginocchia piegate con un angolo di 90 gradi. Appoggiati leggermente all''indietro e metti le mani sul bordo della panca o della sedia per sostenerti. Coinvolgendo i muscoli posteriori della coscia, solleva i piedi da terra ed estendi le gambe davanti a te. Fermati un attimo in alto, poi piega lentamente le ginocchia e riporta i piedi verso il corpo. Ripetere per il numero di ripetizioni desiderato.","tr":"Ayaklarınız yere düz basacak ve dizleriniz 90 derecelik bir açıyla bükülü olacak şekilde bir bankın veya sandalyenin kenarına oturun. Hafifçe geriye yaslanın ve destek için ellerinizi bankın veya sandalyenin kenarına koyun. Diz arkası kaslarınızı devreye sokarak ayaklarınızı yerden kaldırın ve bacaklarınızı düz bir şekilde önünüze doğru uzatın. Tepede bir an duraklayın, sonra yavaşça dizlerinizi bükün ve ayaklarınızı tekrar vücudunuza doğru getirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Siéntate en el borde de un banco o una silla con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Inclínate ligeramente hacia atrás y coloca las manos en el borde del banco o la silla como apoyo. Activando los isquiotibiales, levanta los pies del suelo y extiende las piernas rectas hacia adelante. Haz una pausa breve en lo alto, luego flexiona lentamente las rodillas y lleva los pies de vuelta hacia el cuerpo. Repite el número de repeticiones deseado.","ru":"Сядьте на край скамьи или стула, поставьте ступни на землю и согните колени под углом 90 градусов. Слегка откиньтесь назад и положите руки на край скамьи или стула для поддержки. Задействуя мышцы задней поверхности бедра, оторвите ступни от земли и вытяните ноги прямо перед собой. Задержитесь на мгновение в верхней точке, затем медленно согните колени и верните ступни назад к телу. Повторите необходимое количество повторений.","zh":"坐在长凳或椅子的边缘，双脚平放在地上，膝盖弯曲成 90 度角。 稍微向后倾斜，将双手放在长凳或椅子的边缘以获得支撑。 启动腿筋，将脚抬离地面，并将双腿伸直到身前。 在顶部停顿片刻，然后慢慢弯曲膝盖，将脚放回身体。 重复所需的重复次数。","hi":"अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को 90 डिग्री के कोण पर मोड़कर एक बेंच या कुर्सी के किनारे पर बैठें। थोड़ा पीछे झुकें और सहारे के लिए अपने हाथों को बेंच या कुर्सी के किनारे पर रखें। अपनी हैमस्ट्रिंग को जोड़ते हुए, अपने पैरों को ज़मीन से ऊपर उठाएं और अपने पैरों को सीधे अपने सामने फैलाएँ। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने घुटनों को मोड़ें और अपने पैरों को वापस अपने शरीर की ओर लाएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Usiądź na krawędzi ławki lub krzesła, stopy płasko oparte o podłogę, kolana ugięte pod kątem 90 stopni. Odchyl się lekko do tyłu i oprzyj dłonie o krawędź ławki lub krzesła dla wsparcia. Napinając mięśnie dwugłowe uda, unieś stopy nad podłogę i wyprostuj nogi prosto przed sobą. Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli ugnij kolana i przyciągnij stopy z powrotem w stronę ciała. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"벤치나 의자 모서리에 앉아 발은 땅에 닿고 무릎을 90도로 구부린 상태에서 시작합니다. 몸을 약간 뒤로 기울이고 벤치나 의자 모서리에 손을 놓아 지탱합니다. 햄스트링에 힘을 주면서 발을 땅에서 들어올리고 다리를 몸 앞으로 곧게 펼칩니다. 맨 위에서 잠깐 멈춘 후 천천히 무릎을 구부리고 발을 몸 쪽으로 다시 가져옵니다. 원하는 횟수만큼 반복합니다.","fr":"Assieds-toi au bord d''un banc ou d''une chaise, les pieds à plat sur le sol et les genoux fléchis à un angle de 90 degrés. Penche-toi légèrement en arrière et place tes mains sur le bord du banc ou de la chaise pour te soutenir. En gainant tes ischio-jambiers, soulève tes pieds du sol et étends tes jambes droit devant toi. Marque une pause en haut, puis fléchis lentement tes genoux et ramène tes pieds vers ton corps. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0555-v7p5bYl.jpg', 'videos/0555-v7p5bYl.gif', '© Gym visual — https://gymvisual.com/'),
(558, 'kipping muscle up', 'back', 'strength', 'back', 'body weight', 'biceps', 'lats', '["biceps","triceps","shoulders","core"]'::jsonb, '{"en":"Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart. Engage your core and use a swinging motion to generate momentum. As you swing forward, pull your chest towards the bar, using your lats and biceps to initiate the movement. Continue the upward motion until your chest reaches the bar, then transition into a dip position by pushing down on the bar and extending your arms. Lower yourself back down to the starting position by bending your arms and controlling the descent. Repeat for the desired number of repetitions.","it":"Inizia appendendoti a una barra per trazioni con una presa prona, con le mani leggermente più larghe della larghezza delle spalle. Coinvolgi il tuo core e usa un movimento oscillante per generare slancio. Mentre ti muovi in ​​avanti, tira il petto verso la barra, usando i dorsali e i bicipiti per iniziare il movimento. Continua il movimento verso l''alto finché il petto non raggiunge la barra, quindi passa alla posizione dip spingendo verso il basso la barra ed estendendo le braccia. Abbassati nuovamente nella posizione di partenza piegando le braccia e controllando la discesa. Ripetere per il numero di ripetizioni desiderato.","tr":"Eller omuz genişliğinden biraz daha geniş olacak şekilde, üstten tutuşla bir barfiks barına asılarak başlayın. Merkez bölgenizi devreye sokun ve momentum oluşturmak için sallanma hareketi kullanın. İleriye doğru sallanırken, hareketi başlatmak için lat ve bicepslerinizi kullanarak göğsünüzü bara doğru çekin. Göğsünüz bara ulaşana kadar yukarı doğru harekete devam edin, ardından barı aşağı doğru itip kollarınızı uzatarak dalma pozisyonuna geçin. Kollarınızı bükerek ve inişi kontrol ederek kendinizi başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Comienza colgándote de una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Activa el core y usa un movimiento de balanceo para generar impulso. Mientras te balanceas hacia adelante, tira del pecho hacia la barra, usando los dorsales y los bíceps para iniciar el movimiento. Continúa el movimiento ascendente hasta que el pecho llegue a la barra, luego pasa a una posición de fondos empujando hacia abajo en la barra y extendiendo los brazos. Bájate de vuelta a la posición inicial flexionando los brazos y controlando el descenso. Repite el número de repeticiones deseado.","ru":"Начните с подвешивания на перекладине хватом сверху, руки чуть шире плеч. напрягите мышцы кора ​​и используйте раскачивающие движения, чтобы создать импульс. Делая поворот вперед, подтяните грудь к перекладине, используя широчайшие и бицепсы, чтобы начать движение. Продолжайте движение вверх, пока ваша грудь не достигнет перекладины, затем перейдите в положение для отжиманий, надавив на перекладину вниз и вытянув руки. Опуститесь обратно в исходное положение, сгибая руки и контролируя опускание. Повторите необходимое количество повторений.","zh":"首先，用正手握法悬挂在引体向上杆上，双手分开的距离略大于肩宽。 启动你的核心并使用摆动动作来产生动力。 当你向前挥杆时，将胸部拉向杠铃，用背阔肌和二头肌开始动作。 继续向上运动，直到胸部到达杠铃，然后向下推杠铃并伸展手臂，过渡到双臂屈伸姿势。 弯曲手臂并控制下降，将自己放回到起始位置。 重复所需的重复次数。","hi":"ओवरहैंड पकड़ के साथ पुल-अप बार से लटकने से शुरुआत करें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें। अपने मूल को संलग्न करें और गति उत्पन्न करने के लिए एक झूलती गति का उपयोग करें। जैसे ही आप आगे की ओर झूलते हैं, आंदोलन शुरू करने के लिए अपने लैट्स और बाइसेप्स का उपयोग करते हुए अपनी छाती को बार की ओर खींचें। जब तक आपकी छाती बार तक नहीं पहुंच जाती, तब तक ऊपर की ओर गति जारी रखें, फिर बार को नीचे की ओर धकेलते हुए और अपनी बाहों को फैलाकर डिप स्थिति में आ जाएं। अपनी भुजाओं को मोड़कर और ढलान को नियंत्रित करके अपने आप को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Zacznij, zwisając na drążku do podciągania nachwytem, dłonie nieco szerzej niż szerokość barków. Napnij mięśnie brzucha i wykorzystaj ruch bujający, aby wygenerować pęd. Bujając się do przodu, podciągnij klatkę piersiową w stronę drążka, wykorzystując mięśnie najszersze grzbietu i bicepsy, aby zainicjować ruch. Kontynuuj ruch w górę, aż klatka piersiowa dotrze do drążka, a następnie przejdź do pozycji dipu, naciskając na drążek i prostując ramiona. Opuść się z powrotem do pozycji wyjściowej, uginając ramiona i kontrolując opadanie. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"턱걸이 바에 손을 위로 향하도록 잡고 어깨너비보다 약간 넓게 벌려 매달린 상태에서 시작합니다. 코어에 힘을 주고 스윙 동작을 사용하여 모멘텀을 만듭니다. 앞으로 스윙할 때 등과 이두근을 사용하여 가슴을 바 쪽으로 당겨 동작을 시작합니다. 가슴이 바에 닿을 때까지 위로 움직임을 계속한 후 바를 누르고 팔을 펴면서 딥 자세로 전환합니다. 팔을 구부리고 내려오는 것을 제어하면서 시작 위치로 몸을 다시 내립니다. 원하는 횟수만큼 반복합니다.","fr":"Commence suspendu à une barre de traction en prise pronation, les mains légèrement plus écartées que la largeur des épaules. Gaine ta sangle abdominale et utilise un mouvement de balancier pour générer de l''élan. En te balançant vers l''avant, tire ta poitrine vers la barre en utilisant tes grands dorsaux et tes biceps pour initier le mouvement. Continue le mouvement vers le haut jusqu''à ce que ta poitrine atteigne la barre, puis passe en position de dip en poussant sur la barre et en étendant tes bras. Redescends jusqu''à la position de départ en pliant les bras et en contrôlant la descente. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0558-pM07UxU.jpg', 'videos/0558-pM07UxU.gif', '© Gym visual — https://gymvisual.com/'),
(3640, 'knee touch crunch', 'waist', 'strength', 'waist', 'body weight', 'hip flexors', 'abs', '["hip flexors"]'::jsonb, '{"en":"Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, lift your shoulder blades off the ground and reach your right hand towards your left knee. Return to the starting position and repeat, this time reaching your left hand towards your right knee. Continue alternating sides for the desired number of repetitions.","it":"Sdraiati sulla schiena con le ginocchia piegate e i piedi appoggiati a terra. Metti le mani dietro la testa con i gomiti rivolti verso l''esterno. Coinvolgendo gli addominali, solleva le scapole da terra e allunga la mano destra verso il ginocchio sinistro. Ritorna alla posizione di partenza e ripeti, questa volta portando la mano sinistra verso il ginocchio destro. Continua ad alternare i lati per il numero di ripetizioni desiderato.","tr":"Dizleriniz bükülü ve ayaklarınız yere düz basacak şekilde sırt üstü yatın. Ellerinizi başınızın arkasına, dirsekleriniz dışarı bakacak şekilde yerleştirin. Karın kaslarınızı devreye sokarak kürek kemiklerinizi yerden kaldırın ve sağ elinizi sol dizinize doğru uzatın. Başlangıç ​​pozisyonuna dönün ve bu sefer sol elinizi sağ dizinize doğru uzatarak tekrarlayın. İstenilen tekrar sayısı için alternatif taraflara devam edin.","es":"Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta los omóplatos del suelo y extiende la mano derecha hacia la rodilla izquierda. Vuelve a la posición inicial y repite, esta vez extendiendo la mano izquierda hacia la rodilla derecha. Continúa alternando lados durante el número de repeticiones deseado.","ru":"Лягте на спину, согните колени и поставьте ступни на землю. Положите руки за голову локтями наружу. Включив пресс, поднимите лопатки от земли и протяните правую руку к левому колену. Вернитесь в исходное положение и повторите, на этот раз дотянув левую руку до правого колена. Продолжайте чередовать стороны желаемое количество повторений.","zh":"平躺，膝盖弯曲，双脚平放在地上。 将双手放在脑后，肘部朝外。 收紧腹肌，将肩胛骨抬离地面，并将右手伸向左膝盖。 返回起始位置并重复，这次将左手伸向右膝盖。 继续交替进行所需的重复次数。","hi":"अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ। अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें। अपने एब्स को शामिल करते हुए, अपने कंधे के ब्लेड को जमीन से ऊपर उठाएं और अपने दाहिने हाथ को अपने बाएं घुटने की ओर ले जाएं। प्रारंभिक स्थिति पर लौटें और दोहराएं, इस बार अपने बाएं हाथ को अपने दाहिने घुटने तक ले जाएं। दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।","pl":"Połóż się płasko na plecach z ugiętymi kolanami i stopami płasko opartymi o podłogę. Umieść dłonie za głową, z łokciami skierowanymi na zewnątrz. Napinając mięśnie brzucha, unieś łopatki znad podłogi i sięgnij prawą dłonią w stronę lewego kolana. Wróć do pozycji wyjściowej i powtórz, tym razem sięgając lewą dłonią w stronę prawego kolana. Kontynuuj naprzemienne wykonywanie ruchu zgodnie z zaplanowaną liczbą powtórzeń.","ko":"등을 대고 누운 자세에서 무릎을 구부리고 발은 땅에 닿은 상태에서 시작합니다. 손을 머리 뒤에 놓고 팔꿈치는 바깥쪽을 향하도록 합니다. 복근에 힘을 주고 어깨 날개뼈를 땅에서 들어올린 후 오른손을 왼쪽 무릎 쪽으로 뻗습니다. 시작 위치로 돌아온 후 이번에는 왼손을 오른쪽 무릎 쪽으로 뻗습니다. 원하는 횟수만큼 양쪽을 교대로 계속합니다.","fr":"Allonge-toi sur le dos, les genoux fléchis et les pieds à plat au sol. Place tes mains derrière ta tête avec tes coudes pointés vers l''extérieur. En gainant tes abdominaux, soulève tes omoplates du sol et amène ta main droite vers ton genou gauche. Reviens à la position de départ et répète, cette fois en tendant ta main gauche vers ton genou droit. Continue à alterner les côtés pour le nombre de répétitions souhaité."}'::jsonb, 'images/3640-dTg95eZ.jpg', 'videos/3640-dTg95eZ.gif', '© Gym visual — https://gymvisual.com/'),
(1420, 'kneeling jump squat', 'upper legs', 'strength', 'upper legs', 'barbell', 'quadriceps', 'glutes', '["quadriceps","hamstrings","calves"]'::jsonb, '{"en":"Start by kneeling on the ground with your feet hip-width apart and your toes pointing forward. Hold a barbell across your upper back, resting it on your shoulders. Engage your core and glutes, then explosively jump up into the air, extending your hips and knees. As you jump, push through your toes and fully extend your ankles, knees, and hips. Land softly back on the ground, bending your knees to absorb the impact. Immediately go into the next repetition, repeating the jump squat motion.","it":"Inizia in ginocchio a terra con i piedi alla larghezza dei fianchi e le dita dei piedi rivolte in avanti. Tieni un bilanciere sulla parte superiore della schiena, appoggiandolo sulle spalle. Coinvolgi il core e i glutei, quindi salta in aria in modo esplosivo, estendendo i fianchi e le ginocchia. Mentre salti, spingi le dita dei piedi ed estendi completamente caviglie, ginocchia e fianchi. Atterra dolcemente a terra, piegando le ginocchia per assorbire l''impatto. Passa immediatamente alla ripetizione successiva, ripetendo il movimento dello squat salto.","tr":"Ayaklarınız kalça genişliğinde açık ve ayak parmaklarınız ileriyi gösterecek şekilde yere diz çökerek başlayın. Sırtınızın üst kısmına bir halter tutun ve omuzlarınıza yaslayın. Merkez bölgenizi ve kalça kaslarınızı devreye sokun, ardından patlayıcı bir şekilde havaya sıçrayarak kalçalarınızı ve dizlerinizi uzatın. Zıplarken ayak parmaklarınızı itin ve ayak bileklerinizi, dizlerinizi ve kalçalarınızı tamamen uzatın. Çarpmayı absorbe etmek için dizlerinizi bükerek yavaşça yere inin. Hemen atlama çömelme hareketini tekrarlayarak bir sonraki tekrara geçin.","es":"Comienza arrodillado en el suelo con los pies separados a la altura de las caderas y los dedos de los pies apuntando hacia adelante. Sujeta una barra sobre la parte superior de la espalda, apoyándola en los hombros. Activa el core y los glúteos, luego salta explosivamente hacia arriba, extendiendo las caderas y las rodillas. Mientras saltas, empuja con los dedos de los pies y extiende por completo los tobillos, las rodillas y las caderas. Aterriza suavemente de vuelta en el suelo, flexionando las rodillas para absorber el impacto. Pasa de inmediato a la siguiente repetición, repitiendo el movimiento de sentadilla con salto.","ru":"Начните с того, что встаньте на колени на землю, поставив ноги на ширине плеч и направив пальцы ног вперед. Держите штангу через верхнюю часть спины, положив ее на плечи. Задействуйте корпус и ягодицы, затем резко подпрыгните в воздух, выпрямляя бедра и колени. Во время прыжка надавите на пальцы ног и полностью выпрямите лодыжки, колени и бедра. Мягко приземлитесь на землю, согнув колени, чтобы поглотить удар. Сразу же переходите к следующему повторению, повторяя движение приседа с выпрыгиванием.","zh":"首先跪在地上，双脚分开与臀部同宽，脚趾向前。 将杠铃放在上背部，将其放在肩膀上。 启动你的核心和臀部，然后爆发性地跳到空中，伸展你的臀部和膝盖。 跳跃时，用脚趾推动并充分伸展脚踝、膝盖和臀部。 轻轻地回到地面，弯曲膝盖以吸收冲击力。 立即进入下一个重复，重复跳蹲动作。","hi":"अपने पैरों को कूल्हे-चौड़ाई पर अलग रखते हुए और अपने पैर की उंगलियों को आगे की ओर रखते हुए जमीन पर घुटने टेककर शुरुआत करें। अपनी ऊपरी पीठ पर एक बारबेल पकड़ें, इसे अपने कंधों पर टिकाएं। अपने कोर और ग्लूट्स को संलग्न करें, फिर अपने कूल्हों और घुटनों को फैलाते हुए तेजी से हवा में उछलें। जैसे ही आप कूदते हैं, अपने पैर की उंगलियों से धक्का दें और अपनी टखनों, घुटनों और कूल्हों को पूरी तरह फैलाएं। प्रभाव को अवशोषित करने के लिए अपने घुटनों को मोड़ते हुए, धीरे से वापस जमीन पर उतरें। जंप स्क्वाट गति को दोहराते हुए तुरंत अगली पुनरावृत्ति पर जाएं।","pl":"Zacznij, klęcząc na podłodze ze stopami rozstawionymi na szerokość bioder, palce stóp skierowane do przodu. Trzymaj sztangę na górnej części pleców, opierając ją na barkach. Napnij mięśnie brzucha i pośladków, a następnie eksplozywnie wyskocz w powietrze, prostując biodra i kolana. Skacząc, odepchnij się palcami stóp i w pełni wyprostuj stawy skokowe, kolana i biodra. Wyląduj miękko z powrotem na podłodze, uginając kolana, aby zamortyzować uderzenie. Od razu przejdź do kolejnego powtórzenia, powtarzając ruch skoku w przysiadzie.","ko":"땅에 무릎을 꿇은 자세에서 발은 엉덩이너비로 벌리고 발가락은 앞을 향하게 시작합니다. 바벨을 등 위쪽에 걸쳐 어깨에 올려놓습니다. 코어와 글루트에 힘을 주고 폭발적으로 공중으로 점프하면서 엉덩이와 무릎을 펼칩니다. 점프할 때 발가락으로 밀어 발목, 무릎, 엉덩이를 완전히 펼칩니다. 땅에 부드럽게 착지하여 무릎을 구부려 충격을 흡수합니다. 다음 반복을 위해 즉시 점프 스쿼트 동작을 반복합니다.","fr":"Commence à genoux au sol, les pieds écartés à la largeur des hanches et les orteils pointés vers l''avant. Tiens une barre en travers du haut de ton dos, en la posant sur tes épaules. Gaine ta sangle abdominale et tes fessiers, puis saute explosivement en l''air, en étendant tes hanches et tes genoux. En sautant, pousse sur tes orteils et étends complètement tes chevilles, tes genoux et tes hanches. Atterris en douceur au sol, en fléchissant les genoux pour absorber l''impact. Enchaîne immédiatement avec la répétition suivante, en répétant le mouvement de squat sauté."}'::jsonb, 'images/1420-UgDm3oy.jpg', 'videos/1420-UgDm3oy.gif', '© Gym visual — https://gymvisual.com/'),
(1346, 'kneeling lat stretch', 'back', 'strength', 'back', 'body weight', 'shoulders', 'lats', '["shoulders","triceps"]'::jsonb, '{"en":"Kneel on the ground with your knees hip-width apart and your toes pointing back. Extend your arms overhead and interlace your fingers. Keeping your back straight, slowly lean to the right side, feeling a stretch in your left lat muscle. Hold the stretch for 20-30 seconds, then return to the starting position. Repeat the stretch on the left side, leaning to the left and feeling a stretch in your right lat muscle. Continue alternating sides for the desired number of repetitions.","it":"Inginocchiati a terra con le ginocchia alla larghezza dei fianchi e le dita dei piedi rivolte all''indietro. Estendi le braccia sopra la testa e intreccia le dita. Tenendo la schiena dritta, inclinati lentamente verso il lato destro, avvertendo un allungamento nel muscolo lat sinistro. Mantieni l''allungamento per 20-30 secondi, quindi torna alla posizione di partenza. Ripeti l''allungamento sul lato sinistro, inclinandoti a sinistra e avvertendo un allungamento nel muscolo lat destro. Continua ad alternare i lati per il numero di ripetizioni desiderato.","tr":"Dizleriniz kalça genişliğinde açık ve ayak parmaklarınız geriye dönük olacak şekilde yere diz çökün. Kollarınızı yukarı doğru uzatın ve parmaklarınızı birbirine geçirin. Sırtınızı düz tutarak yavaşça sağ tarafa doğru eğin, sol lat kasınızda bir gerginlik hissedin. Gerdirmeyi 20-30 saniye kadar tutun, ardından başlangıç ​​pozisyonuna dönün. Sola doğru eğilerek ve sağ lat kasınızda bir gerginlik hissederek sol taraftaki esnemeyi tekrarlayın. İstenilen tekrar sayısı için alternatif taraflara devam edin.","es":"Arrodíllate en el suelo con las rodillas separadas a la altura de las caderas y los dedos de los pies apuntando hacia atrás. Extiende los brazos por encima de la cabeza y entrelaza los dedos. Manteniendo la espalda recta, inclínate lentamente hacia el lado derecho, sintiendo un estiramiento en el dorsal izquierdo. Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial. Repite el estiramiento en el lado izquierdo, inclinándote hacia la izquierda y sintiendo un estiramiento en el dorsal derecho. Continúa alternando lados durante el número de repeticiones deseado.","ru":"Встаньте на колени, расставив колени на ширине плеч и носки ног назад. Вытяните руки над головой и переплетите пальцы. Держа спину прямо, медленно наклонитесь в правую сторону, чувствуя растяжение левой широчайшей мышцы. Удерживайте растяжку 20–30 секунд, затем вернитесь в исходное положение. Повторите растяжку с левой стороны, наклоняясь влево и чувствуя растяжение правой широчайшей мышцы. Продолжайте чередовать стороны желаемое количество повторений.","zh":"跪在地上，膝盖分开与臀部同宽，脚趾向后。 将双臂伸过头顶，手指交叉。 保持背部挺直，慢慢向右侧倾斜，感受左侧背阔肌的拉伸。 保持伸展动作 20-30 秒，然后回到起始位置。 在左侧重复该拉伸动作，向左侧倾斜，感受右侧背阔肌的拉伸。 继续交替进行所需的重复次数。","hi":"अपने घुटनों को कूल्हे-चौड़ाई पर अलग रखते हुए और अपने पैर की उंगलियों को पीछे की ओर रखते हुए जमीन पर झुकें। अपनी बाहों को ऊपर की ओर फैलाएं और अपनी उंगलियों को आपस में फंसा लें। अपनी पीठ को सीधा रखते हुए, धीरे-धीरे दाहिनी ओर झुकें, अपनी बाईं लैट मांसपेशी में खिंचाव महसूस करें। 20-30 सेकंड तक खिंचाव बनाए रखें, फिर प्रारंभिक स्थिति में लौट आएं। बाईं ओर के खिंचाव को दोहराएं, बाईं ओर झुकें और अपनी दाहिनी लैट मांसपेशी में खिंचाव महसूस करें। दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।","pl":"Uklęknij na podłodze, kolana rozstawione na szerokość bioder, palce stóp skierowane do tyłu. Wyciągnij ramiona nad głowę i spleć palce dłoni. Utrzymując proste plecy, powoli pochyl się w prawą stronę, odczuwając rozciąganie w lewym mięśniu najszerszym grzbietu. Przytrzymaj rozciąganie przez 20-30 sekund, a następnie wróć do pozycji wyjściowej. Powtórz rozciąganie po lewej stronie, pochylając się w lewo i odczuwając rozciąganie w prawym mięśniu najszerszym grzbietu. Kontynuuj naprzemienne rozciąganie zgodnie z zaplanowaną liczbą powtórzeń.","ko":"땅에 무릎을 꿇은 자세에서 무릎은 엉덩이너비로 벌리고 발가락은 뒤를 향하게 합니다. 팔을 머리 위로 펼치고 손가락을 깍지껴 연결합니다. 등을 곧게 유지하면서 오른쪽으로 천천히 몸을 기울여 왼쪽 광배근에 스트레치를 느낍니다. 스트레치를 20-30초 유지한 후 시작 위치로 돌아옵니다. 왼쪽으로 기울여 오른쪽 광배근에 스트레치를 느끼면서 양쪽을 교대로 계속합니다. 원하는 횟수만큼 양쪽을 반복합니다.","fr":"Mets-toi à genoux au sol, les genoux écartés à la largeur des hanches et les orteils pointés vers l''arrière. Étends tes bras au-dessus de la tête et entrelace tes doigts. En gardant le dos droit, penche-toi lentement vers le côté droit, en ressentant un étirement dans ton grand dorsal gauche. Maintiens l''étirement pendant 20 à 30 secondes, puis reviens à la position de départ. Répète l''étirement du côté gauche, en te penchant vers la gauche et en ressentant un étirement dans ton grand dorsal droit. Continue à alterner les côtés pour le nombre de répétitions souhaité."}'::jsonb, 'images/1346-f38OEuO.jpg', 'videos/1346-f38OEuO.gif', '© Gym visual — https://gymvisual.com/'),
(3239, 'kneeling plank tap shoulder (male)', 'waist', 'strength', 'waist', 'body weight', 'shoulders', 'abs', '["shoulders","triceps"]'::jsonb, '{"en":"Start in a kneeling position with your hands on the ground, shoulder-width apart. Extend your legs behind you, resting on your toes, and lift your body into a plank position. Keeping your core engaged and your hips stable, lift one hand off the ground and tap the opposite shoulder. Return the hand to the ground and repeat with the other hand. Continue alternating sides for the desired number of repetitions.","it":"Inizia in posizione inginocchiata con le mani a terra, alla larghezza delle spalle. Estendi le gambe dietro di te, appoggiandoti sulle punte dei piedi e solleva il corpo in una posizione di plancia. Mantenendo il core impegnato e i fianchi stabili, solleva una mano da terra e tocca la spalla opposta. Riporta la mano a terra e ripeti con l''altra mano. Continua ad alternare i lati per il numero di ripetizioni desiderato.","tr":"Elleriniz yerde, omuz genişliğinde açık olacak şekilde diz çökme pozisyonunda başlayın. Bacaklarınızı arkanıza doğru uzatın, ayak parmaklarınızın üzerinde durun ve vücudunuzu tahta pozisyonuna kaldırın. Merkez bölgenizi meşgul ve kalçalarınızı sabit tutarak bir elinizi yerden kaldırın ve karşı omzunuza hafifçe vurun. Elinizi yere koyun ve diğer elinizle tekrarlayın. İstenilen tekrar sayısı için alternatif taraflara devam edin.","es":"Comienza en posición de rodillas con las manos en el suelo, separadas a la altura de los hombros. Extiende las piernas hacia atrás, apoyándote en los dedos de los pies, y levanta el cuerpo a una posición de plancha. Manteniendo el core activado y las caderas estables, levanta una mano del suelo y toca el hombro opuesto. Devuelve la mano al suelo y repite con la otra mano. Continúa alternando lados durante el número de repeticiones deseado.","ru":"Начните в положении стоя на коленях, положив руки на землю на ширине плеч. Вытяните ноги позади себя, опираясь на носки, и поднимите тело в положение планки. Сохраняя корпус напряженным, а бедра устойчивыми, поднимите одну руку от земли и коснитесь противоположного плеча. Верните руку на землю и повторите то же самое с другой рукой. Продолжайте чередовать стороны желаемое количество повторений.","zh":"从跪姿开始，双手放在地上，与肩同宽。 将双腿伸到身后，用脚趾支撑，将身体抬起成平板支撑姿势。 保持核心参与并保持臀部稳定，将一只手抬离地面并拍打另一侧的肩膀。 将手放回地面并用另一只手重复此操作。 继续交替进行所需的重复次数。","hi":"अपने हाथों को कंधे की चौड़ाई के बराबर दूरी पर ज़मीन पर रखते हुए घुटनों के बल बैठ कर शुरुआत करें। अपने पैरों को अपने पीछे फैलाएं, अपने पैर की उंगलियों पर आराम करें और अपने शरीर को तख़्त स्थिति में उठाएं। अपने कोर को व्यस्त रखते हुए और अपने कूल्हों को स्थिर रखते हुए, एक हाथ को जमीन से ऊपर उठाएं और विपरीत कंधे को थपथपाएं। हाथ को ज़मीन पर लौटाएँ और दूसरे हाथ से दोहराएँ। दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।","pl":"Zacznij w pozycji klęczącej z dłońmi opartymi na podłodze, rozstawionymi na szerokość barków. Wyprostuj nogi za sobą, opierając się na palcach stóp, i unieś ciało do pozycji deski. Utrzymując napięte mięśnie brzucha i stabilne biodra, unieś jedną dłoń znad podłogi i dotknij przeciwnego barku. Wróć dłonią do podłogi i powtórz drugą dłonią. Kontynuuj naprzemienne wykonywanie ruchu zgodnie z zaplanowaną liczbą powtórzeń.","ko":"무릎을 꿇은 자세에서 손을 땅에 어깨너비로 벌려 시작합니다. 다리를 뒤로 펼쳐 발가락으로 받친 상태에서 몸을 플랭크 자세로 들어올립니다. 코어에 힘을 주고 엉덩이를 안정적으로 유지하면서 한쪽 손을 땅에서 들어올려 반대쪽 어깨를 탭합니다. 손을 땅에 다시 놓고 다른 손으로 반복합니다. 원하는 횟수만큼 양쪽을 교대로 계속합니다.","fr":"Commence à genoux, les mains sur le sol, écartées à la largeur des épaules. Étends tes jambes derrière toi, en appui sur les orteils, et soulève ton corps en position de planche. En gardant ta sangle abdominale gainée et tes hanches stables, soulève une main du sol et tape l''épaule opposée. Ramène la main au sol et répète avec l''autre main. Continue à alterner les côtés pour le nombre de répétitions souhaité."}'::jsonb, 'images/3239-h1ezqSu.jpg', 'videos/3239-h1ezqSu.gif', '© Gym visual — https://gymvisual.com/'),
(3211, 'kneeling push-up (male)', 'chest', 'strength', 'chest', 'body weight', 'triceps', 'pectorals', '["triceps","shoulders"]'::jsonb, '{"en":"Start by kneeling on the ground with your hands shoulder-width apart, fingers pointing forward. Extend your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels. Engage your core and lower your body towards the ground by bending your elbows, keeping them close to your sides. Continue lowering until your chest is just above the ground, then push back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.","it":"Inizia in ginocchio a terra con le mani alla larghezza delle spalle, le dita rivolte in avanti. Estendi le gambe dietro di te, appoggiandole sulle punte dei piedi, in modo che il tuo corpo formi una linea retta dalla testa ai talloni. Coinvolgi il core e abbassa il corpo verso terra piegando i gomiti, tenendoli vicini ai fianchi. Continua ad abbassarti finché il petto non si trova appena sopra il suolo, quindi torna alla posizione iniziale raddrizzando le braccia. Ripetere per il numero di ripetizioni desiderato.","tr":"Elleriniz omuz genişliğinde açık, parmaklarınız ileriyi gösterecek şekilde yere diz çökerek başlayın. Vücudunuz baştan topuklara kadar düz bir çizgi oluşturacak şekilde ayak parmaklarınızın ucuna yaslanarak bacaklarınızı arkanıza doğru uzatın. Merkez bölgenizi devreye sokun ve dirseklerinizi bükerek, yanlarınıza yakın tutarak vücudunuzu yere doğru indirin. Göğsünüz yerden hemen yukarı çıkana kadar alçalmaya devam edin, ardından kollarınızı düzleştirerek başlangıç ​​pozisyonuna geri dönün. İstenilen sayıda tekrar için tekrarlayın.","es":"Comienza arrodillado en el suelo con las manos separadas a la altura de los hombros, los dedos apuntando hacia adelante. Extiende las piernas hacia atrás, apoyándote en la punta de los pies, de modo que tu cuerpo forme una línea recta desde la cabeza hasta los talones. Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Continúa bajando hasta que el pecho esté justo encima del suelo, luego empuja hacia arriba a la posición inicial enderezando los brazos. Repite el número de repeticiones deseado.","ru":"Начните с того, что встаньте на колени на землю, поставив руки на ширине плеч, пальцы направлены вперед. Вытяните ноги позади себя, опираясь на подушечки стоп так, чтобы ваше тело образовывало прямую линию от головы до пяток. Напрягите корпус и опустите тело к земле, сгибая локти и держа их близко к бокам. Продолжайте опускаться до тех пор, пока ваша грудь не окажется чуть выше земли, затем вернитесь в исходное положение, выпрямляя руки. Повторите необходимое количество повторений.","zh":"首先跪在地上，双手与肩同宽，手指指向前方。 将双腿伸到身后，放在脚掌上，使身体从头到脚跟形成一条直线。 弯曲肘部，保持核心靠近身体两侧，将身体压向地面。 继续降低，直到胸部刚好高于地面，然后伸直手臂，将其推回起始位置。 重复所需的重复次数。","hi":"अपने हाथों को कंधे की चौड़ाई पर फैलाकर, उंगलियों को आगे की ओर रखते हुए, ज़मीन पर घुटने टेककर शुरुआत करें। अपने पैरों को अपने पैरों के पंजों पर टिकाते हुए अपने पीछे फैलाएँ, ताकि आपका शरीर सिर से एड़ी तक एक सीधी रेखा बना ले। अपने कोर को संलग्न करें और अपनी कोहनियों को मोड़कर, उन्हें अपनी भुजाओं के पास रखते हुए, अपने शरीर को ज़मीन की ओर नीचे लाएँ। जब तक आपकी छाती जमीन से ठीक ऊपर न हो जाए, तब तक नीचे आना जारी रखें, फिर अपनी बाहों को सीधा करके प्रारंभिक स्थिति में वापस आ जाएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Zacznij, klęcząc na podłodze z dłońmi rozstawionymi na szerokość barków, palce skierowane do przodu. Wyprostuj nogi za sobą, opierając się na palcach stóp, tak aby ciało tworzyło linię prostą od głowy do pięt. Napnij mięśnie brzucha i opuść ciało w stronę podłogi, uginając łokcie i trzymając je blisko boków. Kontynuuj opuszczanie, aż klatka piersiowa znajdzie się tuż nad podłogą, a następnie wypchnij się z powrotem do pozycji wyjściowej, prostując ramiona. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"땅에 무릎을 꿇은 자세에서 손을 어깨너비로 벌리고 손가락은 앞을 향하도록 시작합니다. 다리를 뒤로 펼쳐 발가락으로 받치면서 머리에서 발뒤꿈치까지 몸이 일직선을 이루도록 합니다. 코어에 힘을 주고 팔꿈치를 구부려 몸을 땅 쪽으로 낮추면서 팔꿈치는 몸 옆에 가깝게 유지합니다. 가슴이 땅 바로 위에 올 때까지 계속 낮춘 후 팔을 펴면서 밀어 시작 위치로 돌아옵니다. 원하는 횟수만큼 반복합니다.","fr":"Commence à genoux au sol, les mains écartées à la largeur des épaules, les doigts pointés vers l''avant. Étends tes jambes derrière toi, en appui sur la pointe des pieds, de sorte que ton corps forme une ligne droite de la tête aux talons. Gaine ta sangle abdominale et abaisse ton corps vers le sol en pliant tes coudes, en les gardant près de tes flancs. Continue à descendre jusqu''à ce que ta poitrine soit juste au-dessus du sol, puis repousse vers le haut jusqu''à la position de départ en tendant tes bras. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/3211-ZOuKWir.jpg', 'videos/3211-ZOuKWir.gif', '© Gym visual — https://gymvisual.com/'),
(3288, 'korean dips', 'chest', 'strength', 'chest', 'body weight', 'triceps', 'pectorals', '["triceps","shoulders"]'::jsonb, '{"en":"Position yourself between two parallel bars with your arms extended and supporting your body weight. Lower your body by bending your elbows until your upper arms are parallel to the ground. Pause for a moment, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.","it":"Posizionati tra due barre parallele con le braccia tese e sostenendo il peso del corpo. Abbassa il corpo piegando i gomiti finché la parte superiore delle braccia non è parallela al suolo. Fai una pausa per un momento, quindi ritorna alla posizione di partenza raddrizzando le braccia. Ripetere per il numero di ripetizioni desiderato.","tr":"Kollarınız uzatılmış ve vücut ağırlığınızı destekleyecek şekilde kendinizi iki paralel çubuğun arasına konumlandırın. Üst kollarınız yere paralel oluncaya kadar dirseklerinizi bükerek vücudunuzu indirin. Bir an duraklayın, ardından kollarınızı düzleştirerek kendinizi başlangıç ​​pozisyonuna doğru itin. İstenilen sayıda tekrar için tekrarlayın.","es":"Colócate entre dos barras paralelas con los brazos extendidos sosteniendo el peso de tu cuerpo. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.","ru":"Встаньте между двумя параллельными брусьями, вытянув руки и поддерживая вес своего тела. Опустите тело, сгибая локти, пока плечи не станут параллельны земле. Сделайте паузу на мгновение, затем вернитесь в исходное положение, выпрямляя руки. Повторите необходимое количество повторений.","zh":"将自己定位在两个双杠之间，双臂伸展并支撑体重。 弯曲肘部降低身体，直到上臂与地面平行。 暂停片刻，然后伸直手臂，将自己推回起始位置。 重复所需的重复次数。","hi":"अपनी बाहों को फैलाकर और अपने शरीर के वजन को सहारा देते हुए अपने आप को दो समानांतर पट्टियों के बीच रखें। अपनी कोहनियों को मोड़कर अपने शरीर को तब तक नीचे लाएँ जब तक कि आपकी ऊपरी भुजाएँ ज़मीन के समानांतर न हो जाएँ। एक पल के लिए रुकें, फिर अपनी बाहों को सीधा करके खुद को शुरुआती स्थिति में वापस धकेलें। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Ustaw się między dwoma równoległymi poręczami, ramiona wyprostowane i podpierające ciężar ciała. Opuść ciało, uginając łokcie, aż ramiona górne będą równoległe do podłogi. Zatrzymaj się na chwilę, a następnie wypchnij się z powrotem do pozycji wyjściowej, prostując ramiona. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"두 개의 평행 바 사이에 위치하여 팔을 펼친 상태로 몸무게를 지탱합니다. 팔꿈치를 구부려 몸을 낮추면서 위팔이 땅과 평행할 때까지 내립니다. 잠깐 멈춘 후 팔을 펴면서 밀어 시작 위치로 돌아옵니다. 원하는 횟수만큼 반복합니다.","fr":"Positionne-toi entre deux barres parallèles, les bras tendus et soutenant le poids de ton corps. Abaisse ton corps en fléchissant tes coudes jusqu''à ce que le haut de tes bras soit parallèle au sol. Marque une pause, puis repousse-toi vers le haut jusqu''à la position de départ en tendant tes bras. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/3288-rWoBmi5.jpg', 'videos/3288-rWoBmi5.gif', '© Gym visual — https://gymvisual.com/'),
(3418, 'l-pull-up', 'back', 'strength', 'back', 'body weight', 'biceps', 'lats', '["biceps","forearms"]'::jsonb, '{"en":"Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart. Hang with your arms fully extended and your body straight. Engage your lats and biceps to pull your body up towards the bar, keeping your elbows close to your body. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.","it":"Afferra la barra per trazioni con una presa prona, leggermente più larga della larghezza delle spalle. Appendere con le braccia completamente distese e il corpo dritto. Coinvolgi i dorsali e i bicipiti per sollevare il corpo verso la barra, mantenendo i gomiti vicini al corpo. Continua a tirare finché il mento non è sopra la barra. Fai una pausa per un momento in alto, quindi abbassa lentamente il corpo fino alla posizione di partenza. Ripetere per il numero di ripetizioni desiderato.","tr":"Barfiks çubuğunu omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayarak kavrayın. Kollarınız tamamen uzatılmış ve vücudunuz düz olacak şekilde asın. Dirseklerinizi vücudunuza yakın tutarak vücudunuzu bara doğru çekmek için lat ve bicepslerinizi kullanın. Çeneniz çubuğun üstüne çıkana kadar çekmeye devam edin. Tepe noktasında bir an duraklayın, ardından vücudunuzu yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros. Cuélgate con los brazos completamente extendidos y el cuerpo recto. Activa los dorsales y los bíceps para llevar el cuerpo hacia arriba en dirección a la barra, manteniendo los codos cerca del cuerpo. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Возьмитесь за перекладину хватом сверху, на расстоянии чуть шире плеч. Висите, полностью вытянув руки и выпрямив тело. Задействуйте широчайшие и бицепсы, чтобы подтянуть тело к перекладине, держа локти близко к телу. Продолжайте тянуть, пока подбородок не окажется над перекладиной. Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение. Повторите необходимое количество повторений.","zh":"正手握住引体向上杆，握距略宽于肩宽。 双臂完全伸展，身体伸直。 收紧背阔肌和二头肌，将身体拉向杠铃杆，保持肘部靠近身体。 继续拉，直到下巴位于杠铃上方。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。","hi":"पुल-अप बार को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें। अपनी बाहों को पूरी तरह फैलाकर और अपने शरीर को सीधा करके लटकें। अपनी कोहनियों को अपने शरीर के करीब रखते हुए, अपने शरीर को बार की ओर खींचने के लिए अपने लैट्स और बाइसेप्स को संलग्न करें। तब तक खींचते रहें जब तक आपकी ठुड्डी बार के ऊपर न आ जाए। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Chwyć drążek do podciągania nachwytem, nieco szerzej niż szerokość barków. Zwiśnij z całkowicie wyprostowanymi ramionami i prostym ciałem. Napnij mięśnie najszersze grzbietu i bicepsy, aby podciągnąć ciało w stronę drążka, trzymając łokcie blisko ciała. Kontynuuj podciąganie, aż broda znajdzie się nad drążkiem. Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść ciało do pozycji wyjściowej. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"턱걸이 바를 손을 위로 향하도록 잡고 어깨너비보다 약간 넓게 벌려 잡습니다. 팔을 완전히 펼친 상태로 매달려 몸을 곧게 유지합니다. 등과 이두근에 힘을 주고 팔꿈치를 몸에 가깝게 유지하면서 몸을 바 쪽으로 당겨 올립니다. 턱이 바 위에 올 때까지 계속 당겨 올립니다. 맨 위에서 잠깐 멈춘 후 천천히 시작 위치로 몸을 내립니다. 원하는 횟수만큼 반복합니다.","fr":"Saisis la barre de traction avec une prise en pronation, un peu plus large que la largeur des épaules. Suspends-toi, les bras complètement étendus et le corps droit. Contracte tes grands dorsaux et tes biceps pour hisser ton corps vers la barre, en gardant les coudes près du corps. Continue à tirer jusqu''à ce que ton menton soit au-dessus de la barre. Marque une pause en haut, puis abaisse lentement ton corps pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/3418-d1GgzTU.jpg', 'videos/3418-d1GgzTU.gif', '© Gym visual — https://gymvisual.com/'),
(3419, 'l-sit on floor', 'waist', 'strength', 'waist', 'body weight', 'hip flexors', 'abs', '["hip flexors"]'::jsonb, '{"en":"Sit on the floor with your legs extended in front of you. Place your hands on the floor beside your hips, fingers pointing forward. Engage your core and lift your legs off the ground, keeping them straight. Try to bring your legs parallel to the floor, forming an ''L'' shape with your body. Hold this position for as long as you can. Slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.","it":"Siediti sul pavimento con le gambe distese davanti a te. Metti le mani sul pavimento accanto ai fianchi, con le dita rivolte in avanti. Coinvolgi il tuo core e solleva le gambe da terra, mantenendole dritte. Cerca di portare le gambe parallele al pavimento, formando una \"L\" con il tuo corpo. Mantieni questa posizione il più a lungo possibile. Abbassa lentamente le gambe fino alla posizione di partenza. Ripetere per il numero di ripetizioni desiderato.","tr":"Bacaklarınız önünüzde uzatılmış halde yere oturun. Ellerinizi kalçalarınızın yanına, parmaklarınız ileriyi gösterecek şekilde yere koyun. Merkez bölgenizi devreye sokun ve bacaklarınızı düz tutarak yerden kaldırın. Bacaklarınızı yere paralel hale getirerek vücudunuzla ''L'' şekli oluşturmaya çalışın. Bu pozisyonu mümkün olduğu kadar uzun süre koruyun. Bacaklarınızı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Siéntate en el suelo con las piernas extendidas frente a ti. Coloca las manos en el suelo junto a las caderas, con los dedos apuntando hacia adelante. Activa el core y levanta las piernas del suelo, manteniéndolas rectas. Intenta llevar las piernas paralelas al suelo, formando una ''L'' con el cuerpo. Mantén esta posición durante el mayor tiempo posible. Baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Сядьте на пол, вытянув ноги перед собой. Положите руки на пол рядом с бедрами, пальцы направлены вперед. Напрягите корпус и поднимите ноги от земли, сохраняя их прямыми. Постарайтесь поставить ноги параллельно полу, образуя своим телом букву «L». Удерживайте это положение столько, сколько сможете. Медленно опустите ноги обратно в исходное положение. Повторите необходимое количество повторений.","zh":"坐在地板上，双腿伸到身前。 将双手放在臀部旁边的地板上，手指指向前方。 启动你的核心并将双腿抬离地面，保持伸直。 尝试使双腿与地面平行，与身体形成“L”形。 尽可能长时间地保持这个姿势。 慢慢地将双腿放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को अपने सामने फैलाकर फर्श पर बैठें। अपने हाथों को अपने कूल्हों के पास फर्श पर रखें, उंगलियां आगे की ओर हों। अपने कोर को संलग्न करें और अपने पैरों को सीधा रखते हुए जमीन से ऊपर उठाएं। अपने शरीर के साथ ''L'' आकार बनाते हुए अपने पैरों को फर्श के समानांतर लाने का प्रयास करें। जब तक आप कर सकते हैं इस स्थिति में रहें। धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Usiądź na podłodze z nogami wyprostowanymi przed sobą. Umieść dłonie na podłodze obok bioder, palce skierowane do przodu. Napnij mięśnie brzucha i unieś nogi nad podłogę, utrzymując je proste. Postaraj się unieść nogi równolegle do podłogi, tworząc ciałem literę „L”. Przytrzymaj tę pozycję tak długo, jak potrafisz. Powoli opuść nogi z powrotem do pozycji wyjściowej. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"바닥에 앉아 다리를 몸 앞으로 펼친 자세에서 시작합니다. 손을 엉덩이 옆 바닥에 놓고 손가락은 앞을 향하도록 합니다. 코어에 힘을 주고 다리를 땅에서 들어올려 곧게 유지합니다. 다리를 땅과 평행하게 가져가려고 하여 몸으로 L자 모양을 만듭니다. 이 자세를 최대한 오래 유지합니다. 다리를 천천히 땅에 다시 내립니다. 원하는 횟수만큼 반복합니다.","fr":"Assieds-toi au sol, les jambes tendues devant toi. Place tes mains au sol à côté de tes hanches, les doigts pointés vers l''avant. Gaine ta sangle abdominale et lève tes jambes du sol, en les gardant droites. Essaie d''amener tes jambes parallèles au sol, en formant un « L » avec ton corps. Maintiens cette position aussi longtemps que possible. Abaisse lentement tes jambes vers la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/3419-UpWmA5E.jpg', 'videos/3419-UpWmA5E.gif', '© Gym visual — https://gymvisual.com/'),
(562, 'landmine 180', 'waist', 'strength', 'waist', 'barbell', 'obliques', 'abs', '["obliques","quadriceps"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart and hold the barbell with both hands in front of your chest. Bend your knees slightly and rotate your torso to the right, swinging the barbell down towards your right hip. As you reach the bottom of the movement, quickly reverse the motion and rotate your torso to the left, swinging the barbell up and across your body towards your left shoulder. Continue this twisting motion, alternating sides, for the desired number of repetitions.","it":"Stare con i piedi alla larghezza delle spalle e tenere il bilanciere con entrambe le mani davanti al petto. Piega leggermente le ginocchia e ruota il busto verso destra, facendo oscillare il bilanciere verso il fianco destro. Quando raggiungi la fine del movimento, inverti rapidamente il movimento e ruota il busto verso sinistra, facendo oscillare il bilanciere verso l''alto e attraverso il corpo verso la spalla sinistra. Continua questo movimento di torsione, alternando i lati, per il numero di ripetizioni desiderato.","tr":"Ayaklarınızı omuz genişliğinde açın ve halteri iki elinizle göğsünüzün önünde tutun. Dizlerinizi hafifçe bükün ve gövdenizi sağa döndürerek halteri sağ kalçanıza doğru sallayın. Hareketin alt kısmına ulaştığınızda, hareketi hızlı bir şekilde tersine çevirin ve gövdenizi sola döndürerek halteri yukarı ve vücudunuzun üzerinden sol omzunuza doğru sallayın. İstenilen sayıda tekrar için bu bükme hareketine tarafları değiştirerek devam edin.","es":"Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con ambas manos frente al pecho. Flexiona ligeramente las rodillas y rota el torso hacia la derecha, llevando la barra hacia la cadera derecha. Cuando llegues a la parte baja del movimiento, invierte rápidamente el movimiento y rota el torso hacia la izquierda, llevando la barra hacia arriba y a través del cuerpo en dirección al hombro izquierdo. Continúa este movimiento de giro, alternando lados, durante el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, и держите штангу обеими руками перед грудью. Слегка согните ноги в коленях и поверните туловище вправо, перемещая штангу вниз к правому бедру. Достигнув нижней точки движения, быстро поменяйте направление движения и поверните туловище влево, поднимая штангу вверх и поперек тела к левому плечу. Продолжайте это скручивающее движение, чередуя стороны, необходимое количество повторений.","zh":"双脚分开与肩同宽站立，双手握住杠铃于胸前。 稍微弯曲膝盖并将躯干向右旋转，将杠铃向下朝右臀部摆动。 当你到达动作的底部时，快速反向运动并向左旋转你的躯干，向上摆动杠铃并穿过你的身体朝向左肩。 继续这个扭转动作，两侧交替，达到所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और दोनों हाथों से बारबेल को अपनी छाती के सामने पकड़ें। अपने घुटनों को थोड़ा मोड़ें और अपने धड़ को दाईं ओर घुमाएं, बारबेल को अपने दाहिने कूल्हे की ओर झुकाएं। जैसे ही आप आंदोलन के निचले भाग पर पहुंचते हैं, गति को तुरंत उलट दें और अपने धड़ को बाईं ओर घुमाएं, बारबेल को ऊपर और अपने शरीर के पार अपने बाएं कंधे की ओर घुमाएं। दोहराव की वांछित संख्या के लिए, पक्षों को बदलते हुए, इस घुमाव गति को जारी रखें।","pl":"Stań ze stopami rozstawionymi na szerokość barków i trzymaj sztangę obiema dłońmi przed klatką piersiową. Ugnij lekko kolana i obróć tułów w prawo, opuszczając sztangę w kierunku prawego biodra. Osiągając dolną część ruchu, szybko odwróć ruch i obróć tułów w lewo, wymachując sztangą w górę i w poprzek ciała w stronę lewego barku. Kontynuuj ten ruch skrętny, zmieniając strony, zgodnie z zaplanowaną liczbą powtórzeń.","ko":"발을 어깨너비로 벌리고 선 자세에서 양손으로 바벨을 가슴 앞에 잡습니다. 무릎을 약간 구부리고 몸통을 오른쪽으로 회전시키면서 바벨을 오른쪽 엉덩이 쪽으로 아래로 스윙합니다. 동작의 맨 아래에 도달했을 때 빠르게 동작을 역으로 하여 몸통을 왼쪽으로 회전시키면서 바벨을 위로 스윙하고 몸을 가로질러 왼쪽 어깨 쪽으로 가져옵니다. 양쪽을 교대로 하는 이 비틀기 동작을 원하는 횟수만큼 계속합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules et tiens la barre à deux mains devant ta poitrine. Fléchis légèrement les genoux et fais pivoter ton torse vers la droite en balançant la barre vers ta hanche droite. Une fois au bas du mouvement, inverse rapidement le mouvement et pivote ton torse vers la gauche en balançant la barre vers le haut et en travers de ton corps vers ton épaule gauche. Continue ce mouvement de torsion en alternant les côtés, pour le nombre de répétitions souhaité."}'::jsonb, 'images/0562-QYysSLV.jpg', 'videos/0562-QYysSLV.gif', '© Gym visual — https://gymvisual.com/'),
(3237, 'landmine lateral raise', 'shoulders', 'strength', 'shoulders', 'barbell', 'traps', 'delts', '["traps","upper back"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart and knees slightly bent. Hold the barbell with an overhand grip, resting it on the front of your shoulders. Keeping your core engaged and back straight, lift the barbell up and away from your body, raising it to shoulder height. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.","it":"Stai in piedi con i piedi alla larghezza delle spalle e le ginocchia leggermente piegate. Tieni il bilanciere con una presa prona, appoggiandolo sulla parte anteriore delle spalle. Mantenendo il core impegnato e la schiena dritta, solleva il bilanciere verso l''alto e lontano dal corpo, sollevandolo all''altezza delle spalle. Fermati per un momento in alto, quindi abbassa lentamente il bilanciere nella posizione iniziale. Ripetere per il numero di ripetizioni desiderato.","tr":"Ayaklarınız omuz genişliğinde açık ve dizleriniz hafifçe bükülü şekilde ayakta durun. Halteri üstten kavrayarak tutun ve omuzlarınızın ön kısmına dayayın. Merkez bölgenizi meşgul ve sırtınızı düz tutarak halteri yukarı ve vücudunuzdan uzağa kaldırın ve omuz hizasına kadar kaldırın. Tepe noktasında bir süre duraklayın, ardından halteri yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra con un agarre prono, apoyándola en la parte delantera de los hombros. Manteniendo el core activado y la espalda recta, levanta la barra alejándola del cuerpo, elevándola hasta la altura del hombro. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч и слегка согнуты в коленях. Возьмите штангу хватом сверху, положив ее на переднюю часть плеч. Удерживая корпус напряженным и спину прямой, поднимите штангу вверх и в сторону от тела, подняв ее до уровня плеч. Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение. Повторите необходимое количество повторений.","zh":"站立，双脚分开与肩同宽，膝盖稍微弯曲。 正手握住杠铃，将其放在肩膀前面。 保持核心收紧并保持背部挺直，将杠铃向上举起并远离身体，将其提升至肩膀高度。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं। बारबेल को ओवरहैंड ग्रिप से पकड़ें, इसे अपने कंधों के सामने रखें। अपने कोर को व्यस्त रखते हुए और पीठ को सीधा रखते हुए, बारबेल को अपने शरीर से ऊपर और दूर उठाएं, इसे कंधे की ऊंचाई तक उठाएं। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań ze stopami rozstawionymi na szerokość barków i lekko ugiętymi kolanami. Trzymaj sztangę nachwytem, opierając ją na przedniej części barków. Utrzymując napięte mięśnie brzucha i proste plecy, unieś sztangę na zewnątrz od ciała, podnosząc ją na wysokość barków. Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść sztangę do pozycji wyjściowej. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"발을 어깨너비로 벌리고 무릎을 약간 구부린 자세에서 시작합니다. 손을 위로 향하게 하여 바벨을 잡고 어깨 앞에 얹습니다. 코어에 힘을 주고 등을 곧게 유지하면서 바벨을 몸에서 위로 들어올려 어깨 높이까지 올립니다. 맨 위에서 잠깐 멈춘 후 바벨을 천천히 시작 위치로 내립니다. 원하는 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules et les genoux légèrement fléchis. Tiens la barre en prise pronation, en la faisant reposer sur l''avant de tes épaules. En gardant ta sangle abdominale gainée et le dos droit, soulève la barre vers le haut et loin de ton corps, en la levant à hauteur d''épaule. Marque une pause en haut, puis abaisse lentement la barre pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/3237-eXMFHww.jpg', 'videos/3237-eXMFHww.gif', '© Gym visual — https://gymvisual.com/'),
(3300, 'lean planche', 'waist', 'strength', 'waist', 'body weight', 'shoulders', 'abs', '["shoulders","chest","triceps"]'::jsonb, '{"en":"Start in a push-up position with your hands shoulder-width apart and your body straight. Engage your core and slowly shift your weight forward, bringing your shoulders past your hands. Keep your elbows slightly bent and your body straight as you lean forward. Hold this position for a few seconds, then slowly return to the starting position. Repeat for the desired number of repetitions.","it":"Inizia in una posizione push-up con le mani alla larghezza delle spalle e il corpo dritto. Coinvolgi il tuo core e sposta lentamente il peso in avanti, portando le spalle oltre le mani. Tieni i gomiti leggermente piegati e il corpo dritto mentre ti pieghi in avanti. Mantieni questa posizione per alcuni secondi, quindi torna lentamente alla posizione di partenza. Ripetere per il numero di ripetizioni desiderato.","tr":"Elleriniz omuz genişliğinde açık ve vücudunuz düz olacak şekilde şınav pozisyonuna başlayın. Merkez bölgenizi devreye sokun ve ağırlığınızı yavaşça ileri doğru vererek omuzlarınızı ellerinizin üzerine getirin. Öne doğru eğilirken dirseklerinizi hafifçe bükülü ve vücudunuzu düz tutun. Bu pozisyonu birkaç saniye basılı tutun, ardından yavaşça başlangıç ​​​​pozisyonuna dönün. İstenilen sayıda tekrar için tekrarlayın.","es":"Comienza en una posición de flexión con las manos separadas a la altura de los hombros y el cuerpo recto. Activa el core y traslada lentamente el peso hacia adelante, llevando los hombros más allá de las manos. Mantén los codos ligeramente flexionados y el cuerpo recto mientras te inclinas hacia adelante. Mantén esta posición durante unos segundos, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.","ru":"Начните с позиции для отжиманий, поставив руки на ширине плеч и выпрямив тело. Напрягите корпус и медленно перенесите вес вперед, выводя плечи за руки. Держите локти слегка согнутыми, а тело прямым, наклоняясь вперед. Удерживайте это положение несколько секунд, затем медленно вернитесь в исходное положение. Повторите необходимое количество повторений.","zh":"从俯卧撑位置开始，双手分开与肩同宽，身体伸直。 启动你的核心，慢慢地将你的重心向前移动，让你的肩膀越过你的手。 向前倾时，保持肘部稍微弯曲，身体伸直。 保持这个姿势几秒钟，然后慢慢回到起始位置。 重复所需的重复次数。","hi":"अपने हाथों को कंधे की चौड़ाई पर अलग रखते हुए और अपने शरीर को सीधा रखते हुए पुश-अप स्थिति से शुरुआत करें। अपने कोर को संलग्न करें और धीरे-धीरे अपना वजन आगे बढ़ाएं, अपने कंधों को अपने हाथों से आगे लाएं। आगे की ओर झुकते समय अपनी कोहनियाँ थोड़ी मुड़ी हुई और शरीर सीधा रखें। कुछ सेकंड के लिए इस स्थिति में रहें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Zacznij w pozycji do pompki, dłonie rozstawione na szerokość barków, ciało proste. Napnij mięśnie brzucha i powoli przesuń ciężar ciała do przodu, przenosząc barki poza linię dłoni. Trzymaj łokcie lekko ugięte, a ciało proste, pochylając się do przodu. Przytrzymaj tę pozycję przez kilka sekund, a następnie powoli wróć do pozycji wyjściowej. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"푸시업 자세에서 시작하여 손을 어깨너비로 벌리고 몸을 곧게 유지합니다. 코어에 힘을 주고 천천히 무게를 앞으로 이동하면서 어깨를 손 너머로 가져옵니다. 팔꿈치를 약간 구부린 상태로 유지하고 몸을 곧게 유지하면서 앞으로 기울입니다. 이 자세를 몇 초간 유지한 후 천천히 시작 위치로 돌아옵니다. 원하는 횟수만큼 반복합니다.","fr":"Commence en position de pompe, les mains écartées à la largeur des épaules et le corps bien droit. Gaine ta sangle abdominale et déplace lentement ton poids vers l''avant, en amenant tes épaules au-delà de tes mains. Garde tes coudes légèrement fléchis et ton corps droit pendant que tu te penches vers l''avant. Maintiens cette position pendant quelques secondes, puis reviens lentement à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/3300-LYJodFS.jpg', 'videos/3300-LYJodFS.gif', '© Gym visual — https://gymvisual.com/'),
(2271, 'left hook. boxing', 'shoulders', 'strength', 'shoulders', 'body weight', 'biceps', 'delts', '["biceps","triceps","forearms"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart and your knees slightly bent. Keep your left hand up to protect your face and your right hand by your chin. Rotate your hips and pivot on your left foot as you extend your left arm forward in a punching motion. Twist your torso and engage your core muscles to generate power in the punch. Snap your arm back to the starting position and repeat for the desired number of repetitions.","it":"Stai con i piedi alla larghezza delle spalle e le ginocchia leggermente piegate. Tieni la mano sinistra alzata per proteggere il viso e la mano destra vicino al mento. Ruota i fianchi e fai perno sul piede sinistro mentre estendi il braccio sinistro in avanti con un movimento di pugno. Ruota il busto e coinvolgi i muscoli centrali per generare potenza nel pugno. Riporta il braccio nella posizione iniziale e ripeti per il numero di ripetizioni desiderato.","tr":"Ayaklarınız omuz genişliğinde açık ve dizleriniz hafifçe bükülü şekilde ayakta durun. Yüzünüzü korumak için sol elinizi yukarıda, sağ elinizi ise çenenizden tutun. Sol kolunuzu yumruklama hareketiyle ileri doğru uzatırken kalçalarınızı döndürün ve sol ayağınızın üzerinde dönün. Yumrukta güç üretmek için gövdenizi çevirin ve göbek kaslarınızı çalıştırın. Kolunuzu başlangıç ​​pozisyonuna geri getirin ve istediğiniz tekrar sayısı kadar tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Mantén la mano izquierda arriba para proteger el rostro y la mano derecha junto a la barbilla. Rota las caderas y pívota sobre el pie izquierdo mientras extiendes el brazo izquierdo hacia adelante con un movimiento de golpe. Gira el torso y activa los músculos del core para generar potencia en el golpe. Lleva el brazo rápidamente de vuelta a la posición inicial y repite el número de repeticiones deseado.","ru":"Встаньте, поставив ноги на ширине плеч и слегка согнув колени. Держите левую руку вверх, чтобы защитить лицо, а правую руку — под подбородок. Вращайте бедра и поворачивайтесь на левой ноге, одновременно вытягивая левую руку вперед для ударного движения. Поверните туловище и задействуйте мышцы корпуса, чтобы генерировать силу удара. Верните руку в исходное положение и повторите желаемое количество повторений.","zh":"双脚分开与肩同宽站立，膝盖稍微弯曲。 左手举起以保护脸部，右手握住下巴。 旋转臀部并以左脚为轴心，同时以出拳动作向前伸展左臂。 扭转你的躯干并调动你的核心肌肉以产生出拳的力量。 将手臂拉回到起始位置，然后重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों। अपने चेहरे की सुरक्षा के लिए अपने बाएँ हाथ को ऊपर रखें और अपने दाहिने हाथ को अपनी ठुड्डी के पास रखें। अपने कूल्हों को घुमाएँ और अपने बाएँ पैर को मोड़ें क्योंकि आप अपने बाएँ हाथ को मुक्का मारने की गति में आगे बढ़ाते हैं। अपने धड़ को मोड़ें और मुक्के में शक्ति उत्पन्न करने के लिए अपनी मुख्य मांसपेशियों को शामिल करें। अपने हाथ को वापस प्रारंभिक स्थिति में लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।","pl":"Stań ze stopami rozstawionymi na szerokość barków i lekko ugiętymi kolanami. Trzymaj lewą rękę uniesioną, chroniąc twarz, a prawą rękę przy brodzie. Obróć biodra i wykonaj pivot na lewej stopie, wyprostowując lewą rękę do przodu ruchem uderzenia. Skręć tułów i napnij mięśnie brzucha, aby wygenerować siłę w uderzeniu. Szybko cofnij rękę do pozycji wyjściowej i powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"어깨 너비만큼 발을 벌리고 무릎을 약간 구부린 상태에서 선다. 왼손을 얼굴 보호를 위해 올려 놓고 오른손을 턱 옆에 위치시킨다. 왼발을 축으로 회전하며 왼팔을 펀칭 동작으로 앞으로 뻗어낸다. 몸통을 비틀어 코어 근육을 활성화하여 펀칭의 파워를 생성한다. 팔을 재빠르게 시작 위치로 되돌리고 원하는 횟수만큼 반복한다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules et les genoux légèrement fléchis. Garde la main gauche levée pour protéger ton visage et la main droite près du menton. Fais pivoter tes hanches et pivote sur ton pied gauche en étendant ton bras gauche vers l''avant dans un mouvement de coup de poing. Fais pivoter ton torse et gaine les muscles de ta sangle abdominale pour générer de la puissance dans le coup de poing. Ramène ton bras d''un coup sec à la position de départ et répète pour le nombre de répétitions souhaité."}'::jsonb, 'images/2271-hoXt6wv.jpg', 'videos/2271-hoXt6wv.gif', '© Gym visual — https://gymvisual.com/'),
(570, 'leg pull in flat bench', 'waist', 'strength', 'waist', 'body weight', 'hip flexors', 'abs', '["hip flexors","lower back"]'::jsonb, '{"en":"Sit on a flat bench with your legs extended straight out in front of you. Place your hands on the bench beside your hips for support. Engage your abs and lift your legs off the ground, bringing your knees towards your chest. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.","it":"Siediti su una panca piana con le gambe distese davanti a te. Metti le mani sulla panca accanto ai fianchi per supporto. Contrai gli addominali e solleva le gambe da terra, portando le ginocchia verso il petto. Fai una pausa per un momento in alto, quindi abbassa lentamente le gambe fino alla posizione di partenza. Ripetere per il numero di ripetizioni desiderato.","tr":"Bacaklarınızı düz bir şekilde önünüze uzatacak şekilde düz bir bankta oturun. Destek için ellerinizi kalçalarınızın yanındaki sehpaya yerleştirin. Karın kaslarınızı devreye sokun ve bacaklarınızı yerden kaldırın, dizlerinizi göğsünüze doğru getirin. Tepe noktasında bir an duraklayın, ardından bacaklarınızı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Siéntate en un banco plano con las piernas extendidas rectas hacia adelante. Coloca las manos en el banco junto a las caderas para mayor apoyo. Activa el abdomen y levanta las piernas del suelo, llevando las rodillas hacia el pecho. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Сядьте на ровную скамью, вытянув ноги прямо перед собой. Положите руки на скамью рядом с бедрами для поддержки. Напрягите пресс и поднимите ноги от земли, подтягивая колени к груди. Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение. Повторите необходимое количество повторений.","zh":"坐在平坦的长凳上，双腿在身前伸直。 将双手放在臀部旁边的长凳上以获得支撑。 收紧腹肌，将双腿抬离地面，使膝盖靠近胸部。 在顶部暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को अपने सामने सीधा फैलाकर एक सपाट बेंच पर बैठें। समर्थन के लिए अपने हाथों को अपने कूल्हों के पास बेंच पर रखें। अपने पेट को संलग्न करें और अपने पैरों को जमीन से ऊपर उठाएं, अपने घुटनों को अपनी छाती की ओर लाएं। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Usiądź na płaskiej ławce z nogami wyprostowanymi prosto przed sobą. Umieść dłonie na ławce obok bioder dla wsparcia. Napnij mięśnie brzucha i unieś nogi nad podłogę, przyciągając kolana w stronę klatki piersiowej. Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść nogi do pozycji wyjściowej. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"플랫 벤치에 앉아 다리를 앞으로 뻗는다. 엉덩이 옆 벤치에 손을 올려 안정성을 확보한다. 복부 근육을 활성화하고 다리를 바닥에서 들어 올려 무릎을 가슴 쪽으로 당긴다. 상단 위치에서 잠시 멈춘 후, 천천히 다리를 시작 위치로 내린다. 원하는 횟수만큼 반복한다.","fr":"Assieds-toi sur un banc plat, les jambes tendues droit devant toi. Place tes mains sur le banc à côté de tes hanches pour le soutien. Gaine tes abdominaux et lève tes jambes du sol, en amenant tes genoux vers ta poitrine. Marque une pause en haut, puis abaisse lentement tes jambes pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0570-OyoZ3Pu.jpg', 'videos/0570-OyoZ3Pu.gif', '© Gym visual — https://gymvisual.com/'),
(1576, 'leg up hamstring stretch', 'upper legs', 'strength', 'upper legs', 'body weight', 'glutes', 'hamstrings', '["glutes"]'::jsonb, '{"en":"Lie flat on your back with your legs extended. Bend one knee and bring it towards your chest, holding onto your thigh or shin. Straighten your leg as much as possible while keeping it elevated. Hold the stretch for 20-30 seconds. Repeat with the other leg.","it":"Sdraiati sulla schiena con le gambe distese. Piega un ginocchio e portalo verso il petto, tenendoti sulla coscia o sullo stinco. Raddrizza la gamba il più possibile mantenendola sollevata. Mantieni l''allungamento per 20-30 secondi. Ripeti con l''altra gamba.","tr":"Bacaklarınızı uzatarak sırt üstü düz bir şekilde uzanın. Bir dizinizi bükün ve kalçanıza veya kaval kemiğinize tutunarak göğsünüze doğru getirin. Bacağınızı yüksekte tutarak mümkün olduğunca düzleştirin. Uzatmayı 20-30 saniye kadar tutun. Diğer bacakla tekrarlayın.","es":"Túmbate boca arriba con las piernas extendidas. Flexiona una rodilla y llévala hacia el pecho, sujetándote del muslo o la espinilla. Endereza la pierna tanto como sea posible mientras la mantienes elevada. Mantén el estiramiento durante 20-30 segundos. Repite con la otra pierna.","ru":"Лягте на спину, вытянув ноги. Согните одно колено и поднесите его к груди, держась за бедро или голень. Максимально выпрямите ногу, удерживая ее в приподнятом положении. Удерживайте растяжку 20–30 секунд. Повторите с другой ногой.","zh":"平躺，双腿伸展。 弯曲一侧膝盖，将其靠近胸部，握住大腿或小腿。 尽可能伸直腿，同时保持腿抬高。 保持拉伸 20-30 秒。 换另一条腿重复上述步骤。","hi":"अपने पैरों को फैलाकर अपनी पीठ के बल सीधे लेट जाएँ। एक घुटने को मोड़ें और अपनी जांघ या पिंडली को पकड़ते हुए इसे अपनी छाती की ओर लाएँ। अपने पैर को ऊंचा रखते हुए जितना संभव हो उतना सीधा करें। 20-30 सेकंड तक खिंचाव बनाए रखें। दूसरे पैर से दोहराएँ।","pl":"Połóż się płasko na plecach z nogami wyprostowanymi. Ugnij jedno kolano i przyciągnij je w stronę klatki piersiowej, trzymając za udo lub podudzie. Wyprostuj nogę tak bardzo, jak to możliwe, utrzymując ją uniesioną. Przytrzymaj rozciąganie przez 20-30 sekund. Powtórz drugą nogą.","ko":"등을 대고 누워 다리를 펼친다. 한쪽 무릎을 구부려 가슴 쪽으로 가져오고, 허벅지나 종아리를 잡는다. 다리를 들어올린 상태로 가능한 한 많이 펼친다. 20~30초간 스트레칭을 유지한다. 반대쪽 다리로 반복한다.","fr":"Allonge-toi sur le dos, les jambes tendues. Plie un genou et amène-le vers ta poitrine en tenant ta cuisse ou ton tibia. Tends la jambe autant que possible tout en la gardant surélevée. Maintiens l''étirement pendant 20 à 30 secondes. Répète avec l''autre jambe."}'::jsonb, 'images/1576-sU5BrfP.jpg', 'videos/1576-sU5BrfP.gif', '© Gym visual — https://gymvisual.com/'),
(2287, 'lever alternate leg press', 'upper legs', 'strength', 'upper legs', 'leverage machine', 'hamstrings', 'quads', '["hamstrings","glutes"]'::jsonb, '{"en":"Adjust the seat and foot platform of the leverage machine to your desired position. Sit on the machine with your back against the backrest and your feet on the foot platform. Place your hands on the handles or sides of the machine for stability. Push one foot against the foot platform, extending your leg until it is almost fully straight. Pause for a moment, then slowly bend your leg and return to the starting position. Repeat with the other leg. Continue alternating legs for the desired number of repetitions.","it":"Regola il sedile e la pedana della macchina con leva nella posizione desiderata. Sedersi sulla macchina con la schiena contro lo schienale e i piedi sulla pedana. Metti le mani sulle maniglie o sui lati della macchina per stabilità. Spingere un piede contro la pedana, estendendo la gamba finché non è quasi completamente diritta. Fai una pausa per un momento, poi piega lentamente la gamba e torna alla posizione di partenza. Ripeti con l''altra gamba. Continua ad alternare le gambe per il numero di ripetizioni desiderato.","tr":"Kaldıraç makinesinin oturma yerini ve ayak platformunu istediğiniz pozisyona ayarlayın. Sırtınız koltuk arkalığına dayalı ve ayaklarınız ayak platformu üzerinde olacak şekilde makinenin üzerine oturun. Dengeyi sağlamak için ellerinizi makinenin kollarına veya yanlarına yerleştirin. Bir ayağınızı ayak platformuna doğru itin ve bacağınızı neredeyse tamamen düz olana kadar uzatın. Bir an duraklayın, ardından bacağınızı yavaşça bükün ve başlangıç ​​pozisyonuna dönün. Diğer bacakla tekrarlayın. İstenilen sayıda tekrar için bacakları değiştirerek devam edin.","es":"Ajusta el asiento y la plataforma para los pies de la máquina de palanca a la posición deseada. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre la plataforma para los pies. Coloca las manos en las asas o en los lados de la máquina para mayor estabilidad. Empuja un pie contra la plataforma para los pies, extendiendo la pierna hasta que esté casi completamente recta. Haz una pausa breve, luego flexiona lentamente la pierna y vuelve a la posición inicial. Repite con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.","ru":"Отрегулируйте сиденье и платформу для ног рычажной машины в желаемое положение. Сядьте на тренажер, прислонившись спиной к спинке и поставив ноги на платформу для ног. Положите руки на ручки или по бокам машины для устойчивости. Упритесь одной ногой в платформу для ног, вытягивая ногу до тех пор, пока она не станет почти полностью прямой. Сделайте паузу на мгновение, затем медленно согните ногу и вернитесь в исходное положение. Повторите с другой ногой. Продолжайте чередовать ноги желаемое количество повторений.","zh":"将杠杆机的座椅和脚踏平台调整到您想要的位置。 坐在机器上，背部靠在靠背上，双脚放在脚踏板上。 将手放在机器的手柄或侧面以保持稳定性。 将一只脚推到脚平台上，伸展腿直到几乎完全伸直。 暂停片刻，然后慢慢弯曲腿，回到起始位置。 换另一条腿重复上述步骤。 继续交替双腿达到所需的重复次数。","hi":"लीवरेज मशीन की सीट और फुट प्लेटफॉर्म को अपनी इच्छित स्थिति में समायोजित करें। मशीन पर अपनी पीठ बैकरेस्ट से सटाकर और अपने पैरों को फुट प्लेटफॉर्म पर रखकर बैठें। स्थिरता के लिए अपने हाथों को मशीन के हैंडल या किनारों पर रखें। एक पैर को पैर के प्लेटफॉर्म पर दबाएं, अपने पैर को तब तक फैलाएं जब तक वह लगभग पूरी तरह से सीधा न हो जाए। एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैर को मोड़ें और प्रारंभिक स्थिति में लौट आएं। दूसरे पैर से दोहराएँ। पुनरावृत्ति की वांछित संख्या के लिए पैरों को बारी-बारी से जारी रखें।","pl":"Wyreguluj siedzisko i platformę na stopy maszyny dźwigniowej do żądanej pozycji. Usiądź na maszynie, opierając plecy o oparcie, a stopy na platformie. Umieść dłonie na uchwytach lub bokach maszyny dla stabilizacji. Naciśnij jedną stopą platformę, prostując nogę niemal do końca. Zatrzymaj się na chwilę, a następnie powoli ugnij nogę i wróć do pozycji wyjściowej. Powtórz drugą nogą. Kontynuuj naprzemienne wykonywanie ruchu zgodnie z zaplanowaną liczbą powtórzeń.","ko":"레버 머신의 시트와 발판을 원하는 위치에 조정한다. 머신에 앉아 등을 등받이에 기대고 발을 발판에 올린다. 안정성을 위해 손잡이나 머신 옆을 잡는다. 한쪽 발로 발판을 밀어 다리를 거의 완전히 펼칠 때까지 누른다. 잠시 멈춘 후, 천천히 다리를 구부려 시작 위치로 돌아온다. 반대쪽 다리로 반복한다. 원하는 횟수만큼 양쪽 다리를 교대로 반복한다.","fr":"Règle le siège et la plateforme pour pieds de la machine à levier dans la position souhaitée. Assieds-toi sur la machine, le dos contre le dossier et les pieds sur la plateforme de pied. Place tes mains sur les poignées ou les côtés de la machine pour plus de stabilité. Pousse un pied contre la plateforme repose-pieds en étendant ta jambe jusqu''à ce qu''elle soit presque complètement tendue. Marque une pause, puis plie lentement ta jambe et reviens à la position de départ. Répète avec l''autre jambe. Continue à alterner les jambes pour le nombre de répétitions souhaité."}'::jsonb, 'images/2287-V07qpXy.jpg', 'videos/2287-V07qpXy.gif', '© Gym visual — https://gymvisual.com/'),
(571, 'lever alternating narrow grip seated row', 'back', 'strength', 'back', 'leverage machine', 'biceps', 'upper back', '["biceps","forearms"]'::jsonb, '{"en":"Adjust the seat height and footplate position to ensure proper alignment. Sit on the machine with your back straight and feet flat on the footplate. Grasp the handles with a narrow grip, palms facing each other. Keep your chest up and shoulders back throughout the exercise. Pull one handle towards your torso while keeping the other handle stationary. Squeeze your shoulder blades together at the end of the movement. Slowly return the handle to the starting position and repeat with the other side. Continue alternating sides for the desired number of repetitions.","it":"Regolare l''altezza del sedile e la posizione della pedana per garantire il corretto allineamento. Sedersi sulla macchina con la schiena dritta e i piedi appoggiati sulla pedana. Afferrare le maniglie con una presa stretta, i palmi rivolti l''uno verso l''altro. Tieni il petto in alto e le spalle indietro durante l''esercizio. Tirare una maniglia verso il busto mantenendo l''altra maniglia ferma. Stringi insieme le scapole alla fine del movimento. Riporta lentamente la maniglia nella posizione iniziale e ripeti con l''altro lato. Continua ad alternare i lati per il numero di ripetizioni desiderato.","tr":"Doğru hizalamayı sağlamak için koltuk yüksekliğini ve ayak plakası konumunu ayarlayın. Sırtınız düz ve ayaklarınız taban plakası üzerinde düz olacak şekilde makinenin üzerine oturun. Avuç içleri birbirine bakacak şekilde tutamakları dar bir tutuşla kavrayın. Egzersiz boyunca göğsünüzü yukarıda ve omuzlarınızı geride tutun. Bir kolu gövdenize doğru çekerken diğer kolu sabit tutun. Hareketin sonunda kürek kemiklerinizi birbirine doğru sıkın. Kolu yavaşça başlangıç ​​pozisyonuna getirin ve hareketi diğer tarafla tekrarlayın. İstenilen tekrar sayısı için alternatif taraflara devam edin.","es":"Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta. Siéntate en la máquina con la espalda recta y los pies planos sobre la placa para los pies. Sujeta las asas con un agarre estrecho, con las palmas una frente a la otra. Mantén el pecho elevado y los hombros hacia atrás durante todo el ejercicio. Tira de una asa hacia el torso mientras mantienes la otra asa inmóvil. Aprieta los omóplatos al final del movimiento. Devuelve lentamente el asa a la posición inicial y repite con el otro lado. Continúa alternando lados durante el número de repeticiones deseado.","ru":"Отрегулируйте высоту сиденья и положение подножки, чтобы обеспечить правильное выравнивание. Сядьте на тренажер, выпрямив спину и положив ступни на подножку. Возьмитесь за ручки узким хватом, ладони обращены друг к другу. На протяжении всего упражнения держите грудь поднятой, а плечи отведенными назад. Потяните одну ручку к туловищу, удерживая другую ручку неподвижной. В конце движения сведите лопатки вместе. Медленно верните ручку в исходное положение и повторите то же самое с другой стороны. Продолжайте чередовать стороны желаемое количество повторений.","zh":"调整座椅高度和踏板位置以确保正确对齐。 坐在机器上，背部挺直，双脚平放在踏板上。 紧紧握住手柄，手掌相对。 在整个练习过程中保持挺胸、肩膀向后。 将一个手柄拉向您的躯干，同时保持另一个手柄静止。 在动作结束时将肩胛骨挤压在一起。 慢慢地将手柄返回到起始位置，并在另一侧重复此操作。 继续交替进行所需的重复次数。","hi":"उचित संरेखण सुनिश्चित करने के लिए सीट की ऊंचाई और फ़ुटप्लेट की स्थिति को समायोजित करें। अपनी पीठ सीधी करके और पैरों को फ़ुटप्लेट पर सपाट करके मशीन पर बैठें। हैंडल को पतली पकड़ से पकड़ें, हथेलियाँ एक दूसरे के सामने हों। पूरे अभ्यास के दौरान अपनी छाती ऊपर और कंधे पीछे रखें। एक हैंडल को अपने धड़ की ओर खींचें जबकि दूसरे हैंडल को स्थिर रखें। आंदोलन के अंत में अपने कंधे के ब्लेड को एक साथ निचोड़ें। धीरे-धीरे हैंडल को शुरुआती स्थिति में लौटाएं और दूसरी तरफ से दोहराएं। दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।","pl":"Wyreguluj wysokość siedziska i pozycję podpórki na stopy, aby zapewnić właściwe ustawienie ciała. Usiądź na maszynie z prostymi plecami i stopami płasko opartymi o podpórkę. Chwyć uchwyty wąskim chwytem, dłonie zwrócone do siebie. Utrzymuj uniesioną klatkę piersiową i cofnięte barki przez cały czas trwania ćwiczenia. Podciągnij jeden uchwyt w stronę tułowia, utrzymując drugi uchwyt nieruchomo. Ściśnij łopatki na końcu ruchu. Powoli wróć uchwytem do pozycji wyjściowej i powtórz po drugiej stronie. Kontynuuj naprzemienne wykonywanie ruchu zgodnie z zaplanowaną liczbą powtórzeń.","ko":"시트의 높이와 발판의 위치를 조정하여 적절한 정렬을 확보한다. 머신에 앉아 등을 펴고 발을 발판에 편다. 좁은 그립으로 손잡이를 잡고 손바닥이 서로 마주보게 한다. 운동 내내 가슴을 세우고 어깨를 뒤로 유지한다. 한쪽 손잡이를 몸통 쪽으로 당기고 다른 쪽은 그대로 유지한다. 스트로크의 끝에서 견갑골을 모아 쥔다. 천천히 손잡이를 시작 위치로 돌려 놓고 반대쪽으로 반복한다. 원하는 횟수만큼 양쪽을 교대로 반복한다.","fr":"Règle la hauteur du siège et la position du repose-pieds pour garantir un bon alignement. Assieds-toi sur la machine, le dos droit et les pieds à plat sur la plaque de pied. Saisis les poignées avec une prise serrée, les paumes tournées l''une vers l''autre. Garde la poitrine relevée et les épaules en arrière tout au long de l''exercice. Tire une poignée vers ton torse tout en gardant l''autre poignée immobile. Contracte tes omoplates l''une vers l''autre à la fin du mouvement. Ramène lentement la poignée à la position de départ et répète de l''autre côté. Continue à alterner les côtés pour le nombre de répétitions souhaité."}'::jsonb, 'images/0571-w2oRpuH.jpg', 'videos/0571-w2oRpuH.gif', '© Gym visual — https://gymvisual.com/'),
(572, 'lever assisted chin-up', 'back', 'strength', 'back', 'leverage machine', 'biceps', 'lats', '["biceps","forearms"]'::jsonb, '{"en":"Adjust the leverage machine to your desired resistance level. Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart. Hang with your arms fully extended, keeping your body straight. Engage your back muscles and pull your body up towards the handles, leading with your chest. Continue pulling until your chin is above the handles. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.","it":"Regola la macchina con leva al livello di resistenza desiderato. Stare sulla pedana e afferrare le maniglie con una presa prona, leggermente più larghe della larghezza delle spalle. Appendere con le braccia completamente distese, mantenendo il corpo dritto. Coinvolgi i muscoli della schiena e solleva il corpo verso le maniglie, guidando con il petto. Continua a tirare finché il mento non è sopra le maniglie. Fai una pausa per un momento in alto, quindi abbassa lentamente il corpo fino alla posizione di partenza. Ripetere per il numero di ripetizioni desiderato.","tr":"Kaldıraç makinesini istediğiniz direnç seviyesine ayarlayın. Ayak platformunun üzerinde durun ve kolları omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayarak tutun. Kollarınızı tamamen uzatarak, vücudunuzu düz tutarak asın. Sırt kaslarınızı devreye sokun ve vücudunuzu göğsünüzle birlikte tutacaklara doğru yukarı çekin. Çeneniz tutamakların üzerine gelene kadar çekmeye devam edin. Tepe noktasında bir an duraklayın, ardından vücudunuzu yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ajusta la máquina de palanca al nivel de resistencia deseado. Sube a la plataforma para los pies y agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Cuélgate con los brazos completamente extendidos, manteniendo el cuerpo recto. Activa los músculos de la espalda y tira del cuerpo hacia arriba en dirección a las asas, liderando con el pecho. Continúa subiendo hasta que la barbilla quede por encima de las agarraderas. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Отрегулируйте рычаг тренажера до желаемого уровня сопротивления. Встаньте на платформу для ног и возьмитесь за рукоятки хватом сверху, на расстоянии чуть шире плеч. Висите, полностью вытянув руки, сохраняя тело прямым. Задействуйте мышцы спины и подтяните тело вверх к ручкам, ведя грудью. Продолжайте тянуть, пока подбородок не окажется над ручками. Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение. Повторите необходимое количество повторений.","zh":"将杠杆机调整至您想要的阻力水平。 站在脚踏板上，正手握住手柄，握距略宽于肩宽。 双臂完全伸展，保持身体挺直。 收紧背部肌肉，将身体拉向手柄，以胸部为主导。 继续拉，直到下巴位于手柄上方。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。","hi":"लीवरेज मशीन को अपने वांछित प्रतिरोध स्तर पर समायोजित करें। फुट प्लेटफॉर्म पर खड़े हो जाएं और हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें। अपने शरीर को सीधा रखते हुए, अपनी बाहों को पूरी तरह फैलाकर लटकें। अपनी पीठ की मांसपेशियों को शामिल करें और अपने शरीर को अपनी छाती की ओर ले जाते हुए हैंडल की ओर ऊपर खींचें। तब तक खींचते रहें जब तक आपकी ठुड्डी हैंडल के ऊपर न आ जाए। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Wyreguluj maszynę dźwigniową do żądanego poziomu obciążenia asekuracyjnego. Stań na platformie na stopy i chwyć uchwyty nachwytem, nieco szerzej niż szerokość barków. Zwiśnij z całkowicie wyprostowanymi ramionami, utrzymując proste ciało. Napnij mięśnie pleców i podciągnij ciało w stronę uchwytów, prowadząc klatką piersiową. Kontynuuj podciąganie, aż broda znajdzie się nad uchwytami. Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść ciało do pozycji wyjściowej. Powtórz zgodnie z zaplanowaną liczbą powtórzeń.","ko":"레버 머신을 원하는 저항 수준으로 조정한다. 발판에 서서 오버핸드 그립으로 손잡이를 잡고, 손잡이는 어깨 너비보다 약간 넓게 벌린다. 팔을 완전히 펼친 채로 몸을 곧게 유지하며 매달린다. 등 근육을 활성화하고 가슴을 먼저 이끌며 몸을 손잡이 쪽으로 당겨 올린다. 턱이 손잡이 위로 올 때까지 계속 당긴다. 상단에서 잠시 멈춘 후, 천천히 몸을 시작 위치로 내린다. 원하는 횟수만큼 반복한다.","fr":"Règle la machine à levier au niveau de résistance souhaité. Tiens-toi sur la plateforme pour les pieds et saisis les poignées en prise pronation, légèrement plus écartées que la largeur des épaules. Suspends-toi, les bras complètement étendus, en gardant le corps droit. Sollicite les muscles de ton dos et tire ton corps vers les poignées, en menant avec ta poitrine. Continue à tirer jusqu''à ce que ton menton soit au-dessus des poignées. Marque une pause en haut, puis abaisse lentement ton corps pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0572-MaMuGH6.jpg', 'videos/0572-MaMuGH6.gif', '© Gym visual — https://gymvisual.com/')
